INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "警察、海关等为查找可疑物或人而进行搜查。", "primary_collocate": null, "pronunciation": "sōu", "ipa": "soʊ̯⁵⁵", "syllable_count": 1, "sentences": [{"text": "警察搜了他的房间，找到了证据。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员要搜我的行李。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在山上搜了三天，终于找到了人。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搜了整栋楼，没有发现可疑的人。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把汽车里里外外搜了一遍。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安要搜每个进门的人的包。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方搜过这个地方，什么也没找到。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师搜了学生的书包，发现了手机。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在他家搜出了一把刀。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搜了每间屋子，想找那个逃犯。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜了", "label": "体标（了）"}, {"form": "搜过", "label": "体标（过）"}, {"form": "搜着", "label": "体标（着）"}, {"form": "搜搜", "label": "重叠"}], "register": "中性", "sense_fingerprint": "警察、海关等为查找可疑物或人而搜查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搜", "is_correct": true, "explanation": "搜：为查找证据而仔细搜查，与“找到了证据”相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂抹墙面，不表示搜查，与“找到了证据”不符。"}, {"text": "布置", "is_correct": false, "explanation": "语义：“布置”指陈设、安排，与为找证据而进行的搜查无关。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于花果、树叶，不能说“摘他的房间”。"}], "explanations": {"搜": "搜：为查找证据而仔细搜查，与“找到了证据”相符。", "粉刷": "语义：“粉刷”指涂抹墙面，不表示搜查，与“找到了证据”不符。", "布置": "语义：“布置”指陈设、安排，与为找证据而进行的搜查无关。", "摘": "搭配：“摘”用于花果、树叶，不能说“摘他的房间”。"}, "sentence_index": 0, "correct_answer": "搜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察仔细搜这起案子。", "explanation": "这里应该用〈调查〉。搜指在具体地点一处一处地找，不用于抽象的案件。"}, {"text": "我在网上搜了一下酒店的价格。", "explanation": "这里“搜”是网络检索信息的义项，与“为查找可疑物而搜查”不同。"}, {"text": "他们搜了这件事的真相。", "explanation": "这里应该用〈追查〉。搜是具体翻找的动作，不能用于抽象的真相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搜", "is_correct": true, "explanation": "搜：为查找可疑物而搜查，与“什么也没找到”相符。"}, {"text": "修缮", "is_correct": false, "explanation": "语义：“修缮”指修理保养，与“什么也没找到”的查找不符。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂抹墙面，不表示搜查。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”多用于树木、物体，不能说“砍过这个地方”。"}], "explanations": {"搜": "搜：为查找可疑物而搜查，与“什么也没找到”相符。", "修缮": "语义：“修缮”指修理保养，与“什么也没找到”的查找不符。", "粉刷": "语义：“粉刷”指涂抹墙面，不表示搜查。", "砍": "搭配：“砍”多用于树木、物体，不能说“砍过这个地方”。"}, "sentence_index": 6, "correct_answer": "搜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在网上搜了一下这家饭店的地址。", "explanation": "这里“搜”是网上检索信息的义项，与本条“警察、海关等搜查可疑物或人”不同。"}, {"text": "我在抽屉里搜了半天，想找我的眼镜。", "explanation": "这里“搜”是自己在某处仔细翻找东西的义项，并非警察、海关等为查找可疑物而进行的搜查。"}, {"text": "他一直在搜出路。", "explanation": "这里应该用〈寻找〉。搜是具体翻找的动作，不能用于抽象的出路，抽象的寻求要用寻找。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察在那间屋子里搜出了了一张照片。", "corrected_sentence": "警察在那间屋子里搜出了一张照片。", "error_description": "“搜出”后已有“了”，又多加了一个“了”，重复；应只保留一个“了”，写作“搜出了一张照片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察在那间屋子里搜了出了线索。", "corrected_sentence": "警察在那间屋子里搜出了线索。", "error_description": "错误在于多出一个“了”，放在了“搜”和“出”之间。“搜出”是结果补语，“了”只放在“搜出”之后即可，应写作“搜出了线索”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
