INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "夜晚睡觉前互相致意的问候语。", "primary_collocate": null, "pronunciation": "wǎn ān", "ipa": "wan˨˩˦ an˥˥", "syllable_count": 2, "sentences": [{"text": "“晚安！”妈妈说，“明天见。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们，晚安，明天见！", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“晚安，好梦！”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，她给我发了一句“晚安”。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“晚安，宝贝！”爸爸关上了灯。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一点了，我先睡了，大家晚安！", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里，他轻轻地说：“晚安，早点睡。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“晚安！”我挥挥手，回房间去了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“晚安，同学们，明天见。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在朋友圈写了一句“晚安”，就睡了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "夜晚睡前互相致意的问候语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早安", "is_correct": false, "explanation": "语义：早安是早上的问候，与“晚安！”的睡前语境不符。"}, {"text": "午安", "is_correct": false, "explanation": "语义：午安是中午的问候，与妈妈说“明天见”的睡前语境不符。"}, {"text": "你好", "is_correct": false, "explanation": "语义：“你好”是见面时的问候，与“明天见”的道别语境不合，不是睡前互相致意的用语。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：晚安是夜晚睡前互相致意的问候语，与后文“明天见”呼应。"}], "explanations": {"早安": "语义：早安是早上的问候，与“晚安！”的睡前语境不符。", "午安": "语义：午安是中午的问候，与妈妈说“明天见”的睡前语境不符。", "你好": "语义：“你好”是见面时的问候，与“明天见”的道别语境不合，不是睡前互相致意的用语。", "晚安": "正确：晚安是夜晚睡前互相致意的问候语，与后文“明天见”呼应。"}, "sentence_index": 0, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上午十点开会时，她说了一句晚安。", "explanation": "这里应该用〈大家好〉。开会时的问候要说“大家好”，“晚安”只用于夜晚睡前。"}, {"text": "早上她向我说了一句晚安。", "explanation": "这里应该用〈早安〉。早上的问候要用“早安”，“晚安”只用于夜晚睡前。"}, {"text": "见面时她向我说了一句晚安。", "explanation": "这里应该用〈你好〉。见面要说“你好”，“晚安”只用于夜晚睡前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "您好", "is_correct": false, "explanation": "语域：对家人说“您好”过于客气，与睡前的口语语境不符。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：早上好是早上的问候，与“早点睡”的睡前语境矛盾。"}, {"text": "大家好", "is_correct": false, "explanation": "语义：大家好是见面问候，与“早点睡”的语境不合。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：晚安是睡前致意的问候语，与“早点睡”呼应。"}], "explanations": {"您好": "语域：对家人说“您好”过于客气，与睡前的口语语境不符。", "早上好": "语义：早上好是早上的问候，与“早点睡”的睡前语境矛盾。", "大家好": "语义：大家好是见面问候，与“早点睡”的语境不合。", "晚安": "正确：晚安是睡前致意的问候语，与“早点睡”呼应。"}, "sentence_index": 6, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动会开幕式上，队长对我们说了一句晚安。", "explanation": "这里应该用〈加油〉。运动会上为选手鼓劲要说“加油”，“晚安”只用于睡前问候。"}, {"text": "中午她向我说了一句晚安。", "explanation": "这里应该用〈午安〉。中午的问候要说“午安”，“晚安”只用于夜晚。"}, {"text": "晚会开始时她向大家说了一句晚安。", "explanation": "这里应该用〈晚上好〉。晚会开始时的问候是“晚上好”，“晚安”只用于睡前道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在门口轻轻说了一张“晚安”。", "corrected_sentence": "妈妈在门口轻轻说了一句“晚安”。", "error_description": "量词错误：“晚安”是一句话，量词应用“句”，“张”用于纸等平的东西。正确说法是“一句晚安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对她说：“晚安着！”", "corrected_sentence": "我对她说：“晚安！”", "error_description": "体标错误：“着”只能附在动词或形容词之后，固定问候语“晚安”不能带“着”，应直接说“晚安！”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
