INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93927, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "正着是朝对的方向，不是倒过来的。", "primary_collocate": null, "pronunciation": "zhèng zhe", "ipa": "ʈʂəŋ⁵¹ ʈʂə", "syllable_count": 2, "sentences": [{"text": "这个字母我得正着写。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把画正着挂在墙上。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书正着拿，字才不会倒。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机正着放在桌上。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你正着看，就能认出这个字。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把帽子正着戴好了。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图正着放才对。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这只杯子正着放，水才不会流出来。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名牌正着挂在胸前。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这张卡片要正着看。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "正着：朝对的方向，不是倒过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确答案：正着（zhèng zhe），朝对的方向，不是倒过来的。"}, {"text": "争着", "is_correct": false, "explanation": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“争着”（抢着）。"}, {"text": "蒸着", "is_correct": false, "explanation": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“蒸着”（用蒸汽加热）。"}, {"text": "整着", "is_correct": false, "explanation": "首音节 zhěng（第三声）与 zhèng（第四声）声调不同，意思是“整理着”。"}], "explanations": {"正着": "正确答案：正着（zhèng zhe），朝对的方向，不是倒过来的。", "争着": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“争着”（抢着）。", "蒸着": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“蒸着”（用蒸汽加热）。", "整着": "首音节 zhěng（第三声）与 zhèng（第四声）声调不同，意思是“整理着”。"}, "sentence_index": null, "correct_answer": "正着"}, "level_3": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确：“正着写”指朝对的方向写，与字母的书写要求相符。"}, {"text": "刚才", "is_correct": false, "explanation": "语法：“得”表示必须，后面接将要做的事，不能接表示过去的“刚才”。"}, {"text": "曾经", "is_correct": false, "explanation": "语法：“曾经”表示过去的经历，不能放在表示必须的“得”后面。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”表示动作已完成，不能放在表示必须的“得”后面。"}], "explanations": {"正着": "正确：“正着写”指朝对的方向写，与字母的书写要求相符。", "刚才": "语法：“得”表示必须，后面接将要做的事，不能接表示过去的“刚才”。", "曾经": "语法：“曾经”表示过去的经历，不能放在表示必须的“得”后面。", "已经": "语法：“已经”表示动作已完成，不能放在表示必须的“得”后面。"}, "sentence_index": 0, "correct_answer": "正着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正着有空。", "explanation": "这里应该用〈正好〉。正着表示按正常方向，不能表示时间或状态的巧合。"}, {"text": "他正着说错了话。", "explanation": "这里应该用〈故意〉。正着表示按正常方向，不能表示有意做某事。"}, {"text": "我正着想起了一件事。", "explanation": "这里应该用〈忽然〉。正着表示方向正常，不表示突然发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确：“正着放”指按正常方向放，符合“放才对”的要求。"}, {"text": "胡乱", "is_correct": false, "explanation": "语义：“胡乱放”指随意摆放，与“才对”所表达的正确摆放相矛盾。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷放”指暗中放置，与图的摆放方向无关，也不符合“才对”的判断。"}, {"text": "瞎", "is_correct": false, "explanation": "语义：“瞎放”指随意乱放，与“才对”所表达的正确摆放相矛盾。"}], "explanations": {"正着": "正确：“正着放”指按正常方向放，符合“放才对”的要求。", "胡乱": "语义：“胡乱放”指随意摆放，与“才对”所表达的正确摆放相矛盾。", "偷偷": "语义：“偷偷放”指暗中放置，与图的摆放方向无关，也不符合“才对”的判断。", "瞎": "语义：“瞎放”指随意乱放，与“才对”所表达的正确摆放相矛盾。"}, "sentence_index": 6, "correct_answer": "正着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正着到家了。", "explanation": "这里应该用〈刚〉。正着表示按正常方向，不表示时间刚刚发生。"}, {"text": "我们正着讨论问题。", "explanation": "这里应该用〈一起〉。正着表示方向，不表示共同进行。"}, {"text": "妈妈正着做了一顿饭。", "explanation": "这里应该用〈亲自〉。正着表示按正常方向，不表示自己动手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个音节我要正着的念。", "corrected_sentence": "这个音节我要正着念。", "error_description": "错误：“正着的念”；正确：“正着念”。“正着”作状语修饰动词，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们把这张图正着的挂好。", "corrected_sentence": "老师让我们把这张图正着挂好。", "error_description": "错误：“正着的挂好”；正确：“正着挂好”。“正着”作状语修饰动词，直接放在动词前，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
