INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93928, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "按正常方向；不颠倒地。", "primary_collocate": null, "pronunciation": "zhèng zhe", "ipa": "ʈʂəŋ⁵¹ ʈʂə", "syllable_count": 2, "sentences": [{"text": "这本书你拿反了，要正着拿。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张照片正着放。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字正着写和倒着写不一样。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子正着放在桌子上。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画要正着看才好看。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把那张纸正着贴在墙上。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正着读和倒着读，这句话都一样。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志要正着挂才对。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字正着写在本子上。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你正着看这张地图就明白了。", "target_word": "正着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "正着：按正常方向，不颠倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确答案：正着（zhèng zhe），按正常方向，不颠倒。"}, {"text": "争着", "is_correct": false, "explanation": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“争着”（抢着）。"}, {"text": "蒸着", "is_correct": false, "explanation": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“蒸着”（用蒸汽加热）。"}, {"text": "整着", "is_correct": false, "explanation": "首音节 zhěng（第三声）与 zhèng（第四声）声调不同，意思是“整理着”。"}], "explanations": {"正着": "正确答案：正着（zhèng zhe），按正常方向，不颠倒。", "争着": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“争着”（抢着）。", "蒸着": "首音节 zhēng（第一声）与 zhèng（第四声）声调不同，意思是“蒸着”（用蒸汽加热）。", "整着": "首音节 zhěng（第三声）与 zhèng（第四声）声调不同，意思是“整理着”。"}, "sentence_index": null, "correct_answer": "正着"}, "level_3": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确：“正着拿”指按正常方向拿，与“拿反了，要……”的纠正语境相符。"}, {"text": "倒着", "is_correct": false, "explanation": "语义：“倒着”指颠倒，与“拿反了，要……”的纠正语境相反。"}, {"text": "胡乱", "is_correct": false, "explanation": "语义：“胡乱”指随意、不认真，不符合纠正拿法的语境。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“随便”指任意取用，不能用于要求特定方向的动作。"}], "explanations": {"正着": "正确：“正着拿”指按正常方向拿，与“拿反了，要……”的纠正语境相符。", "倒着": "语义：“倒着”指颠倒，与“拿反了，要……”的纠正语境相反。", "胡乱": "语义：“胡乱”指随意、不认真，不符合纠正拿法的语境。", "随便": "搭配：“随便”指任意取用，不能用于要求特定方向的动作。"}, "sentence_index": 0, "correct_answer": "正着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正着吃饭。", "explanation": "这里应该用〈正在〉。正着表示按正常方向，不表示动作进行中。"}, {"text": "我正着想念你。", "explanation": "这里应该用〈一直〉。正着只表示方向，不表示持续的思念。"}, {"text": "他正着宣布了结果。", "explanation": "这里应该用〈正式〉。正着表示方向正常，不表示官方或正式的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正着", "is_correct": true, "explanation": "正确：“正着读”指按正常方向读，与“倒着读”形成对照，符合句意。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起读”指共同进行，与“正着”“倒着”两个方向的对照不通。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说的是音量，与句中“正着”“倒着”两种读法的对照不符。"}, {"text": "悉数", "is_correct": false, "explanation": "语域：“悉数”是书面语，与句中口语化的读法对照不符，且意思是全部算上，不指读法方向。"}], "explanations": {"正着": "正确：“正着读”指按正常方向读，与“倒着读”形成对照，符合句意。", "一起": "语义：“一起读”指共同进行，与“正着”“倒着”两个方向的对照不通。", "大声": "语义：“大声”说的是音量，与句中“正着”“倒着”两种读法的对照不符。", "悉数": "语域：“悉数”是书面语，与句中口语化的读法对照不符，且意思是全部算上，不指读法方向。"}, "sentence_index": 6, "correct_answer": "正着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正着见面了。", "explanation": "这里应该用〈正好〉。正着表示按正常方向，不表示时间巧合。"}, {"text": "我正着担心你。", "explanation": "这里应该用〈非常〉。正着表示方向正常，不表示程度深。"}, {"text": "他正着回来了。", "explanation": "这里应该用〈马上〉。正着表示方向，不表示时间紧接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把钥匙很正着放进包里。", "corrected_sentence": "她把钥匙正着放进包里。", "error_description": "错误：“很正着放”；正确：“正着放”。“正着”描述动作的方向，不表示程度，不能被程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要把这张纸很正着放好。", "corrected_sentence": "你要把这张纸正着放好。", "error_description": "错误：“很正着放好”；正确：“正着放好”。“正着”表示按正常方向，是状态性的副词，不能用程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
