INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "湾是海边向里弯进来的一片水。", "primary_collocate": null, "pronunciation": "wān", "ipa": "wan˥", "syllable_count": 1, "sentences": [{"text": "那个湾里停着很多小船。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家就住在这个湾旁边。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水涌进湾里，水面很平。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湾的水为什么这么绿？", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上这个湾很小。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长把船开进了湾里。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湾里没有大浪，很适合游泳。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候常在这个湾里玩水。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有一个湾，我们在那里停一下。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湾外的风浪很大，湾里却很平静。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灣", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "海边向里弯进来的一片水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾（wān）指海边向里弯进来的一片水，即本题的目标词。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wān（第一声）声调不同，意思是“玩耍”。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 wān 声母不同（g/w），意思是“干燥”。"}, {"text": "翻", "is_correct": false, "explanation": "fān 与 wān 声母不同（f/w），意思是“翻转”。"}, {"text": "欢", "is_correct": false, "explanation": "huān 与 wān 声母不同（h/w），意思是“高兴”。"}], "explanations": {"湾": "湾（wān）指海边向里弯进来的一片水，即本题的目标词。", "玩": "wán（第二声）与 wān（第一声）声调不同，意思是“玩耍”。", "干": "gān 与 wān 声母不同（g/w），意思是“干燥”。", "翻": "fān 与 wān 声母不同（f/w），意思是“翻转”。", "欢": "huān 与 wān 声母不同（h/w），意思是“高兴”。"}, "sentence_index": null, "correct_answer": "湾"}, "level_3": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾是海边的水域，船可以停在里面，与“那个湾里停着很多小船”相符。"}, {"text": "房", "is_correct": false, "explanation": "语义：房子里不能停很多小船。"}, {"text": "盒", "is_correct": false, "explanation": "搭配：“停着很多小船”需要水域作处所，盒子不能与之搭配。"}, {"text": "柜", "is_correct": false, "explanation": "语义：柜子里放不下很多小船，句意不通。"}], "explanations": {"湾": "湾是海边的水域，船可以停在里面，与“那个湾里停着很多小船”相符。", "房": "语义：房子里不能停很多小船。", "盒": "搭配：“停着很多小船”需要水域作处所，盒子不能与之搭配。", "柜": "语义：柜子里放不下很多小船，句意不通。"}, "sentence_index": 0, "correct_answer": "湾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湾从山里流出来，一直流到村子旁边。", "explanation": "这里应该用〈河〉。湾是海边向里弯进来的一片水，不会从山里流出；从山里流出、流向村子的水道要用河。"}, {"text": "孩子们在湾里踢足球。", "explanation": "这里应该用〈球场〉。湾是水域，人不能在水里踢足球；踢足球要在球场上进行。"}, {"text": "那个湾的四面都是陆地，湾里长满了松树。", "explanation": "这里应该用〈林地〉。湾是水域，里面不会长满松树；长满树木的陆地要用林地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93929, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾（wān）指海边向里弯进来的一片水，即本题的目标词。"}, {"text": "温", "is_correct": false, "explanation": "wēn 与 wān 韵母不同（en/an），意思是“温暖”。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wān（第一声）声调不同，意思是“碗”。"}, {"text": "关", "is_correct": false, "explanation": "guān 与 wān 声母不同（g/w），意思是“关闭”。"}], "explanations": {"湾": "湾（wān）指海边向里弯进来的一片水，即本题的目标词。", "温": "wēn 与 wān 韵母不同（en/an），意思是“温暖”。", "碗": "wǎn（第三声）与 wān（第一声）声调不同，意思是“碗”。", "关": "guān 与 wān 声母不同（g/w），意思是“关闭”。"}, "sentence_index": null, "correct_answer": "湾"}, "level_3": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾是有遮挡的水域，里面没有大浪，适合游泳，与句意相符。"}, {"text": "屋", "is_correct": false, "explanation": "语义：屋里不会有大浪，“没有大浪”说的是水面。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“很适合游泳”需要水域，车里不能游泳。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶子里不会有“大浪”，句意不通。"}], "explanations": {"湾": "湾是有遮挡的水域，里面没有大浪，适合游泳，与句意相符。", "屋": "语义：屋里不会有大浪，“没有大浪”说的是水面。", "车": "搭配：“很适合游泳”需要水域，车里不能游泳。", "瓶": "语义：瓶子里不会有“大浪”，句意不通。"}, "sentence_index": 6, "correct_answer": "湾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湾三面环水，外面是大海。", "explanation": "这里应该用〈半岛〉。湾三面都是陆地，不能三面环水；三面环水、一面连陆的陆地要用半岛。"}, {"text": "这个湾在山顶上，要爬很久才能到达。", "explanation": "这里应该用〈山〉。湾是海边向里弯进来的水面，不会在山顶上；要爬很久才能到达的高处要用山。"}, {"text": "湾上的贝壳很多，孩子们喜欢去捡。", "explanation": "这里应该用〈沙滩〉。贝壳多见于沙滩，湾是水域，不能说“湾上”的贝壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只湾很深，船可以停靠。", "corrected_sentence": "这个湾很深，船可以停靠。", "error_description": "量词错误：“湾”应用量词“个”，不能用“只”，应说“这个湾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗湾里的水很深，船可以停靠。", "corrected_sentence": "这个湾里的水很深，船可以停靠。", "error_description": "量词错误：“湾”不用量词“颗”（颗多用于粒状小物），应说“这个湾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
