INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海岸向陆地凹入的部分，水面三面被陆地环绕。", "primary_collocate": null, "pronunciation": "wān", "ipa": "wan˥", "syllable_count": 1, "sentences": [{"text": "这个湾三面都是山，风很小。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船都停在湾里。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开船进了湾里休息。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个湾里的水很蓝。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湾里有很多小鱼。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，船回到了湾里。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湾不大，但是很深。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湾的东边有一个小村子。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风大的时候，湾里比外面安静。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湾的水很浅，孩子们可以下去玩。", "target_word": "湾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灣", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "海岸凹入陆地、三面环陆的水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93930, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾（wān）指海岸向陆地凹入的部分，即本题的目标词。"}, {"text": "完", "is_correct": false, "explanation": "wán（第二声）与 wān（第一声）声调不同，意思是“完成”。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wān（第一声）声调不同，意思是“晚上”。"}, {"text": "关", "is_correct": false, "explanation": "guān 与 wān 声母不同（g/w），意思是“关闭”。"}, {"text": "三", "is_correct": false, "explanation": "sān 与 wān 声母不同（s/w），意思是数字“三”。"}, {"text": "烟", "is_correct": false, "explanation": "yān 与 wān 声母不同（y/w），意思是“烟”。"}], "explanations": {"湾": "湾（wān）指海岸向陆地凹入的部分，即本题的目标词。", "完": "wán（第二声）与 wān（第一声）声调不同，意思是“完成”。", "晚": "wǎn（第三声）与 wān（第一声）声调不同，意思是“晚上”。", "关": "guān 与 wān 声母不同（g/w），意思是“关闭”。", "三": "sān 与 wān 声母不同（s/w），意思是数字“三”。", "烟": "yān 与 wān 声母不同（y/w），意思是“烟”。"}, "sentence_index": null, "correct_answer": "湾"}, "level_3": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾是海岸向陆地凹入、三面环陆的水域，与“三面都是山，风很小”相符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不会被三面的山环绕，句中说的是被陆地包围的水域。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：“三面都是山”描述的是地形，桥不能这样被描述。"}, {"text": "窗", "is_correct": false, "explanation": "语义：窗户不可能三面都被山环绕，句意不通。"}], "explanations": {"湾": "湾是海岸向陆地凹入、三面环陆的水域，与“三面都是山，风很小”相符。", "船": "语义：船不会被三面的山环绕，句中说的是被陆地包围的水域。", "桥": "搭配：“三面都是山”描述的是地形，桥不能这样被描述。", "窗": "语义：窗户不可能三面都被山环绕，句意不通。"}, "sentence_index": 0, "correct_answer": "湾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人每天早上在湾里跑步锻炼。", "explanation": "这里应该用〈海滩〉。湾是水域，人不能在里面跑步；跑步要在陆地上进行，比如海滩。"}, {"text": "这个湾很高，山顶上有一座庙。", "explanation": "这里应该用〈山〉。湾是向陆地凹入的水域，不会很高，也没有山顶；高耸的陆地要用山。"}, {"text": "太平洋是世界上最大的湾。", "explanation": "这里应该用〈海洋〉。湾是海岸凹入、三面环陆的小水域，太平洋这样的大洋不能称为湾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93930, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾（wān）指海岸向陆地凹入的部分，即本题的目标词。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wān（第一声）声调不同，意思是“一万”。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wān（第一声）声调不同，意思是“碗”。"}, {"text": "欢", "is_correct": false, "explanation": "huān 与 wān 声母不同（h/w），意思是“高兴”。"}, {"text": "班", "is_correct": false, "explanation": "bān 与 wān 声母不同（b/w），意思是“班级”。"}], "explanations": {"湾": "湾（wān）指海岸向陆地凹入的部分，即本题的目标词。", "万": "wàn（第四声）与 wān（第一声）声调不同，意思是“一万”。", "碗": "wǎn（第三声）与 wān（第一声）声调不同，意思是“碗”。", "欢": "huān 与 wān 声母不同（h/w），意思是“高兴”。", "班": "bān 与 wān 声母不同（b/w），意思是“班级”。"}, "sentence_index": null, "correct_answer": "湾"}, "level_3": {"options": [{"text": "湾", "is_correct": true, "explanation": "湾指海岸凹入的水域，可以不大但很深，与“不大，但是很深”相符。"}, {"text": "字", "is_correct": false, "explanation": "语义：文字没有深浅，不能说“很深”。"}, {"text": "蛋", "is_correct": false, "explanation": "语义：鸡蛋没有纵深，句中“很深”说不通。"}, {"text": "梨", "is_correct": false, "explanation": "搭配：“很深”形容有纵深的空间或水域，梨不能这样搭配。"}], "explanations": {"湾": "湾指海岸凹入的水域，可以不大但很深，与“不大，但是很深”相符。", "字": "语义：文字没有深浅，不能说“很深”。", "蛋": "语义：鸡蛋没有纵深，句中“很深”说不通。", "梨": "搭配：“很深”形容有纵深的空间或水域，梨不能这样搭配。"}, "sentence_index": 6, "correct_answer": "湾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湾伸进大海很远，像一根手指。", "explanation": "这里应该用〈岬〉。湾是向陆地凹入的部分；伸入海中的陆地突出部分要用岬。"}, {"text": "孩子们在湾上堆沙堡。", "explanation": "这里应该用〈海滩〉。堆沙堡要在沙滩上进行，湾是水面，不能在它上面堆沙。"}, {"text": "那个湾被大海包围着。", "explanation": "这里应该用〈岛〉。湾三面都是陆地，不会被海水全部包围；被海水四面环绕的陆地是岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
