INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "烧是东西着火，或者用火把东西弄热。", "primary_collocate": null, "pronunciation": "shāo", "ipa": "ʂau˥", "syllable_count": 1, "sentences": [{"text": "妈妈在厨房烧水。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他们烧柴取暖。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些旧纸烧了吧。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水烧开了，快关火。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头很湿，不好烧。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上烧一壶水。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别让火烧到衣服。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树烧了三天。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用炉子烧水做饭。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在院子里烧树叶。", "target_word": "烧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "燒", "label": "繁体"}, {"form": "烧了", "label": "体标"}, {"form": "烧着", "label": "体标"}, {"form": "烧过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西着火或用火加热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93931, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烧", "is_correct": true, "explanation": "烧（shāo）指东西着火，或用火把东西弄热，即本题的目标词。"}, {"text": "少", "is_correct": false, "explanation": "shǎo（第三声）与 shāo（第一声）声调不同，意思是“少”。"}, {"text": "招", "is_correct": false, "explanation": "zhāo 与 shāo 声母不同（zh/sh），意思是“招呼”。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shāo 韵母不同（an/ao），意思是“山”。"}, {"text": "超", "is_correct": false, "explanation": "chāo 与 shāo 声母不同（ch/sh），意思是“超过”。"}, {"text": "哨", "is_correct": false, "explanation": "shào（第四声）与 shāo（第一声）声调不同，意思是“哨子”。"}], "explanations": {"烧": "烧（shāo）指东西着火，或用火把东西弄热，即本题的目标词。", "少": "shǎo（第三声）与 shāo（第一声）声调不同，意思是“少”。", "招": "zhāo 与 shāo 声母不同（zh/sh），意思是“招呼”。", "山": "shān 与 shāo 韵母不同（an/ao），意思是“山”。", "超": "chāo 与 shāo 声母不同（ch/sh），意思是“超过”。", "哨": "shào（第四声）与 shāo（第一声）声调不同，意思是“哨子”。"}, "sentence_index": null, "correct_answer": "烧"}, "level_3": {"options": [{"text": "烧", "is_correct": true, "explanation": "烧：用火使水受热，与“妈妈在厨房烧水”相符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”用于能被切断的固体，不能说“切水”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：把水扔掉与“在厨房烧水”的做饭情境无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是物品或食材，不能说“洗水”。"}], "explanations": {"烧": "烧：用火使水受热，与“妈妈在厨房烧水”相符。", "切": "搭配：“切”用于能被切断的固体，不能说“切水”。", "扔": "语义：把水扔掉与“在厨房烧水”的做饭情境无关。", "洗": "搭配：“洗”的对象通常是物品或食材，不能说“洗水”。"}, "sentence_index": 0, "correct_answer": "烧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把湿衣服烧在院子里，等太阳出来。", "explanation": "这里应该用〈晒〉。烧是用火使东西着火或受热，晒衣服要靠太阳，用“晒”。"}, {"text": "妈妈在门口烧了一首歌，等我回家。", "explanation": "这里应该用〈唱〉。烧不能用于歌曲，唱歌要用“唱”。"}, {"text": "妈妈每天早上烧面包，给我们吃。", "explanation": "这里应该用〈烤〉。烧用于火使东西着火或液体受热，烤面包要用“烤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93931, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烧", "is_correct": true, "explanation": "烧（shāo）指东西着火，或用火把东西弄热，即本题的目标词。"}, {"text": "勺", "is_correct": false, "explanation": "sháo（第二声）与 shāo（第一声）声调不同，意思是“勺子”。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shāo 韵母不同（ang/ao），意思是“受伤”。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 shāo 韵母不同（ou/ao），意思是“收起”。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 shāo 声母不同（x/sh），意思是“消失”。"}], "explanations": {"烧": "烧（shāo）指东西着火，或用火把东西弄热，即本题的目标词。", "勺": "sháo（第二声）与 shāo（第一声）声调不同，意思是“勺子”。", "伤": "shāng 与 shāo 韵母不同（ang/ao），意思是“受伤”。", "收": "shōu 与 shāo 韵母不同（ou/ao），意思是“收起”。", "消": "xiāo 与 shāo 声母不同（x/sh），意思是“消失”。"}, "sentence_index": null, "correct_answer": "烧"}, "level_3": {"options": [{"text": "烧", "is_correct": true, "explanation": "烧：用火使东西着火或受热，与“别让火烧到衣服”相符。"}, {"text": "织", "is_correct": false, "explanation": "语义：火不会织东西，“织到衣服”与句意不符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂物体，火不能被挂到衣服上。"}, {"text": "摘", "is_correct": false, "explanation": "语义：火不能被摘下来，“摘到衣服”说不通。"}], "explanations": {"烧": "烧：用火使东西着火或受热，与“别让火烧到衣服”相符。", "织": "语义：火不会织东西，“织到衣服”与句意不符。", "挂": "搭配：“挂”指悬挂物体，火不能被挂到衣服上。", "摘": "语义：火不能被摘下来，“摘到衣服”说不通。"}, "sentence_index": 6, "correct_answer": "烧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河面烧得很厚，人们可以在上面走过去。", "explanation": "这里应该用〈冻〉。烧是用火使东西着火或受热，不表示结冰；河面变厚要用“冻”。"}, {"text": "她每天用洗衣机烧衣服。", "explanation": "这里应该用〈洗〉。烧是用火使东西着火或受热，用洗衣机让衣服变干净要用“洗”。"}, {"text": "妈妈每天早上烧药，给爷爷喝。", "explanation": "这里应该用〈煎〉。中药要煎，不说“烧药”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书烧了掉。", "corrected_sentence": "他把书烧掉了。", "error_description": "补语语序错误：“烧掉”是动补结构，“了”应放在补语之后，应说“烧掉了”，不能说“烧了掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧报纸了烧。", "corrected_sentence": "他把旧报纸烧了。", "error_description": "“了”的位置错误：“把”字句中“了”应放在动词后，应说“烧了”，不能说“了烧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
