INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93933, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "甚是非常、特别。", "primary_collocate": null, "pronunciation": "shèn", "ipa": "ʂən˥˩", "syllable_count": 1, "sentences": [{"text": "今天天气甚好，我们去公园吧。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景甚美，游客很多。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪虽大，身体却甚好。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，他的表现甚佳。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说你的作业甚好，继续努力。", "target_word": "甚", "complexity_tier": "T3", "furigana": "lǎo shī shuō nǐ de zuò yè shèn hǎo, jì xù nǔ lì。", "sentence_source": "generated"}, {"text": "山里的冬天，雪甚大，路很难走。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近很忙，我们见面的机会甚少。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法简单，用处却甚大。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的夜晚甚安静，只听到水声。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我的书，我读后受益甚多。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在形容词前，表示非常、特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93933, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，表示非常、特别，放在形容词前。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shèn（第四声）声调不同，意思是神灵、神奇。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shèn（第四声）声调不同，意思是深浅的深。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shèn（第四声）声调不同，意思是审查、审问。"}, {"text": "胜", "is_correct": false, "explanation": "shèng 与 shèn 韵母不同（eng 与 en），意思是胜利、胜过。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 shèn 韵母不同（an 与 en），意思是善良、善于。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn 与 shèn 声母不同（zh 与 sh），意思是城镇、镇压。"}], "explanations": {"甚": "甚：副词，表示非常、特别，放在形容词前。", "神": "shén（第二声）与 shèn（第四声）声调不同，意思是神灵、神奇。", "深": "shēn（第一声）与 shèn（第四声）声调不同，意思是深浅的深。", "审": "shěn（第三声）与 shèn（第四声）声调不同，意思是审查、审问。", "胜": "shèng 与 shèn 韵母不同（eng 与 en），意思是胜利、胜过。", "善": "shàn 与 shèn 韵母不同（an 与 en），意思是善良、善于。", "镇": "zhèn 与 shèn 声母不同（zh 与 sh），意思是城镇、镇压。"}, "sentence_index": null, "correct_answer": "甚"}, "level_3": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，修饰“好”，表示程度很高，属书面语。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去的经历，与“今天”这一天的天气不合。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是动态助词，不能直接放在形容词前作程度修饰，“天气了好”不成立。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“好”，与后句“我们去公园吧”的提议相矛盾。"}], "explanations": {"甚": "甚：副词，修饰“好”，表示程度很高，属书面语。", "曾": "语义：“曾”表示过去的经历，与“今天”这一天的天气不合。", "了": "语法：“了”是动态助词，不能直接放在形容词前作程度修饰，“天气了好”不成立。", "不": "语义：“不”否定“好”，与后句“我们去公园吧”的提议相矛盾。"}, "sentence_index": 0, "correct_answer": "甚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他甚连家门都没进，就去了医院。", "explanation": "这里应该用〈甚至〉。甚表示“很、特别”的程度，不表示“就连”，要说“甚至连”。"}, {"text": "这件事甚连老师都不知道。", "explanation": "这里应该用〈甚至〉。甚只表示程度，不表示“就连”，“连……都”前要用“甚至”。"}, {"text": "甚连我的父母也没听说过这件事。", "explanation": "这里应该用〈甚至〉。甚表示“很、特别”的程度，不表示“就连”，要说“甚至连”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93933, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，表示非常、特别，放在形容词前。"}, {"text": "伸", "is_correct": false, "explanation": "shēn（第一声）与 shèn（第四声）声调不同，意思是伸展、伸手。"}, {"text": "婶", "is_correct": false, "explanation": "shěn（第三声）与 shèn（第四声）声调不同，意思是婶婶。"}, {"text": "剩", "is_correct": false, "explanation": "shèng 与 shèn 韵母不同（eng 与 en），意思是剩下。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 shèn 韵母不同（an 与 en），意思是扇子。"}, {"text": "衬", "is_correct": false, "explanation": "chèn 与 shèn 声母不同（ch 与 sh），意思是衬托、衬衫的衬。"}, {"text": "震", "is_correct": false, "explanation": "zhèn 与 shèn 声母不同（zh 与 sh），意思是震动。"}], "explanations": {"甚": "甚：副词，表示非常、特别，放在形容词前。", "伸": "shēn（第一声）与 shèn（第四声）声调不同，意思是伸展、伸手。", "婶": "shěn（第三声）与 shèn（第四声）声调不同，意思是婶婶。", "剩": "shèng 与 shèn 韵母不同（eng 与 en），意思是剩下。", "扇": "shàn 与 shèn 韵母不同（an 与 en），意思是扇子。", "衬": "chèn 与 shèn 声母不同（ch 与 sh），意思是衬托、衬衫的衬。", "震": "zhèn 与 shèn 声母不同（zh 与 sh），意思是震动。"}, "sentence_index": null, "correct_answer": "甚"}, "level_3": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，修饰“少”，表示程度很高，属书面语。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，须构成“把＋宾语＋动词”结构，不能直接修饰形容词“少”。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“仅仅、刚刚”，与“很忙”导致机会少的因果关系不符。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表被动，后须接动词，不能直接修饰形容词“少”。"}], "explanations": {"甚": "甚：副词，修饰“少”，表示程度很高，属书面语。", "把": "语法：“把”是介词，须构成“把＋宾语＋动词”结构，不能直接修饰形容词“少”。", "才": "语义：“才”表示“仅仅、刚刚”，与“很忙”导致机会少的因果关系不符。", "被": "语法：“被”表被动，后须接动词，不能直接修饰形容词“少”。"}, "sentence_index": 6, "correct_answer": "甚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "甚连他的老师都夸这个方法好。", "explanation": "这里应该用〈甚至〉。甚表示“很、特别”的程度，不表示“就连”，要说“甚至连”。"}, {"text": "甚连老师也没来。", "explanation": "这里应该用〈甚至〉。甚表示程度，不表示“就连”，要说“甚至连”。"}, {"text": "甚连孩子都知道这个道理。", "explanation": "这里应该用〈甚至〉。甚表示“很、特别”的程度，不表示“就连”，要说“甚至连”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的夜景非常甚美，适合散步。", "corrected_sentence": "这座城市的夜景甚美，适合散步。", "error_description": "“甚”本身已表示程度很高，前面不能再加“非常”，构成双重程度修饰，应删去“非常”，改为“甚美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的收获很甚多，我很满意。", "corrected_sentence": "这次旅行的收获甚多，我很满意。", "error_description": "“甚”已经表示程度很高，前面不能再加“很”，构成双重程度修饰，应删去“很”，改为“甚多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
