INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93934, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很；极。多用于书面语。", "primary_collocate": null, "pronunciation": "shèn", "ipa": "ʂən˥˩", "syllable_count": 1, "sentences": [{"text": "这位老人在村里甚受尊敬。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话甚有道理。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息让大家甚感意外。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个孩子甚相像，大家常常认错。", "target_word": "甚", "complexity_tier": "T3", "furigana": "zhè liǎng gè hái zi shèn xiāng xiàng, dà jiā cháng cháng rèn cuò。", "sentence_source": "generated"}, {"text": "这件事关系甚大，不能马上决定。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里离市中心甚远，坐车要两个小时。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间甚小，只放得下一张床。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的讲解甚清楚，学生都看得懂。", "target_word": "甚", "complexity_tier": "T3", "furigana": "zhè běn shū de jiǎng jiě shèn qīng chu, xué sheng dōu kàn de dǒng。", "sentence_source": "generated"}, {"text": "老师对你的进步甚感欣慰。", "target_word": "甚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的字甚漂亮，大家都很羡慕。", "target_word": "甚", "complexity_tier": "T3", "furigana": "tā de zì shèn piào liang, dà jiā dōu hěn xiàn mù。", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语程度副词，相当于很、极", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，表示很、极，多用于书面语。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shèn（第四声）声调不同，意思是神灵、神奇。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shèn（第四声）声调不同，意思是身体。"}, {"text": "婶", "is_correct": false, "explanation": "shěn（第三声）与 shèn（第四声）声调不同，意思是婶婶。"}, {"text": "圣", "is_correct": false, "explanation": "shèng 与 shèn 韵母不同（eng 与 en），意思是圣人、圣诞。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 shèn 韵母不同（an 与 en），意思是扇子。"}, {"text": "阵", "is_correct": false, "explanation": "zhèn 与 shèn 声母不同（zh 与 sh），意思是阵地、一阵。"}], "explanations": {"甚": "甚：副词，表示很、极，多用于书面语。", "神": "shén（第二声）与 shèn（第四声）声调不同，意思是神灵、神奇。", "身": "shēn（第一声）与 shèn（第四声）声调不同，意思是身体。", "婶": "shěn（第三声）与 shèn（第四声）声调不同，意思是婶婶。", "圣": "shèng 与 shèn 韵母不同（eng 与 en），意思是圣人、圣诞。", "扇": "shàn 与 shèn 韵母不同（an 与 en），意思是扇子。", "阵": "zhèn 与 shèn 声母不同（zh 与 sh），意思是阵地、一阵。"}, "sentence_index": null, "correct_answer": "甚"}, "level_3": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，修饰“受尊敬”，表示程度很高，属书面语。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，须构成“把＋宾语＋动词”结构，“在村里把受尊敬”不成立。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是动态助词，不能放在“在村里”之后、动词之前，“在村里了受尊敬”不成立。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表被动，而“受尊敬”已含被动义，“被受尊敬”不成立。"}], "explanations": {"甚": "甚：副词，修饰“受尊敬”，表示程度很高，属书面语。", "把": "语法：“把”是介词，须构成“把＋宾语＋动词”结构，“在村里把受尊敬”不成立。", "了": "语法：“了”是动态助词，不能放在“在村里”之后、动词之前，“在村里了受尊敬”不成立。", "被": "语法：“被”表被动，而“受尊敬”已含被动义，“被受尊敬”不成立。"}, "sentence_index": 0, "correct_answer": "甚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题甚连三岁小孩都会，你别担心。", "explanation": "这里应该用〈甚至〉。甚表示“很、极”的程度，不表示“就连”，要说“甚至连”。"}, {"text": "我甚连一口水都没喝就走了。", "explanation": "这里应该用〈甚至〉。甚不表示“就连”，“连……都”前要用“甚至”。"}, {"text": "她甚连自己的生日都忘了。", "explanation": "这里应该用〈甚至〉。甚表示“很、极”的程度，不表示“就连”，要说“甚至连”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93934, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，表示很、极，多用于书面语。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shèn（第四声）声调不同，意思是审查、审问。"}, {"text": "伸", "is_correct": false, "explanation": "shēn（第一声）与 shèn（第四声）声调不同，意思是伸展、伸手。"}, {"text": "剩", "is_correct": false, "explanation": "shèng 与 shèn 韵母不同（eng 与 en），意思是剩下。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 shèn 韵母不同（an 与 en），意思是善良、善于。"}, {"text": "衬", "is_correct": false, "explanation": "chèn 与 shèn 声母不同（ch 与 sh），意思是衬托、衬衫的衬。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn 与 shèn 声母不同（zh 与 sh），意思是城镇、镇压。"}], "explanations": {"甚": "甚：副词，表示很、极，多用于书面语。", "审": "shěn（第三声）与 shèn（第四声）声调不同，意思是审查、审问。", "伸": "shēn（第一声）与 shèn（第四声）声调不同，意思是伸展、伸手。", "剩": "shèng 与 shèn 韵母不同（eng 与 en），意思是剩下。", "善": "shàn 与 shèn 韵母不同（an 与 en），意思是善良、善于。", "衬": "chèn 与 shèn 声母不同（ch 与 sh），意思是衬托、衬衫的衬。", "镇": "zhèn 与 shèn 声母不同（zh 与 sh），意思是城镇、镇压。"}, "sentence_index": null, "correct_answer": "甚"}, "level_3": {"options": [{"text": "甚", "is_correct": true, "explanation": "甚：副词，修饰“小”，表示程度很高，属书面语。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“小”，与“只放得下一张床”的意思相矛盾。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是动态助词，不能直接放在形容词前修饰“小”，“房间了小”不成立。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“仅仅”，与前文对房间的描述无法搭配。"}], "explanations": {"甚": "甚：副词，修饰“小”，表示程度很高，属书面语。", "不": "语义：“不”否定“小”，与“只放得下一张床”的意思相矛盾。", "了": "语法：“了”是动态助词，不能直接放在形容词前修饰“小”，“房间了小”不成立。", "才": "语义：“才”表示“仅仅”，与前文对房间的描述无法搭配。"}, "sentence_index": 6, "correct_answer": "甚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他太累了，甚连饭都不想吃。", "explanation": "这里应该用〈甚至〉。甚表示“很、极”的程度，不表示“就连”，要说“甚至连”。"}, {"text": "这道题甚连班长也不会做。", "explanation": "这里应该用〈甚至〉。甚只表示程度，不表示“就连”，“连……也”前要用“甚至”。"}, {"text": "雨下得很大，甚连路都看不清了。", "explanation": "这里应该用〈甚至〉。甚表示“很、极”的程度，不表示“就连”，要说“甚至连”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏很甚有意思，我们玩了一下午。", "corrected_sentence": "这个游戏甚有意思，我们玩了一下午。", "error_description": "“很甚有意思”错误：“甚”本身已表示程度很高，前面不能再加“很”，构成双重程度修饰，应删去“很”，改为“甚有意思”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的房间很甚干净，妈妈很满意。", "corrected_sentence": "他的房间甚干净，妈妈很满意。", "error_description": "“甚”已经表示程度很高，前面不能再加“很”，构成双重程度修饰，应删去“很”，改为“甚干净”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "略是不多，只有一点点。", "primary_collocate": null, "pronunciation": "lüè", "ipa": "lɥe˥˩", "syllable_count": 1, "sentences": [{"text": "这件衣服略大一点。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气略冷。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我略高一点。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜略贵，但是很好吃。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语比去年略有进步。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况略有好转。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字的写法略有不同。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天起得略早了一点。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯茶的味道略甜。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房间比他的略小。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，放在形容词或“有”前，表示程度很轻、只有一点点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "略", "is_correct": true, "explanation": "正确：“略大一点”表示只大一点点，与句意相符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”表示程度很高，不与“大一点”这样表示少量的说法搭配。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示最高程度，与“一点”的轻微程度矛盾。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示程度很高，与“一点”的轻微程度矛盾。"}], "explanations": {"略": "正确：“略大一点”表示只大一点点，与句意相符。", "非常": "搭配：“非常”表示程度很高，不与“大一点”这样表示少量的说法搭配。", "最": "语义：“最”表示最高程度，与“一点”的轻微程度矛盾。", "特别": "语义：“特别”表示程度很高，与“一点”的轻微程度矛盾。"}, "sentence_index": 0, "correct_answer": "略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我略高很多。", "explanation": "这里“略”表示程度很轻，被误用为〈远远〉的意思；“高很多”是大幅差距，与“略”的轻微程度矛盾，应该说“他比我高很多”。"}, {"text": "他的病略好得完全看不出来了。", "explanation": "这里“略”被误用为〈完全〉的意思。“略”表示程度很轻，不能修饰“完全看不出来”这种彻底的程度。"}, {"text": "他的成绩略特别好。", "explanation": "这里“略”被误用为〈十分〉的意思。“略”表示程度很轻，不能修饰“特别好”这种极高的程度，应该说“他的成绩很好”或“他的成绩略好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "略", "is_correct": true, "explanation": "正确：“略有不同”表示只有一点点的不同，与句意相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，不能修饰“有不同”这样的状态。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“有不同”这种已存在的状态不符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰程度，一般不说“十分有不同”，搭配不当。"}], "explanations": {"略": "正确：“略有不同”表示只有一点点的不同，与句意相符。", "正在": "体貌：“正在”表示动作进行，不能修饰“有不同”这样的状态。", "马上": "语义：“马上”表示很快发生，与“有不同”这种已存在的状态不符。", "十分": "搭配：“十分”修饰程度，一般不说“十分有不同”，搭配不当。"}, "sentence_index": 6, "correct_answer": "略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛我略赢了所有人。", "explanation": "这里“略”被误用为〈彻底〉的意思。“略”表示程度很轻，不能修饰“赢了所有人”这种全面的结果。"}, {"text": "这箱苹果我略吃光了。", "explanation": "这里“略”被误用为〈完全〉的意思。“略”表示程度很轻，不能修饰“吃光”这种完全的结果。"}, {"text": "这件衣服略很便宜。", "explanation": "这里“略”被误用为〈非常〉的意思。“略”表示程度很轻，不能与表示程度很高的副词同用，应该说“这件衣服略便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋紧略一点。", "corrected_sentence": "这双鞋略紧一点。", "error_description": "错误：“略”放在形容词“紧”后面；正确：“略紧”。“略”修饰形容词，要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两本书的价格有略差别。", "corrected_sentence": "这两本书的价格略有差别。", "error_description": "错误：“略”位置不对，写成“有略差别”；正确：“略有差别”。“略”应放在“有”前面，表示程度轻。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "稍微；简单。", "primary_collocate": null, "pronunciation": "lüè", "ipa": "lɥe˥˩", "syllable_count": 1, "sentences": [{"text": "他略想了想，就答应了。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师略讲了一下这个问题。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你略说一下昨天的情况。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这本书略翻了翻。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他略笑了笑，没有说话。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我略看了一眼，就知道是谁。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个行业略作了介绍。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈略问了几句，就让他回家。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他略休息了一会儿，又开始工作。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理略看了一下我的计划。", "target_word": "略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，放在动词前，表示稍微、简单地做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "略", "is_correct": true, "explanation": "正确：“略”表示稍微、简单，修饰动词，“略想了想”是稍微想一下。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”表示程度很高，不能修饰“想了想”这样的短动作，“非常想了想”不通。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“想了想”这个短暂的动作矛盾。"}, {"text": "颇", "is_correct": false, "explanation": "语域：“颇”是书面用词，而且一般不修饰“想了想”这类动作，句子不自然。"}], "explanations": {"略": "正确：“略”表示稍微、简单，修饰动词，“略想了想”是稍微想一下。", "非常": "搭配：“非常”表示程度很高，不能修饰“想了想”这样的短动作，“非常想了想”不通。", "一直": "语义：“一直”表示持续，与“想了想”这个短暂的动作矛盾。", "颇": "语域：“颇”是书面用词，而且一般不修饰“想了想”这类动作，句子不自然。"}, "sentence_index": 0, "correct_answer": "略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我略考了满分。", "explanation": "这里“略”被误用为〈完全〉的意思。“略”表示稍微、简单地做，不能修饰“考了满分”这种极端的结果。"}, {"text": "我略吃了三碗饭。", "explanation": "这里“略”被误用为〈多、大量〉的意思。“略”表示稍微、程度轻，而“吃了三碗饭”是大量，不能用“略”修饰。"}, {"text": "这项工作的难度略大得惊人。", "explanation": "这里“略”被误用为〈十分〉的意思。“略”表示稍微、程度轻，不能修饰“大得惊人”这种极高的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "略", "is_correct": true, "explanation": "正确：“略作了介绍”指简单地介绍一下，“略”修饰动词，与句意相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，与“作了介绍”的完成语气不符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“作了介绍”已完成的意思不符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能修饰“作了介绍”。"}], "explanations": {"略": "正确：“略作了介绍”指简单地介绍一下，“略”修饰动词，与句意相符。", "正在": "体貌：“正在”表示动作进行，与“作了介绍”的完成语气不符。", "马上": "语义：“马上”表示很快发生，与“作了介绍”已完成的意思不符。", "十分": "搭配：“十分”修饰形容词或心理动词，不能修饰“作了介绍”。"}, "sentence_index": 6, "correct_answer": "略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比我略强得多。", "explanation": "这里“略”被误用为〈远远〉的意思。“略”表示稍微、程度轻，与“强得多”的大幅差距矛盾，不能这样说。"}, {"text": "我略知道一切。", "explanation": "这里“略”被误用为〈全部〉的意思。“略”表示稍微、程度轻，不能修饰“知道一切”这种全部的程度。"}, {"text": "我略非常了解这个行业。", "explanation": "这里“略”被误用为〈十分〉的意思。“略”表示稍微、程度轻，不能用来表示程度很高的了解，应该说“我略有了解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我问略了一下他的意见。", "corrected_sentence": "我略问了一下他的意见。", "error_description": "错误：“略”放在动词“问”后面；正确：“略问”。“略”作状语，要放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我略看了很久这份文件。", "corrected_sentence": "我略看了一下这份文件。", "error_description": "错误：“略看了很久”；正确：“略看了一下”。“略”表示稍微、简单地做，与“很久”的长时间矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
