INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发放是把东西一份一份分给大家。", "primary_collocate": null, "pronunciation": "fā fàng", "ipa": "fa˥ faŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师给每个同学发放一份试卷。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把作业一份一份发放给大家。", "target_word": "发放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动现场发放了很多小礼物。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区正在给居民发放口罩。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在门口发放宣传单。", "target_word": "发放", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议开始前，工作人员发放资料。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食堂中午给大家发放水果。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者在路口发放过免费地图。", "target_word": "发放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给新生发放了校服和书包。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家排队，我来发放饭票。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "發放", "label": "繁体"}, {"form": "发放了", "label": "体标"}, {"form": "发放过", "label": "体标"}], "register": "正式", "sense_fingerprint": "把试卷、口罩、礼物、资料等东西一份一份分给在场的每个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发放", "is_correct": true, "explanation": "「发放」表示把试卷一份份分给同学，与句意相合。"}, {"text": "烤", "is_correct": false, "explanation": "语义：「烤」需要食物或材料作宾语，「试卷」不能被烤。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：「咬」与纸质的「试卷」不搭配。"}, {"text": "骂", "is_correct": false, "explanation": "配价：「骂」的宾语是人，不能带「一份试卷」作宾语。"}], "explanations": {"发放": "「发放」表示把试卷一份份分给同学，与句意相合。", "烤": "语义：「烤」需要食物或材料作宾语，「试卷」不能被烤。", "咬": "搭配：「咬」与纸质的「试卷」不搭配。", "骂": "配价：「骂」的宾语是人，不能带「一份试卷」作宾语。"}, "sentence_index": 0, "correct_answer": "发放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在杂志上发放了一篇文章。", "explanation": "这里应该用〈发表〉。文章在刊物上登出用发表，发放是把实物一份份分给人。"}, {"text": "我把包裹发放给了朋友。", "explanation": "这里应该用〈寄〉。个人把包裹送出用寄，发放多指集体把东西分给许多人。"}, {"text": "他在生日那天发放了一份礼物给我。", "explanation": "这里应该用〈送〉。一人送给另一人单个礼物用送，发放要面向许多人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发放", "is_correct": true, "explanation": "「发放」表示把水果分给大家，与“食堂中午给大家……水果”相合。"}, {"text": "砍", "is_correct": false, "explanation": "语义：「砍」指用刀斩断，与分给大家的意思不符。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：「拆」的宾语多为包装物，「水果」不能拆。"}, {"text": "撕", "is_correct": false, "explanation": "语义：「撕」指撕裂，不能表示把水果分给大家。"}], "explanations": {"发放": "「发放」表示把水果分给大家，与“食堂中午给大家……水果”相合。", "砍": "语义：「砍」指用刀斩断，与分给大家的意思不符。", "拆": "搭配：「拆」的宾语多为包装物，「水果」不能拆。", "撕": "语义：「撕」指撕裂，不能表示把水果分给大家。"}, "sentence_index": 6, "correct_answer": "发放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电台发放了一首新歌。", "explanation": "这里应该用〈播放〉。发放是把东西一份份分给大家，广播节目要用播放。"}, {"text": "同学们把作业发放给老师。", "explanation": "这里应该用〈交〉。作业是学生交给老师，不是分发给老师。"}, {"text": "公司发放了一名经理去分公司。", "explanation": "这里应该用〈派遣〉。人员派往某地要用派遣，发放只用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "值班老师正在给同学们发放了试卷。", "corrected_sentence": "值班老师正在给同学们发放试卷。", "error_description": "错误形式是“正在”后又加了“了”。“正在”表示动作进行中，不能与“了”同用。应说“正在给同学们发放试卷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把牛奶发放每个班级。", "corrected_sentence": "学校把牛奶发放到每个班级。", "error_description": "错误形式是「发放」后直接接地点，缺少引介的介词。应说「发放到每个班级」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
