INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分发；把钱或物资发给有关的人。", "primary_collocate": null, "pronunciation": "fā fàng", "ipa": "fa˥ faŋ˥˩", "syllable_count": 2, "sentences": [{"text": "政府给老人发放了生活补助。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校今天发放奖学金。", "target_word": "发放", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司每月十五号发放工资。", "target_word": "发放", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里把救灾物资发放给受灾的人。", "target_word": "发放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行已经发放了这笔贷款。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司下个月发放年终奖。", "target_word": "发放", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "防疫物资还没有发放到社区。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员正在发放救济款。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的津贴已经发放了。", "target_word": "发放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有关部门发放过一批救灾款。", "target_word": "发放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "發放", "label": "繁体"}, {"form": "发放了", "label": "体标"}, {"form": "发放过", "label": "体标"}], "register": "正式", "sense_fingerprint": "把钱款或物资发给有关的人，常用于政府、单位发补助、工资、贷款、救灾物资等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发放", "is_correct": true, "explanation": "「发放」指把补助发给有关的人，与句中“政府给老人”“生活补助”相合。"}, {"text": "偷", "is_correct": false, "explanation": "语义：「偷」指暗中拿走他人财物，与政府正当分发补助的意思相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语多为食物，「生活补助」是钱或物资，不能吃。"}, {"text": "卖", "is_correct": false, "explanation": "配价：「卖」要求有卖出方和买方，与“政府给老人”的受益关系不相容。"}], "explanations": {"发放": "「发放」指把补助发给有关的人，与句中“政府给老人”“生活补助”相合。", "偷": "语义：「偷」指暗中拿走他人财物，与政府正当分发补助的意思相反。", "吃": "搭配：「吃」的宾语多为食物，「生活补助」是钱或物资，不能吃。", "卖": "配价：「卖」要求有卖出方和买方，与“政府给老人”的受益关系不相容。"}, "sentence_index": 0, "correct_answer": "发放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司把任务发放给每个员工。", "explanation": "这里应该用〈分配〉。发放用于钱款、物资等实物，任务要用分配。"}, {"text": "气象台发放了暴雨预警。", "explanation": "这里应该用〈发布〉。预警是信息，要用发布；发放指把实物分给众人。"}, {"text": "他用手机把照片发放给朋友。", "explanation": "这里应该用〈发送〉。发放多指有关部门或单位分给许多人，个人之间传照片要用发送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发放", "is_correct": true, "explanation": "「发放」表示把物资分送出去，与“防疫物资……到社区”相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的宾语是饮品，「防疫物资」不能喝。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」是人的动作，不能用来表示物资送达。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」是情绪表现，与物资运送毫无关系，“哭到社区”不成话。"}], "explanations": {"发放": "「发放」表示把物资分送出去，与“防疫物资……到社区”相合。", "喝": "搭配：「喝」的宾语是饮品，「防疫物资」不能喝。", "睡": "语义：「睡」是人的动作，不能用来表示物资送达。", "哭": "语义：「哭」是情绪表现，与物资运送毫无关系，“哭到社区”不成话。"}, "sentence_index": 6, "correct_answer": "发放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学向他发放了博士学位。", "explanation": "这里应该用〈授予〉。学位是学校授予的，发放只用于分给众人的钱物。"}, {"text": "人大发放了一部新法律。", "explanation": "这里应该用〈颁布〉。法律由国家机关颁布，发放不能用于法律。"}, {"text": "政府发放了新的税率。", "explanation": "这里应该用〈规定〉。税率是政府规定的，不是一份份分给人的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作人员正在给大家发放了饭票。", "corrected_sentence": "工作人员正在给大家发放饭票。", "error_description": "错误形式是“正在”与动态助词“了”同用。“正在”表示动作进行中，不能再加“了”。应说“正在给大家发放饭票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们去年发放了过一批物资。", "corrected_sentence": "他们去年发放过一批物资。", "error_description": "错误形式是“发放”后同时用了“了”和“过”。“过”表示经历，不能与“了”并用，应说“发放过一批物资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
