INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼是脸上用来看东西的器官。", "primary_collocate": null, "pronunciation": "yǎn", "ipa": "jɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "人有两只眼，一个鼻子。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了他的右眼。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前请闭上眼。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹得他的眼很疼。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在窗前，眼望着远处的山。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子眼里有光。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人一只眼看不见了。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的眼很累，想休息一下。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭红了眼。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睁开眼，天已经亮了。", "target_word": "眼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "双", "label": "量词"}, {"form": "眼睛", "label": "复合"}], "register": "中性", "sense_fingerprint": "脸上用来看东西的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼", "is_correct": true, "explanation": "正确答案：眼，yǎn，指脸上用来看东西的器官。"}, {"text": "严", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟雾。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是燕子。"}, {"text": "样", "is_correct": false, "explanation": "yàng 与 yǎn 韵母不同（ang 与 an），声调也不同（第四声），意思是样子。"}], "explanations": {"眼": "正确答案：眼，yǎn，指脸上用来看东西的器官。", "严": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。", "烟": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟雾。", "燕": "yàn（第四声）与 yǎn（第三声）声调不同，意思是燕子。", "样": "yàng 与 yǎn 韵母不同（ang 与 an），声调也不同（第四声），意思是样子。"}, "sentence_index": null, "correct_answer": "眼"}, "level_3": {"options": [{"text": "眼", "is_correct": true, "explanation": "正确：“两只眼”指人的两只眼睛，与“一个鼻子”相配。"}, {"text": "脑", "is_correct": false, "explanation": "语义：人只有一个脑，不能说“两只脑”。"}, {"text": "心", "is_correct": false, "explanation": "语义：人只有一颗心，不能说“两只心”。"}, {"text": "嘴", "is_correct": false, "explanation": "搭配：嘴用量词“张”计量，句中的“两只”不搭配，应说“两张嘴”。"}], "explanations": {"眼": "正确：“两只眼”指人的两只眼睛，与“一个鼻子”相配。", "脑": "语义：人只有一个脑，不能说“两只脑”。", "心": "语义：人只有一颗心，不能说“两只心”。", "嘴": "搭配：嘴用量词“张”计量，句中的“两只”不搭配，应说“两张嘴”。"}, "sentence_index": 0, "correct_answer": "眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说他的眼下降得很快。", "explanation": "这里应该用〈视力〉。“下降”用于视力、数量，眼睛是器官，不能说它下降。"}, {"text": "他摘下了眼，走到窗边。", "explanation": "这里应该用〈眼镜〉。“摘下”的是眼镜，眼睛是器官，不能摘下。"}, {"text": "她的眼睛痛得厉害，明天要去眼看病。", "explanation": "这里应该用〈眼科〉。看眼病要去“眼科”；“眼”指器官，不是科室，不能作为去处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "眼", "is_correct": true, "explanation": "正确答案：眼，yǎn，指脸上用来看东西的器官。"}, {"text": "养", "is_correct": false, "explanation": "yǎng 与 yǎn 韵母不同（ang 与 an），声调相同，意思是饲养。"}, {"text": "痒", "is_correct": false, "explanation": "yǎng 与 yǎn 韵母不同（ang 与 an），声调相同，意思是发痒。"}, {"text": "扬", "is_correct": false, "explanation": "yáng 与 yǎn 韵母不同（ang 与 an），声调也不同（第二声），意思是飞扬。"}], "explanations": {"眼": "正确答案：眼，yǎn，指脸上用来看东西的器官。", "养": "yǎng 与 yǎn 韵母不同（ang 与 an），声调相同，意思是饲养。", "痒": "yǎng 与 yǎn 韵母不同（ang 与 an），声调相同，意思是发痒。", "扬": "yáng 与 yǎn 韵母不同（ang 与 an），声调也不同（第二声），意思是飞扬。"}, "sentence_index": null, "correct_answer": "眼"}, "level_3": {"options": [{"text": "眼", "is_correct": true, "explanation": "正确：“一只眼”指一只眼睛，“看不见”说的正是视觉器官。"}, {"text": "耳", "is_correct": false, "explanation": "语义：耳朵是听东西的器官，不能说“看不见”。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚不用来看东西，不能说“看不见了”。"}, {"text": "口", "is_correct": false, "explanation": "搭配：“口”用量词“张”计量，不说“一只口”。"}], "explanations": {"眼": "正确：“一只眼”指一只眼睛，“看不见”说的正是视觉器官。", "耳": "语义：耳朵是听东西的器官，不能说“看不见”。", "脚": "语义：脚不用来看东西，不能说“看不见了”。", "口": "搭配：“口”用量词“张”计量，不说“一只口”。"}, "sentence_index": 6, "correct_answer": "眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用眼听到了窗外的鸟叫。", "explanation": "这里应该用〈耳朵〉。眼是用来看东西的器官，听声音要用耳朵。"}, {"text": "她低下头，用眼闻了闻花香。", "explanation": "这里应该用〈鼻子〉。眼用来看，闻气味要用鼻子。"}, {"text": "孩子张开眼，大口吃饭。", "explanation": "这里应该用〈嘴〉。吃饭要张开嘴，眼不能用来吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一个眼盯着屏幕。", "corrected_sentence": "她用一只眼盯着屏幕。", "error_description": "错误：“一个眼”；正确：“一只眼”。眼睛成对，计量单位用“只”，用通用量词“个”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他轻轻眨着一下眼。", "corrected_sentence": "他轻轻眨了一下眼。", "error_description": "错误：“眨着一下眼”；正确：“眨了一下眼”。表示已完成的一次动作要用动态助词“了”，“着”表示持续，与“一下”的完成义冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "示威是很多人站出来大声表示自己不同意。", "primary_collocate": null, "pronunciation": "shì wēi", "ipa": "ʂɨ˥˩ weɪ˥", "syllable_count": 2, "sentences": [{"text": "工人们在公司门口示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们为了反对涨价而示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多市民走上街头示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们站在广场上大声示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们去市政府前面示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机们因为工资太低，一起示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下午，有人在大楼外示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们举着牌子，向政府示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们为了保护公园，天天示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不满意这个决定，所以去示威了。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "示威者", "label": "复合"}, {"form": "示威游行", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多人公开站出来，大声表示不同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。"}, {"text": "视为", "is_correct": false, "explanation": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。"}, {"text": "市委", "is_correct": false, "explanation": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。"}, {"text": "世卫", "is_correct": false, "explanation": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。", "视为": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。", "市委": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。", "世卫": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：许多人公开站出来表示不同意，与“工人们在公司门口”的场景相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：人不能在公司门口“飞”，与“工人们”的动作不相符。"}, {"text": "涨价", "is_correct": false, "explanation": "语义：“涨价”指价格上升，工人不能在公司门口“涨价”，语义不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水域，公司门口没有可以游泳的地方，语义不通。"}], "explanations": {"示威": "示威：许多人公开站出来表示不同意，与“工人们在公司门口”的场景相符。", "飞": "语义：人不能在公司门口“飞”，与“工人们”的动作不相符。", "涨价": "语义：“涨价”指价格上升，工人不能在公司门口“涨价”，语义不通。", "游泳": "语义：“游泳”需要水域，公司门口没有可以游泳的地方，语义不通。"}, "sentence_index": 0, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人在家里示威，没有人看见。", "explanation": "这里应该用〈发脾气〉。示威指多人公开站出来表示不同意，一个人在家里生气不能称为示威。"}, {"text": "大家都为他的成功示威。", "explanation": "这里应该用〈祝贺〉。示威表示不同意或抗议，不用来表示祝贺。"}, {"text": "他一直在图书馆里示威，写完了论文。", "explanation": "这里应该用〈写作〉。示威指为表达抗议或要求而集会游行，在图书馆里写论文不叫示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。"}, {"text": "十位", "is_correct": false, "explanation": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。"}, {"text": "实为", "is_correct": false, "explanation": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。"}, {"text": "施威", "is_correct": false, "explanation": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。", "十位": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。", "实为": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。", "施威": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：许多人公开站出来表示不同意，与“昨天下午，有人在大楼外”的语境相符。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，多用于尊贵的客人，用在这里语域不合。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是书面敬语，用于描述普通人在大楼外的行为，语域不合。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：“打烊”多指商店收工，不用于描述“有人在大楼外”。"}], "explanations": {"示威": "示威：许多人公开站出来表示不同意，与“昨天下午，有人在大楼外”的语境相符。", "驾临": "语域：“驾临”是敬辞，多用于尊贵的客人，用在这里语域不合。", "莅临": "语域：“莅临”是书面敬语，用于描述普通人在大楼外的行为，语域不合。", "打烊": "搭配：“打烊”多指商店收工，不用于描述“有人在大楼外”。"}, "sentence_index": 6, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在教室里示威，聊得很开心。", "explanation": "这里应该用〈聊天〉。示威是为表达抗议或要求而集会游行，同学们在教室里聊天不叫示威。"}, {"text": "我周末去医院示威，祝朋友早日康复。", "explanation": "这里应该用〈探望〉。示威是为表达抗议或要求而集会游行，不用于去医院探望朋友。"}, {"text": "老师在办公室里示威，批改了三十份卷子。", "explanation": "这里应该用〈批改〉。示威指为表达抗议或要求而集会游行，在办公室批改卷子不叫示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们公司示威，要求涨工资。", "corrected_sentence": "工人们向公司示威，要求涨工资。", "error_description": "“示威”是不及物动词，其对象或地点须用介词引出（如“向公司示威”“在公司门口示威”）；漏掉介词后直接说“公司示威”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在校门口大声示威者。", "corrected_sentence": "同学们在校门口大声示威。", "error_description": "“示威”是动词，“示威者”是名词，这里应用动词“示威”，不能加“者”变成名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
