INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用游行、集会等方式显示力量，表达抗议或要求。", "primary_collocate": null, "pronunciation": "shì wēi", "ipa": "ʂɨ˥˩ weɪ˥", "syllable_count": 2, "sentences": [{"text": "他们用游行的方式示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上千人在广场集会示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会组织工人上街示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民们为了环境问题示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在大使馆外示威，要求放人。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们集会示威，要求提高工资。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察拦住了示威的人群。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每个月都在市中心示威一次。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了表达抗议，村民们走到县政府门口示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们举着旗子，在街上示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "示威者", "label": "复合"}, {"form": "示威游行", "label": "复合"}], "register": "中性", "sense_fingerprint": "以游行、集会显示力量，表达抗议或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是用游行、集会等方式显示力量，表达抗议或要求。"}, {"text": "视为", "is_correct": false, "explanation": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。"}, {"text": "市委", "is_correct": false, "explanation": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。"}, {"text": "世卫", "is_correct": false, "explanation": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是用游行、集会等方式显示力量，表达抗议或要求。", "视为": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。", "市委": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。", "世卫": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：以游行的方式显示力量、表达要求，与“他们用游行的方式”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：游行是一种公开的集体行动，不能用来“睡觉”，语义不通。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“用游行的方式写字”无法理解，游行与写字不是同一种行为方式。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“用游行的方式”搭配不通，句子不成立。"}], "explanations": {"示威": "示威：以游行的方式显示力量、表达要求，与“他们用游行的方式”相符。", "睡觉": "语义：游行是一种公开的集体行动，不能用来“睡觉”，语义不通。", "写字": "语义：“用游行的方式写字”无法理解，游行与写字不是同一种行为方式。", "吃饭": "语义：“吃饭”与“用游行的方式”搭配不通，句子不成立。"}, "sentence_index": 0, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民们为了国庆节示威，大家都很开心。", "explanation": "这里应该用〈庆祝〉。示威是为了表达抗议或要求，不用来表示庆祝节日。"}, {"text": "孩子们在操场上示威，玩得很开心。", "explanation": "这里应该用〈游玩〉。示威指为表达抗议或要求而游行、集会，不指游玩。"}, {"text": "他一个人在家里示威，没有人看见。", "explanation": "这里应该用〈抱怨〉。示威要求许多人以游行或集会的方式表达抗议，一个人在家里发牢骚不能称为示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是用游行、集会等方式显示力量，表达抗议或要求。"}, {"text": "十位", "is_correct": false, "explanation": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。"}, {"text": "实为", "is_correct": false, "explanation": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。"}, {"text": "施威", "is_correct": false, "explanation": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是用游行、集会等方式显示力量，表达抗议或要求。", "十位": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。", "实为": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。", "施威": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：以集体游行或集会的方式表达要求，与“警察拦住了……的人群”相符。"}, {"text": "光临", "is_correct": false, "explanation": "语域：“光临”是客套话，多用于顾客，用在警察拦人的场景中语域不合。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是书面敬语，用来描述警察拦人的场面语域不合。"}, {"text": "上映", "is_correct": false, "explanation": "搭配：“上映”多用于电影，不与“人群”搭配，“上映的人群”不符合习惯说法。"}], "explanations": {"示威": "示威：以集体游行或集会的方式表达要求，与“警察拦住了……的人群”相符。", "光临": "语域：“光临”是客套话，多用于顾客，用在警察拦人的场景中语域不合。", "莅临": "语域：“莅临”是书面敬语，用来描述警察拦人的场面语域不合。", "上映": "搭配：“上映”多用于电影，不与“人群”搭配，“上映的人群”不符合习惯说法。"}, "sentence_index": 6, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人们每天在公园示威，锻炼身体。", "explanation": "这里应该用〈锻炼〉。示威指公开表示不满或要求，不用来指锻炼身体。"}, {"text": "母亲们在学校门口示威，等孩子放学。", "explanation": "这里应该用〈等候〉。示威是表达抗议或要求的集体行动，不用于等人。"}, {"text": "他在教室里示威，改作业改到半夜。", "explanation": "这里应该用〈批改〉。示威指为表达抗议或要求而集会游行，在教室里批改作业不叫示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们明天在市政府门口示威了。", "corrected_sentence": "学生们明天在市政府门口示威。", "error_description": "体标错误：“明天”指将来，动作尚未发生，不能用表示完成的“了”；应去掉“了”，说“学生们明天在市政府门口示威”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
