INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93946, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在职权范围内管理、统辖。", "primary_collocate": null, "pronunciation": "guǎn xiá", "ipa": "kwan˨˩ ɕja˧˥", "syllable_count": 2, "sentences": [{"text": "这个区由市政府管辖。", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河归哪个县管辖？", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海关管辖的范围很大。", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个案子由当地法院管辖。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小岛一直由邻国管辖着。", "target_word": "管辖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地归谁管辖，没人说得清。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察不能管辖别的城市。", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所学校归教育局管辖。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山过去由两个县共同管辖。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机构管辖过三个县。", "target_word": "管辖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管辖着", "label": "体标"}, {"form": "管辖过", "label": "体标"}, {"form": "管辖权", "label": "复合"}, {"form": "管辖范围", "label": "复合"}, {"form": "管轄", "label": "繁体"}], "register": "书面", "sense_fingerprint": "机关或政府在职权范围内管理某地区、某事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管辖", "is_correct": true, "explanation": "正确。“管辖”指在职权范围内统辖某地区，市政府对这个区即是如此。"}, {"text": "开采", "is_correct": false, "explanation": "语义：“开采”指从地下取出矿物，不表示行政上的隶属。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”的宾语须是交通工具，不能是“这个区”。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”指挖出地下的东西，与行政隶属无关。"}], "explanations": {"管辖": "正确。“管辖”指在职权范围内统辖某地区，市政府对这个区即是如此。", "开采": "语义：“开采”指从地下取出矿物，不表示行政上的隶属。", "乘坐": "配价：“乘坐”的宾语须是交通工具，不能是“这个区”。", "挖掘": "语义：“挖掘”指挖出地下的东西，与行政隶属无关。"}, "sentence_index": 0, "correct_answer": "管辖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈管辖家里的钱。", "explanation": "这里应该用〈管理〉。“管辖”指行政区域或职权范围内的统辖，家里的钱要用“管理”。"}, {"text": "他管辖一锅汤。", "explanation": "这里应该用〈熬〉。“管辖”指统辖地区或职权范围，熬汤要用“熬”。"}, {"text": "保姆管辖小孩。", "explanation": "这里应该用〈看管〉。“管辖”针对地区和事务，不能用于照看小孩，要用“看管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管辖", "is_correct": true, "explanation": "正确。警察的职权范围有限，不能统辖别的城市。"}, {"text": "逮捕", "is_correct": false, "explanation": "配价：“逮捕”的对象须是人，不能用于“城市”。"}, {"text": "抓获", "is_correct": false, "explanation": "配价：“抓获”的对象是人或物，城市不能被抓获。"}, {"text": "举报", "is_correct": false, "explanation": "语义：“举报”指检举违法的人或事，不能用于城市。"}], "explanations": {"管辖": "正确。警察的职权范围有限，不能统辖别的城市。", "逮捕": "配价：“逮捕”的对象须是人，不能用于“城市”。", "抓获": "配价：“抓获”的对象是人或物，城市不能被抓获。", "举报": "语义：“举报”指检举违法的人或事，不能用于城市。"}, "sentence_index": 6, "correct_answer": "管辖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计管辖账目。", "explanation": "这里应该用〈掌管〉。“管辖”指地区或职权范围的统辖，账目的保管要用“掌管”。"}, {"text": "护士管辖病人。", "explanation": "这里应该用〈照料〉。“管辖”不用于照顾人，护士照料病人要用“照料”。"}, {"text": "司机管辖方向盘。", "explanation": "这里应该用〈控制〉。“管辖”针对地区和事务，操纵方向盘要用“控制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛曾经由邻国管辖着过。", "corrected_sentence": "这个岛曾经由邻国管辖过。", "error_description": "体标错误：“着”表示持续，“过”表示经历，二者不能叠用在“管辖”之后。应只用经历体“过”，说“管辖过”，错误形式是“管辖着过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海关管辖。", "corrected_sentence": "海关管辖这个港口。", "error_description": "配价错误：主动句“海关管辖”须说出管辖的对象；应说“海关管辖这个港口”，或改用“这个港口由海关管辖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
