INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "丝是又细又长的线，比如蚕吐出来的。", "primary_collocate": null, "pronunciation": "sī", "ipa": "sɨ⁵⁵", "syllable_count": 1, "sentences": [{"text": "蚕吐出来的丝又细又长。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蚕正在吐丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是用丝做的。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚕宝宝吐丝，把自己包起来了。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根丝很细，几乎看不见。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛吐的丝很细，能粘住小虫。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛也会吐丝织网。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚕吐的丝可以织成漂亮的布。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一团白色的丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丝越拉越长，一下子断了。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絲", "label": "繁体"}, {"form": "蚕丝", "label": "复合"}, {"form": "一根丝", "label": "量词"}], "register": "中性", "sense_fingerprint": "蚕等吐出的又细又长的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝（sī）：蚕吐出的又细又长的线，与所听到的词相符。"}, {"text": "四", "is_correct": false, "explanation": "sì（第四声）与 sī（第一声）声调不同，意思是数字“四”。"}, {"text": "死", "is_correct": false, "explanation": "sǐ（第三声）与 sī（第一声）声调不同，意思是死亡。"}, {"text": "师", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是老师。"}, {"text": "诗", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是诗歌。"}], "explanations": {"丝": "丝（sī）：蚕吐出的又细又长的线，与所听到的词相符。", "四": "sì（第四声）与 sī（第一声）声调不同，意思是数字“四”。", "死": "sǐ（第三声）与 sī（第一声）声调不同，意思是死亡。", "师": "shī 与 sī 声母不同（sh 与 s），意思是老师。", "诗": "shī 与 sī 声母不同（sh 与 s），意思是诗歌。"}, "sentence_index": null, "correct_answer": "丝"}, "level_3": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝：蚕吐出的细长纤维，与“吐出来”“又细又长”相符，句意通顺。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发不是蚕吐出来的，“蚕吐出来的”只能指丝。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“吐出来”说吐丝、泡沫，不说吐出面条。"}, {"text": "树根", "is_correct": false, "explanation": "语义：树根不是蚕吐出的东西，与句子的主语“蚕”不符。"}], "explanations": {"丝": "丝：蚕吐出的细长纤维，与“吐出来”“又细又长”相符，句意通顺。", "头发": "语义：头发不是蚕吐出来的，“蚕吐出来的”只能指丝。", "面条": "搭配：“吐出来”说吐丝、泡沫，不说吐出面条。", "树根": "语义：树根不是蚕吐出的东西，与句子的主语“蚕”不符。"}, "sentence_index": 0, "correct_answer": "丝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的丝断了，他只好换一根新的。", "explanation": "这里应该用〈腿〉。丝指蚕丝等细软纤维，椅子的支撑部件要说“腿”，不能说“丝”。"}, {"text": "这根丝很结实，可以挑两桶水。", "explanation": "这里应该用〈扁担〉。丝是细软的纤维，挑水要用扁担这样结实的长条木器，丝不能指扁担。"}, {"text": "他坐在一根丝上休息。", "explanation": "这里应该用〈凳子〉。丝是又细又软的线，不能用来坐，坐着休息要说“凳子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93947, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝（sī）：蚕吐出的又细又长的线，与所听到的词相符。"}, {"text": "似", "is_correct": false, "explanation": "sì（第四声）与 sī（第一声）声调不同，意思是“好像”。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 sī 声母不同（z 与 s），意思是资金、资料。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是失去。"}, {"text": "湿", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是潮湿。"}], "explanations": {"丝": "丝（sī）：蚕吐出的又细又长的线，与所听到的词相符。", "似": "sì（第四声）与 sī（第一声）声调不同，意思是“好像”。", "资": "zī 与 sī 声母不同（z 与 s），意思是资金、资料。", "失": "shī 与 sī 声母不同（sh 与 s），意思是失去。", "湿": "shī 与 sī 声母不同（sh 与 s），意思是潮湿。"}, "sentence_index": null, "correct_answer": "丝"}, "level_3": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝：蚕或蜘蛛吐出的细线，与“吐”搭配，句意通顺。"}, {"text": "唾沫", "is_correct": false, "explanation": "语义：唾沫不能用来织网，句意不通。"}, {"text": "血", "is_correct": false, "explanation": "语义：血不是织网的材料，蜘蛛也不会吐血织网。"}, {"text": "胶水", "is_correct": false, "explanation": "搭配：“吐”一般说吐丝、吐泡沫，不说吐胶水。"}], "explanations": {"丝": "丝：蚕或蜘蛛吐出的细线，与“吐”搭配，句意通顺。", "唾沫": "语义：唾沫不能用来织网，句意不通。", "血": "语义：血不是织网的材料，蜘蛛也不会吐血织网。", "胶水": "搭配：“吐”一般说吐丝、吐泡沫，不说吐胶水。"}, "sentence_index": 6, "correct_answer": "丝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家里的电话丝被风吹断了。", "explanation": "这里应该用〈线〉。丝指蚕丝等细软纤维，电话线是导线，不能说“电话丝”。"}, {"text": "妈妈煮了一根丝当早饭。", "explanation": "这里应该用〈面条〉。丝指又细又长的线，煮早饭的面条要说“面条”，丝不能指食物。"}, {"text": "他骑着一根丝去上班。", "explanation": "这里应该用〈自行车〉。丝是细软的线，不能用来骑行，骑车上班要说“自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上放着一片丝。", "corrected_sentence": "桌上放着一缕丝。", "error_description": "“丝”作细长纤维时量词用“缕”或“根”，说“一片丝”是错的，“片”用于平面的东西。正确说法是“一缕丝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蚕吐丝完以后，就开始结茧。", "corrected_sentence": "蚕吐完丝以后，就开始结茧。", "error_description": "结果补语“完”要紧跟动词，应说“吐完丝”，说“吐丝完”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
