INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蚕吐出的细线，或形状像丝的细长物。", "primary_collocate": null, "pronunciation": "sī", "ipa": "sɨ⁵⁵", "syllable_count": 1, "sentences": [{"text": "请把土豆切成丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把肉切成丝，准备炒菜。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜里的萝卜要切成丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把姜切成丝，放进汤里。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把葱切成丝放在鱼上。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会把青椒切成丝吗？", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄瓜先切片，再切成丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把青菜切成丝，用油炒一下。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把鸡肉撕成丝，再拌上酱。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把胡萝卜洗干净，再切成丝。", "target_word": "丝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絲", "label": "繁体"}, {"form": "肉丝", "label": "复合"}, {"form": "土豆丝", "label": "复合"}], "register": "中性", "sense_fingerprint": "形状像线的细长条，如切成细条的菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝（sī）：形状像线的细长条，与所听到的词相符。"}, {"text": "四", "is_correct": false, "explanation": "sì（第四声）与 sī（第一声）声调不同，意思是数字“四”。"}, {"text": "死", "is_correct": false, "explanation": "sǐ（第三声）与 sī（第一声）声调不同，意思是死亡。"}, {"text": "施", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是施行、施加。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是失去。"}], "explanations": {"丝": "丝（sī）：形状像线的细长条，与所听到的词相符。", "四": "sì（第四声）与 sī（第一声）声调不同，意思是数字“四”。", "死": "sǐ（第三声）与 sī（第一声）声调不同，意思是死亡。", "施": "shī 与 sī 声母不同（sh 与 s），意思是施行、施加。", "失": "shī 与 sī 声母不同（sh 与 s），意思是失去。"}, "sentence_index": null, "correct_answer": "丝"}, "level_3": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝：切成的细条，与“切成”搭配，句意通顺。"}, {"text": "雨", "is_correct": false, "explanation": "语义：土豆不能切成雨，句意不通。"}, {"text": "灰", "is_correct": false, "explanation": "语义：切不出灰，“切成灰”与句意不符。"}, {"text": "粉", "is_correct": false, "explanation": "搭配：“切”一般不说切成粉，粉要说磨或研。"}], "explanations": {"丝": "丝：切成的细条，与“切成”搭配，句意通顺。", "雨": "语义：土豆不能切成雨，句意不通。", "灰": "语义：切不出灰，“切成灰”与句意不符。", "粉": "搭配：“切”一般不说切成粉，粉要说磨或研。"}, "sentence_index": 0, "correct_answer": "丝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把长发编成了丝。", "explanation": "这里应该用〈辫子〉。丝指细长的线或形状像丝的细长物，编好的头发要说“辫子”，不能说“丝”。"}, {"text": "他把西瓜切成了丝，分给大家吃。", "explanation": "这里应该用〈块〉。西瓜分给大家吃要切成“块”，不会切成细长的丝。"}, {"text": "他把钢管锯成了丝。", "explanation": "这里应该用〈段〉。钢管是硬的管子，锯开要说“锯成几段”，不能说“锯成丝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93948, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝（sī）：形状像线的细长条，与所听到的词相符。"}, {"text": "似", "is_correct": false, "explanation": "sì（第四声）与 sī（第一声）声调不同，意思是“好像”。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 sī 声母不同（z 与 s），意思是资金、资料。"}, {"text": "诗", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是诗歌。"}, {"text": "湿", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），意思是潮湿。"}], "explanations": {"丝": "丝（sī）：形状像线的细长条，与所听到的词相符。", "似": "sì（第四声）与 sī（第一声）声调不同，意思是“好像”。", "资": "zī 与 sī 声母不同（z 与 s），意思是资金、资料。", "诗": "shī 与 sī 声母不同（sh 与 s），意思是诗歌。", "湿": "shī 与 sī 声母不同（sh 与 s），意思是潮湿。"}, "sentence_index": null, "correct_answer": "丝"}, "level_3": {"options": [{"text": "丝", "is_correct": true, "explanation": "丝：切成的细条，与“切成”搭配，句意通顺。"}, {"text": "书", "is_correct": false, "explanation": "语义：黄瓜不能切成书，句意不通。"}, {"text": "雪", "is_correct": false, "explanation": "语义：黄瓜不能切成雪，句意不通。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“切”一般不说切成汤，汤要说煮或熬。"}], "explanations": {"丝": "丝：切成的细条，与“切成”搭配，句意通顺。", "书": "语义：黄瓜不能切成书，句意不通。", "雪": "语义：黄瓜不能切成雪，句意不通。", "汤": "搭配：“切”一般不说切成汤，汤要说煮或熬。"}, "sentence_index": 6, "correct_answer": "丝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一条丝当晚饭。", "explanation": "这里应该用〈鱼〉。丝不能作为晚饭的食材，买来做菜的是鱼，应说“一条鱼”。"}, {"text": "他用一根丝削铅笔。", "explanation": "这里应该用〈小刀〉。丝是细长的条，不能用来削东西，削铅笔要用“小刀”。"}, {"text": "他用一根丝把墙钉牢了。", "explanation": "这里应该用〈钉子〉。丝是细长的条，不能用来钉墙，钉墙要用“钉子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把洋葱切丝成，凉拌着吃。", "corrected_sentence": "把洋葱切成丝，凉拌着吃。", "error_description": "“成”是结果补语，要紧跟动词，应说“切成丝”，“切丝成”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胡萝卜切成丝着以后，倒进油里炒。", "corrected_sentence": "胡萝卜切成丝以后，倒进油里炒。", "error_description": "“着”不能接在结果补语“成丝”后面，应去掉“着”，说“切成丝以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
