INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部加起来的数目。", "primary_collocate": null, "pronunciation": "zǒng shù", "ipa": "tsʊŋ˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这家店今年卖出的书，总数是两千本。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车票的总数已经超过了一万张。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学的作业总数是四十份。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我客人的总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年游客的总数比今年少。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里鱼的总数一直在减少。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这片森林里的树的总数吗？", "target_word": "总数", "complexity_tier": "T3", "furigana": "nǐ zhī dào zhè piàn sēn lín lǐ de shù de zǒng shù ma", "sentence_source": "generated"}, {"text": "所有国家的人口总数很大。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了题目的总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西的总数不到一百。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全部合计起来的数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部合计起来的数目。"}, {"text": "综述", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。"}, {"text": "种数", "is_correct": false, "explanation": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。"}, {"text": "总序", "is_correct": false, "explanation": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}], "explanations": {"总数": "正确。总数指全部合计起来的数目。", "综述": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。", "种数": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。", "总序": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。“总数”指卖出的书加起来的数目，是两千本。"}, {"text": "利润", "is_correct": false, "explanation": "语义：“利润”指卖书后赚得的钱，不是卖出书的数目。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”是钱款，不能用“两千本”来计量。"}, {"text": "页数", "is_correct": false, "explanation": "语义：“页数”指书有多少页，不是卖出的本数。"}], "explanations": {"总数": "正确。“总数”指卖出的书加起来的数目，是两千本。", "利润": "语义：“利润”指卖书后赚得的钱，不是卖出书的数目。", "价格": "搭配：“价格”是钱款，不能用“两千本”来计量。", "页数": "语义：“页数”指书有多少页，不是卖出的本数。"}, "sentence_index": 0, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的总数是一百八十厘米。", "explanation": "这里应该用〈身高〉。“总数”指个数的合计，人的高矮要用“身高”来说。"}, {"text": "这箱苹果的总数有十公斤。", "explanation": "这里应该用〈总量〉。公斤是重量单位，“总数”只用于可以一个个数的东西，重量要用“总量”。"}, {"text": "他的友谊总数很深。", "explanation": "这里误把〈总数〉当成了〈总体〉的意思（整体程度）。“总数”只指加起来的数目，“友谊”不能数，应说“友谊很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL