INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部合计起来的数目。"}, {"text": "总是", "is_correct": false, "explanation": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”。"}, {"text": "总署", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是“中央的总管理机构”，如“海关总署”。"}, {"text": "综述", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。"}], "explanations": {"总数": "正确。总数指全部合计起来的数目。", "总是": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”。", "总署": "shǔ（第三声）与 shù（第四声）声调不同，意思是“中央的总管理机构”，如“海关总署”。", "综述": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。“总数”指树的数目的合计。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是付给人的报酬，树不领工资。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习或比赛的结果，不能用于树。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是交给学校的钱，树不交学费，句子不通。"}], "explanations": {"总数": "正确。“总数”指树的数目的合计。", "工资": "语义：“工资”是付给人的报酬，树不领工资。", "成绩": "语义：“成绩”指学习或比赛的结果，不能用于树。", "学费": "语义：“学费”是交给学校的钱，树不交学费，句子不通。"}, "sentence_index": 6, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份饭的总数是八百大卡。", "explanation": "这里应该用〈热量〉。“总数”指个数的合计，热量的多少要用“热量”来说。"}, {"text": "这块地的总数是五亩。", "explanation": "这里应该用〈面积〉。“总数”只用于可以数的东西，土地大小要用“面积”。"}, {"text": "汽车的总数是一百公里每小时。", "explanation": "这里应该用〈速度〉。“总数”指个数的合计，车行的快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们算出了全部客人的一总数。", "corrected_sentence": "我们算出了全部客人的总数。", "error_description": "数量词错误：“总数”前不能直接加数词“一”，多出的“一”应删去，说“算出了全部客人的总数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的毕业生总数是三百本。", "corrected_sentence": "这所学校的毕业生总数是三百人。", "error_description": "量词错误：“毕业生”是人，计数应用“人”，不能用“本”。错误形式“三百本”，应改为“三百人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
