INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93953, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "要么是说有两件事，只选一件。", "primary_collocate": null, "pronunciation": "yào me", "ipa": "jɑʊ˥˩ mə", "syllable_count": 2, "sentences": [{"text": "周末我要么看书，要么去公园走走。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭你要么吃米饭，要么吃面条。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要么你来我家，要么我去你家。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天要么骑车，要么坐地铁上班。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京，要么坐飞机，要么坐火车。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要么你做，要么我做，别问了。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天他要么在家睡觉，要么在外面踢球。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要么现在走，要么再等一个小时。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要么去海边，要么去山上玩。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚要么我做饭，要么我们出去吃。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "要么……要么……，两件事只选其中一件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不表示二选一，与后面的“要么”冲突"}, {"text": "要么", "is_correct": true, "explanation": "要么表示两件事只选一件，与后面的“要么”成对使用，语境吻合"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，此处前后并没有转折关系"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示因果，需要前因后果，不能与“要么”的选择关系搭配"}], "explanations": {"而且": "语义：“而且”表示递进或并列，不表示二选一，与后面的“要么”冲突", "要么": "要么表示两件事只选一件，与后面的“要么”成对使用，语境吻合", "但是": "语义：“但是”表示转折，此处前后并没有转折关系", "所以": "搭配：“所以”表示因果，需要前因后果，不能与“要么”的选择关系搭配"}, "sentence_index": 0, "correct_answer": "要么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很高兴，要么笑了起来。", "explanation": "这里应该用〈于是〉。要么表示二选一，不表示承接，承接要用于是"}, {"text": "他很聪明，要么很努力。", "explanation": "这里应该用〈并且〉。要么只表示二选一，两种性质都成立时要用并且"}, {"text": "这个房间很大，要么很亮。", "explanation": "这里应该用〈而且〉。要么表示选择，不表示并列补充，描述两种性质要用而且"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，不表示二选一，与“要么”的选择关系冲突"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”表示承接因果，前后没有因果关系，不能与“要么”搭配"}, {"text": "要么", "is_correct": true, "explanation": "要么表示两件事只选一件，与后面的“要么”成对使用，语境吻合"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，与前面二选一的语境不相符"}], "explanations": {"然后": "语义：“然后”表示时间先后，不表示二选一，与“要么”的选择关系冲突", "于是": "搭配：“于是”表示承接因果，前后没有因果关系，不能与“要么”搭配", "要么": "要么表示两件事只选一件，与后面的“要么”成对使用，语境吻合", "不然": "语义：“不然”表示否则，与前面二选一的语境不相符"}, "sentence_index": 6, "correct_answer": "要么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先洗澡，要么吃饭。", "explanation": "这里应该用〈然后〉。要么表示二选一，不能表示先后顺序，先后要用然后"}, {"text": "我想去，要么没有时间。", "explanation": "这里应该用〈可是〉。要么不表示转折，表示转折要用可是"}, {"text": "要么明天下雨，我们就不去。", "explanation": "这里应该用〈如果〉。要么表示二选一，不表示假设条件，假设要用如果"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我在家看书，要么去公园。", "corrected_sentence": "周末我要么在家看书，要么去公园。", "error_description": "错误：漏掉了第一个“要么”。“要么”要成对使用表示二选一，正确为“周末我要么在家看书，要么去公园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我要么留在家里，还是去看电影。", "corrected_sentence": "明天我要么留在家里，要么去看电影。", "error_description": "错误：第二个分句的“要么”被“还是”替换。“要么”与“要么”成对表示二选一，不能与“还是”混用，正确为“……要么去看电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
