INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93954, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在两种情况中选择其一。", "primary_collocate": null, "pronunciation": "yào me", "ipa": "jɑʊ˥˩ mə", "syllable_count": 2, "sentences": [{"text": "你要么听我的，要么自己决定。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末要么下雨，要么刮风，不能去玩了。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要么多花点钱，要么买便宜一点的。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要么不说话，要么一说就很长。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要么哭，要么笑，一刻也不安静。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要么马上回家，要么给妈妈打电话。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机要么放在桌上，要么放进包里。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要么学英语，要么学法语，不要都学。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回家的路上，我要么走路，要么坐公交车。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要么我送你去，要么你自己坐车去。", "target_word": "要么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词，在两种情况或办法中选择其一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示并列递进，不表示二选一，与后面的“要么”冲突"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，此处前后没有转折关系"}, {"text": "要么", "is_correct": true, "explanation": "要么表示在两种情况中选择其一，与后面的“要么”成对使用，语境吻合"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”表示因果，“听我的”与“自己决定”之间不构成因果，不能搭配"}], "explanations": {"而且": "语义：“而且”表示并列递进，不表示二选一，与后面的“要么”冲突", "但是": "语义：“但是”表示转折，此处前后没有转折关系", "要么": "要么表示在两种情况中选择其一，与后面的“要么”成对使用，语境吻合", "因此": "搭配：“因此”表示因果，“听我的”与“自己决定”之间不构成因果，不能搭配"}, "sentence_index": 0, "correct_answer": "要么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很累，要么还在工作。", "explanation": "这里应该用〈但是〉。要么不表示转折，转折要用但是"}, {"text": "我们一起吃饭，要么聊天。", "explanation": "这里应该用〈并且〉。要么只表示在两种情况中选其一，同时进行的并列要用并且"}, {"text": "要么你同意，我们就出发。", "explanation": "这里应该用〈如果〉。要么表示选择，不表示假设条件，假设要用如果"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并且", "is_correct": false, "explanation": "语义：“并且”表示并列，不表示二选一，与“要么”的选择关系冲突"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，不表示选择，与后面的“要么”不相符"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”表示承接因果，此处前后没有因果关系，不能搭配"}, {"text": "要么", "is_correct": true, "explanation": "要么表示在两种情况中选择其一，与后面的“要么”成对使用，语境吻合"}], "explanations": {"并且": "语义：“并且”表示并列，不表示二选一，与“要么”的选择关系冲突", "然后": "语义：“然后”表示先后顺序，不表示选择，与后面的“要么”不相符", "于是": "搭配：“于是”表示承接因果，此处前后没有因果关系，不能搭配", "要么": "要么表示在两种情况中选择其一，与后面的“要么”成对使用，语境吻合"}, "sentence_index": 6, "correct_answer": "要么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先写作业，要么看电视。", "explanation": "这里应该用〈然后〉。要么表示选择，不表示先后顺序，先后要用然后"}, {"text": "下雨了，要么我没出门。", "explanation": "这里应该用〈所以〉。要么表示二选一，不表示因果，因果要用所以"}, {"text": "下课了，要么大家都走了出去。", "explanation": "这里应该用〈于是〉。要么表示二选一，不表示承接，承接要用于是"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的聚会在我家，要么在你家。", "corrected_sentence": "明天的聚会要么在我家，要么在你家。", "error_description": "错误：漏掉了第一个“要么”。“要么”要成对使用表示选择，正确为“明天的聚会要么在我家，要么在你家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "票要么现在买，还是等明天再买。", "corrected_sentence": "票要么现在买，要么等明天再买。", "error_description": "错误：第二个分句的“要么”被“还是”替换。“要么”与“要么”成对表示二选一，不能与“还是”混用，正确为“……要么等明天再买”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
