INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93955, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "见得是看得出来，说得出来。", "primary_collocate": null, "pronunciation": "jiàn de", "ipa": "tɕjɛn˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "你怎么见得他没有说谎？", "target_word": "见得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "凭什么见得他是好人？", "target_word": "见得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你凭什么见得这个办法有用？", "target_word": "见得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说他累了，怎么见得？", "target_word": "见得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这话怎么见得是对的？", "target_word": "见得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他笑得很大声，你怎么见得他高兴？", "target_word": "见得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上是湿的，怎么见得昨晚下过雨？", "target_word": "见得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说话，你怎么见得他生气了？", "target_word": "见得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事怎么见得是他做的？", "target_word": "见得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直坐着，你怎么见得他不累？", "target_word": "见得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見得", "label": "繁体"}, {"form": "怎么见得", "label": "复合"}, {"form": "何以见得", "label": "复合"}], "register": "口语", "sense_fingerprint": "多用于“怎么见得”“何以见得”，询问凭什么看出来、凭什么这样说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见得", "is_correct": true, "explanation": "「怎么见得」表示凭什么看出，与“你怎么……他没有说谎”相合。"}, {"text": "逃", "is_correct": false, "explanation": "语义：「逃」表示躲避，不能表示凭什么做出判断。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：「烧」不能带“他没有说谎”这类小句作宾语。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」需要具体物件作宾语，不能接小句。"}], "explanations": {"见得": "「怎么见得」表示凭什么看出，与“你怎么……他没有说谎”相合。", "逃": "语义：「逃」表示躲避，不能表示凭什么做出判断。", "烧": "搭配：「烧」不能带“他没有说谎”这类小句作宾语。", "搬": "配价：「搬」需要具体物件作宾语，不能接小句。"}, "sentence_index": 0, "correct_answer": "见得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我跟他约好明天在车站见得。", "explanation": "这里应该用〈见面〉。见得不表示与人碰面，约见要说见面。"}, {"text": "我在路口见得了一位老朋友。", "explanation": "这里应该用〈遇见〉。见得不表示偶然碰到人。"}, {"text": "我在楼上见得了吵闹声。", "explanation": "这里应该用〈听见〉。见得不表示听到声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见得", "is_correct": true, "explanation": "「怎么见得」表示凭什么看出，与“地上是湿的……下过雨”相合。"}, {"text": "扫", "is_correct": false, "explanation": "语义：「扫」指清除尘土，不能表示根据现象推断。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」的宾语是可擦拭的东西，不能接“昨晚下过雨”。"}, {"text": "切", "is_correct": false, "explanation": "配价：「切」需要具体物体作宾语，不能接小句。"}], "explanations": {"见得": "「怎么见得」表示凭什么看出，与“地上是湿的……下过雨”相合。", "扫": "语义：「扫」指清除尘土，不能表示根据现象推断。", "擦": "搭配：「擦」的宾语是可擦拭的东西，不能接“昨晚下过雨”。", "切": "配价：「切」需要具体物体作宾语，不能接小句。"}, "sentence_index": 6, "correct_answer": "见得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在厨房见得了饭香。", "explanation": "这里应该用〈闻到〉。见得不表示用鼻子闻到气味。"}, {"text": "我们好久没见得了，真想你。", "explanation": "这里应该用〈见面〉。见得表示凭什么看出来，不表示人与人相见。"}, {"text": "我昨天在电视上见得了那位明星。", "explanation": "这里应该用〈看见〉。见得不表示用眼睛看到某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你凭什么见得的这份计划能成功？", "corrected_sentence": "你凭什么见得这份计划能成功？", "error_description": "错误形式是在“见得”后多加了“的”。“见得”之后直接接小句，不能加“的”。应说“你凭什么见得这份计划能成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你怎么见得的这封信是他写的？", "corrected_sentence": "你怎么见得这封信是他写的？", "error_description": "错误形式是在“见得”后多加了“的”。“见得”之后直接接小句，不能加“的”。应说“你怎么见得这封信是他写的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
