INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93957, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "踢是用脚去碰东西，让它飞出去。", "primary_collocate": null, "pronunciation": "tī", "ipa": "tʰi˥", "syllable_count": 1, "sentences": [{"text": "他用力踢了一下球，球飞过了墙。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把球踢给了弟弟。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公园里踢过足球。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上踢着球。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚把门口的石头踢进了河里。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员踢出了一个漂亮的球。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑过来，把我踢出去的球叼走了。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹把毽子踢得很高。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员踢了球，球飞到了对面。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把空瓶子踢到了马路上。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "踢了", "label": "体标"}, {"form": "踢过", "label": "体标"}, {"form": "踢着", "label": "体标"}, {"form": "踢球", "label": "复合"}], "register": "中性", "sense_fingerprint": "用脚把东西踢飞出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 毽 (Zipf 1.86)']::text[], '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93957, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢（tī，第一声）指用脚碰击，使物体飞出去，与题目要求一致。"}, {"text": "提", "is_correct": false, "explanation": "提（tí，第二声）与 tī（第一声）声调不同，意思是拿、提起。"}, {"text": "体", "is_correct": false, "explanation": "体（tǐ，第三声）与 tī（第一声）声调不同，意思是身体。"}, {"text": "替", "is_correct": false, "explanation": "替（tì，第四声）与 tī（第一声）声调不同，意思是代替。"}, {"text": "低", "is_correct": false, "explanation": "低（dī，第一声）与 tī 声母不同（d 与 t），意思是低矮。"}, {"text": "西", "is_correct": false, "explanation": "西（xī，第一声）与 tī（第一声）仅声母不同（x 与 t），意思是西边、西方。"}], "explanations": {"踢": "踢（tī，第一声）指用脚碰击，使物体飞出去，与题目要求一致。", "提": "提（tí，第二声）与 tī（第一声）声调不同，意思是拿、提起。", "体": "体（tǐ，第三声）与 tī（第一声）声调不同，意思是身体。", "替": "替（tì，第四声）与 tī（第一声）声调不同，意思是代替。", "低": "低（dī，第一声）与 tī 声母不同（d 与 t），意思是低矮。", "西": "西（xī，第一声）与 tī（第一声）仅声母不同（x 与 t），意思是西边、西方。"}, "sentence_index": null, "correct_answer": "踢"}, "level_3": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢指用脚或类似动作猛力击出，与“用力……一下”及“飞过了墙”相符。"}, {"text": "捡", "is_correct": false, "explanation": "语义：“捡”是拾起，不会让球飞过墙。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”是双臂环拢，不能使球飞过墙。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”是轻触，不说“用力摸一下球，球飞过了墙”。"}], "explanations": {"踢": "踢指用脚或类似动作猛力击出，与“用力……一下”及“飞过了墙”相符。", "捡": "语义：“捡”是拾起，不会让球飞过墙。", "抱": "语义：“抱”是双臂环拢，不能使球飞过墙。", "摸": "搭配：“摸”是轻触，不说“用力摸一下球，球飞过了墙”。"}, "sentence_index": 0, "correct_answer": "踢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手踢了一下桌子。", "explanation": "这里应该用〈拍〉。踢必须用脚碰击，用手击打桌子要说拍。"}, {"text": "他用球拍踢了一下球。", "explanation": "这里应该用〈打〉。踢必须用脚，用球拍击球要说打。"}, {"text": "他跑得太快，一头踢在了门框上。", "explanation": "这里应该用〈撞〉。踢必须用脚，用头碰撞门框要说撞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93957, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢（tī，第一声）指用脚碰击，使物体飞出去，与题目要求一致。"}, {"text": "题", "is_correct": false, "explanation": "题（tí，第二声）与 tī（第一声）声调不同，意思是题目。"}, {"text": "剃", "is_correct": false, "explanation": "剃（tì，第四声）与 tī（第一声）声调不同，意思是用刀去掉毛发。"}, {"text": "滴", "is_correct": false, "explanation": "滴（dī，第一声）与 tī 声母不同（d 与 t），意思是液体一点一点落下。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī，第一声）与 tī（第一声）仅声母不同（j 与 t），意思是家禽。"}], "explanations": {"踢": "踢（tī，第一声）指用脚碰击，使物体飞出去，与题目要求一致。", "题": "题（tí，第二声）与 tī（第一声）声调不同，意思是题目。", "剃": "剃（tì，第四声）与 tī（第一声）声调不同，意思是用刀去掉毛发。", "滴": "滴（dī，第一声）与 tī 声母不同（d 与 t），意思是液体一点一点落下。", "鸡": "鸡（jī，第一声）与 tī（第一声）仅声母不同（j 与 t），意思是家禽。"}, "sentence_index": null, "correct_answer": "踢"}, "level_3": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢指用脚猛力击出，与“把我……出去的球”中球被击出去的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用于球，不说“吃出去的球”。"}, {"text": "收", "is_correct": false, "explanation": "搭配：“收”指收回，不说“收出去的球”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬合，不能使球飞出去。"}], "explanations": {"踢": "踢指用脚猛力击出，与“把我……出去的球”中球被击出去的语境相符。", "吃": "搭配：“吃”不能用于球，不说“吃出去的球”。", "收": "搭配：“收”指收回，不说“收出去的球”。", "咬": "语义：“咬”是用牙齿咬合，不能使球飞出去。"}, "sentence_index": 6, "correct_answer": "踢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用棍子踢了踢那个洞。", "explanation": "这里应该用〈捅〉。踢是用脚碰击，用棍子戳洞口要说捅。"}, {"text": "他用嘴踢了一下那个苹果。", "explanation": "这里应该用〈咬〉。踢必须用脚，用嘴对苹果的动作要说咬。"}, {"text": "他用抹布踢了踢桌子。", "explanation": "这里应该用〈擦〉。踢必须用脚，用抹布擦拭桌子要说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prom