INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抬起脚用力碰击。", "primary_collocate": null, "pronunciation": "tī", "ipa": "tʰi˥", "syllable_count": 1, "sentences": [{"text": "他生气地踢了一下桌子。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那匹马踢了我一脚，我疼得叫了起来。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别踢门，里面的人在睡觉。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在梦里踢着被子。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚踢在墙上，脚疼了好几天。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着踢地板。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用脚轻轻踢了踢我，让我别说话。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，这头驴会踢人。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他气得踢翻了椅子。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人踢了我的椅子，我回头看了看。", "target_word": "踢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "踢了", "label": "体标"}, {"form": "踢过", "label": "体标"}, {"form": "踢着", "label": "体标"}, {"form": "踢翻", "label": "复合"}], "register": "中性", "sense_fingerprint": "抬脚用力碰击人或物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢（tī，第一声）指抬脚用力碰击，与题目要求一致。"}, {"text": "提", "is_correct": false, "explanation": "提（tí，第二声）与 tī（第一声）声调不同，意思是拿、提起。"}, {"text": "体", "is_correct": false, "explanation": "体（tǐ，第三声）与 tī（第一声）声调不同，意思是身体。"}, {"text": "替", "is_correct": false, "explanation": "替（tì，第四声）与 tī（第一声）声调不同，意思是代替。"}, {"text": "西", "is_correct": false, "explanation": "西（xī，第一声）与 tī（第一声）仅声母不同（x 与 t），意思是西边、西方。"}], "explanations": {"踢": "踢（tī，第一声）指抬脚用力碰击，与题目要求一致。", "提": "提（tí，第二声）与 tī（第一声）声调不同，意思是拿、提起。", "体": "体（tǐ，第三声）与 tī（第一声）声调不同，意思是身体。", "替": "替（tì，第四声）与 tī（第一声）声调不同，意思是代替。", "西": "西（xī，第一声）与 tī（第一声）仅声母不同（x 与 t），意思是西边、西方。"}, "sentence_index": null, "correct_answer": "踢"}, "level_3": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢指抬脚用力碰击，与“生气地”的动作语境相符。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不带物体宾语，不能说笑桌子。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”是轻触，与“生气地”所表达的用力动作不合。"}, {"text": "扶", "is_correct": false, "explanation": "搭配：“扶”是支撑，生气时不说“生气地扶了一下桌子”。"}], "explanations": {"踢": "踢指抬脚用力碰击，与“生气地”的动作语境相符。", "笑": "搭配：“笑”不带物体宾语，不能说笑桌子。", "摸": "语义：“摸”是轻触，与“生气地”所表达的用力动作不合。", "扶": "搭配：“扶”是支撑，生气时不说“生气地扶了一下桌子”。"}, "sentence_index": 0, "correct_answer": "踢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手踢了踢桌子。", "explanation": "这里应该用〈拍〉。踢必须用脚，用手碰击桌子要说拍。"}, {"text": "他一步就踢过了那道小沟。", "explanation": "这里应该用〈跨〉。踢是用脚碰击使东西飞出去，人越过沟要说跨。"}, {"text": "他用棍子踢了踢洞口。", "explanation": "这里应该用〈捅〉。踢必须用脚，用棍子戳洞口要说捅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢（tī，第一声）指抬脚用力碰击，与题目要求一致。"}, {"text": "题", "is_correct": false, "explanation": "题（tí，第二声）与 tī（第一声）声调不同，意思是题目。"}, {"text": "剃", "is_correct": false, "explanation": "剃（tì，第四声）与 tī（第一声）声调不同，意思是用刀去掉毛发。"}, {"text": "滴", "is_correct": false, "explanation": "滴（dī，第一声）与 tī 声母不同（d 与 t），意思是液体一点一点落下。"}, {"text": "期", "is_correct": false, "explanation": "期（qī，第一声）与 tī（第一声）仅声母不同（q 与 t），意思是时期、期限。"}], "explanations": {"踢": "踢（tī，第一声）指抬脚用力碰击，与题目要求一致。", "题": "题（tí，第二声）与 tī（第一声）声调不同，意思是题目。", "剃": "剃（tì，第四声）与 tī（第一声）声调不同，意思是用刀去掉毛发。", "滴": "滴（dī，第一声）与 tī 声母不同（d 与 t），意思是液体一点一点落下。", "期": "期（qī，第一声）与 tī（第一声）仅声母不同（q 与 t），意思是时期、期限。"}, "sentence_index": null, "correct_answer": "踢"}, "level_3": {"options": [{"text": "踢", "is_correct": true, "explanation": "踢指用脚轻轻碰击，与“用脚轻轻”的语境相符。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”用手掌，与句中的“用脚”冲突。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”指双臂环拢，不能用脚进行。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”用眼睛，不能“用脚”进行。"}], "explanations": {"踢": "踢指用脚轻轻碰击，与“用脚轻轻”的语境相符。", "拍": "语义：“拍”用手掌，与句中的“用脚”冲突。", "抱": "语义：“抱”指双臂环拢，不能用脚进行。", "看": "语义：“看”用眼睛，不能“用脚”进行。"}, "sentence_index": 6, "correct_answer": "踢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用嘴踢了一下那个苹果。", "explanation": "这里应该用〈咬〉。踢必须用脚，用嘴对苹果的动作要说咬。"}, {"text": "他用抹布踢了踢桌子。", "explanation": "这里应该用〈擦〉。踢必须用脚，用抹布擦拭桌子要说擦。"}, {"text": "他用扫把踢了踢地。", "explanation": "这里应该用〈扫〉。踢必须用脚，用扫把清理地面要说扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is