INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93959, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "轻易是很容易，不用花什么力气。", "primary_collocate": null, "pronunciation": "qīng yì", "ipa": "tɕʰiŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这道题很简单，他轻易就做对了。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王跑得很快，轻易赢了比赛。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫轻易跳上了很高的墙。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气很大，轻易地搬起了那个箱子。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏太简单，孩子轻易就过关了。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语很好，轻易通过了考试。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手太弱，我们轻易打赢了他们。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门没有锁，小偷轻易地走了进去。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小问题，老师轻易就解决了。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌很好，轻易拿到了第一名。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輕易", "label": "繁体"}], "register": "中性", "sense_fingerprint": "轻易：毫不费力、很容易地做成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：这是本题的目标词，读 qīng yì，表示毫不费力、很容易。"}, {"text": "情意", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是心意、感情。"}, {"text": "轻视", "is_correct": false, "explanation": "yì 与 shì 声母不同，意思是看不起、不重视。"}, {"text": "轻细", "is_correct": false, "explanation": "yì 与 xì 声母不同，意思是又轻又细。"}], "explanations": {"轻易": "正确：这是本题的目标词，读 qīng yì，表示毫不费力、很容易。", "情意": "qíng（第二声）与 qīng（第一声）声调不同，意思是心意、感情。", "轻视": "yì 与 shì 声母不同，意思是看不起、不重视。", "轻细": "yì 与 xì 声母不同，意思是又轻又细。"}, "sentence_index": null, "correct_answer": "轻易"}, "level_3": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：“轻易就做对了”表示毫不费力地做对。"}, {"text": "费力地", "is_correct": false, "explanation": "语义：“费力地”强调用力，与“这道题很简单”矛盾。"}, {"text": "好不容易", "is_correct": false, "explanation": "语义：“好不容易”强调费了很大力气才成功，与“很简单”矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，与“就做对了”表示很快完成的语气不搭配。"}], "explanations": {"轻易": "正确：“轻易就做对了”表示毫不费力地做对。", "费力地": "语义：“费力地”强调用力，与“这道题很简单”矛盾。", "好不容易": "语义：“好不容易”强调费了很大力气才成功，与“很简单”矛盾。", "一直": "搭配：“一直”表示持续，与“就做对了”表示很快完成的语气不搭配。"}, "sentence_index": 0, "correct_answer": "轻易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他轻易地把秘密说了出去，大家都很生气。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}, {"text": "这笔钱是家里的，不能轻易花掉。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}, {"text": "这种事关系重大，别轻易下结论。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：“轻易打赢了他们”表示毫不费力地取胜。"}, {"text": "拼命地", "is_correct": false, "explanation": "语义：“拼命地”强调竭尽全力，与“对手太弱”不协调。"}, {"text": "勉强", "is_correct": false, "explanation": "语义：“勉强”表示费力才做到，与“对手太弱”矛盾。"}, {"text": "险些", "is_correct": false, "explanation": "搭配：“险些”表示差一点没有发生，多跟不如意的结果搭配，不说“险些打赢”。"}], "explanations": {"轻易": "正确：“轻易打赢了他们”表示毫不费力地取胜。", "拼命地": "语义：“拼命地”强调竭尽全力，与“对手太弱”不协调。", "勉强": "语义：“勉强”表示费力才做到，与“对手太弱”矛盾。", "险些": "搭配：“险些”表示差一点没有发生，多跟不如意的结果搭配，不说“险些打赢”。"}, "sentence_index": 6, "correct_answer": "轻易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事很重要，你别轻易开玩笑。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}, {"text": "这份合同很重要，你别轻易签字。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}, {"text": "这事关系到家人，你别轻易表态。", "explanation": "这里是“随便、不慎重”的意思，与本条“毫不费力、很容易”的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很聪明，轻易的解出了这道题。", "corrected_sentence": "他很聪明，轻易地解出了这道题。", "error_description": "“轻易地”是状语，后面用“地”，不用“的”。应说“轻易地解出”，不说“轻易的解出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛不难，我们轻易的打败了对手。", "corrected_sentence": "比赛不难，我们轻易地打败了对手。", "error_description": "“轻易地”是状语，修饰动词“打败”，要用“地”，不用“的”。应说“轻易地打败了对手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
