INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93960, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "随随便便、不经慎重考虑；多用于否定式，如“不轻易”。", "primary_collocate": null, "pronunciation": "qīng yì", "ipa": "tɕʰiŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他很小心，不会轻易相信陌生人。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很重要，你不要轻易做决定。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说过，不能轻易放弃自己的梦想。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个有原则的人，从不轻易答应别人。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很爱面子，不轻易向朋友借钱。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行密码很重要，不要轻易告诉别人。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很少哭，不轻易在孩子面前流泪。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是爷爷送的，我不轻易借给别人。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买贵重的东西以前，不要轻易下单。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格很稳重，不轻易发脾气。", "target_word": "轻易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輕易", "label": "繁体"}], "register": "中性", "sense_fingerprint": "轻易：随随便便、不经慎重考虑（多用于不轻易）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：这是本题的目标词，读 qīng yì，表示随便、不慎重。"}, {"text": "情义", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是交情、情谊。"}, {"text": "轻视", "is_correct": false, "explanation": "yì 与 shì 声母不同，意思是看不起、不重视。"}, {"text": "轻细", "is_correct": false, "explanation": "yì 与 xì 声母不同，意思是又轻又细。"}], "explanations": {"轻易": "正确：这是本题的目标词，读 qīng yì，表示随便、不慎重。", "情义": "qíng（第二声）与 qīng（第一声）声调不同，意思是交情、情谊。", "轻视": "yì 与 shì 声母不同，意思是看不起、不重视。", "轻细": "yì 与 xì 声母不同，意思是又轻又细。"}, "sentence_index": null, "correct_answer": "轻易"}, "level_3": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：“不会轻易相信”表示不随便、不慎重地相信。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同，不能修饰“相信陌生人”这种个人心理活动，句意不通。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示时间或数量正合适，与“很小心”的态度不协调。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“很小心”的态度前后矛盾。"}], "explanations": {"轻易": "正确：“不会轻易相信”表示不随便、不慎重地相信。", "一起": "搭配：“一起”表示共同，不能修饰“相信陌生人”这种个人心理活动，句意不通。", "恰好": "语义：“恰好”表示时间或数量正合适，与“很小心”的态度不协调。", "竟然": "语义：“竟然”表示出乎意料，与“很小心”的态度前后矛盾。"}, "sentence_index": 0, "correct_answer": "轻易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你轻易坐，别客气。", "explanation": "这里应该用〈随便〉。“轻易”不能用来请人自便，请人随便坐要用“随便”。"}, {"text": "今天中午你轻易吃点东西就行。", "explanation": "这里应该用〈随便〉。“轻易”不能表示不挑不拣、怎么都行的意思，随便吃点东西要用“随便”。"}, {"text": "我不挑，轻易什么都行。", "explanation": "这里应该用〈随便〉。“轻易”不能表示“什么都行”，不挑不拣要用“随便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻易", "is_correct": true, "explanation": "正确：“不轻易在孩子面前流泪”表示不随便地、不轻率地流泪。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经发生，不能受否定词“不”修饰。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间刚过去，与“很少哭”描述的习惯不符。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”表示过去的经历，不能直接与否定词“不”搭配。"}], "explanations": {"轻易": "正确：“不轻易在孩子面前流泪”表示不随便地、不轻率地流泪。", "已经": "搭配：“已经”表示已经发生，不能受否定词“不”修饰。", "刚刚": "语义：“刚刚”表示时间刚过去，与“很少哭”描述的习惯不符。", "曾经": "搭配：“曾经”表示过去的经历，不能直接与否定词“不”搭配。"}, "sentence_index": 6, "correct_answer": "轻易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你轻易挑，我请客。", "explanation": "这里应该用〈随便〉。“轻易”不能表示任意挑选、不加拣择的意思，随便挑要用“随便”。"}, {"text": "轻易哪一个都行。", "explanation": "这里应该用〈随便〉。“轻易”不能表示“不论哪一个”的意思，“随便哪一个都行”要用“随便”。"}, {"text": "在家轻易穿穿就行。", "explanation": "这里应该用〈随便〉。“轻易”不能表示在家不拘形式地穿着，在家随便穿要用“随便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人很谨慎，不会轻易答应了别人的请求。", "corrected_sentence": "这个人很谨慎，不会轻易答应别人的请求。", "error_description": "“不会轻易答应”说的是还没发生的事，动词“答应”后面不能加“了”。应说“不会轻易答应别人的请求”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他办事很稳，不会轻易的作决定。", "corrected_sentence": "他办事很稳，不会轻易作决定。", "error_description": "“轻易”是副词，后面不加“的”。应说“不会轻易作决定”，不说“不会轻易的作决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
