INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93962, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在前一步的基础上更进一步。", "primary_collocate": null, "pronunciation": "jìn ér", "ipa": "tɕin˥˩ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "我们先了解问题，进而找出原因。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学会了写字，进而开始写文章。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先提高成绩，进而争取奖学金。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司稳定了市场，进而扩大了生产。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先讲规则，进而让学生练习。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先学好汉语，进而研究中国文化。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济发展了，进而改善了人民的生活。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府先解决住房问题，进而降低物价。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先理解别人，进而学会帮助别人。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先改进了方法，进而提高了工作效率。", "target_word": "进而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "進而", "label": "繁体"}], "register": "书面", "sense_fingerprint": "进而：连词，在前一步的基础上更进一步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc29dc70-dc3b-43f5-8c12-a16457eab3c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进而", "is_correct": true, "explanation": "进而：在前一步“先了解问题”的基础上再往前推进一步。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，这里前后没有转折关系。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事一起进行，与“先……”的先后顺序相矛盾。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样做就会怎样，这里没有这种条件关系。"}], "explanations": {"进而": "进而：在前一步“先了解问题”的基础上再往前推进一步。", "但是": "语义：“但是”表示转折，这里前后没有转折关系。", "同时": "语义：“同时”表示两件事一起进行，与“先……”的先后顺序相矛盾。", "否则": "语义：“否则”表示不这样做就会怎样，这里没有这种条件关系。"}, "sentence_index": 0, "correct_answer": "进而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不但会说汉语，进而会写汉字。", "explanation": "这里应该用〈而且〉。“不但……而且……”是固定格式，“进而”不能和“不但”配对。"}, {"text": "他很努力，进而没成功。", "explanation": "这里应该用〈但是〉。“但是”表示转折，“进而”只表示递进，不能引出相反的结果。"}, {"text": "你要努力，进而会失败。", "explanation": "这里应该用〈否则〉。“否则”引出不这样做的后果，“进而”不能表示这种条件关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进而", "is_correct": true, "explanation": "进而：在“经济发展了”的基础上，进一步改善人民的生活。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，这里前后没有转折关系。"}, {"text": "反之", "is_correct": false, "explanation": "语义：“反之”表示相反的情况，这里没有相反关系。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示如果不这样就会怎样，这里没有这种假设关系。"}], "explanations": {"进而": "进而：在“经济发展了”的基础上，进一步改善人民的生活。", "然而": "语义：“然而”表示转折，这里前后没有转折关系。", "反之": "语义：“反之”表示相反的情况，这里没有相反关系。", "不然": "语义：“不然”表示如果不这样就会怎样，这里没有这种假设关系。"}, "sentence_index": 6, "correct_answer": "进而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边学习，进而打工。", "explanation": "这里应该用〈同时〉。“一边……”表示两件事同时进行，“进而”表示先后相继，不能用于同时发生的动作。"}, {"text": "他是进而去学校，还是去公园？", "explanation": "这里应该用〈还是〉。“进而”表示接续推进，不能用在选择疑问句中表示二选一。"}, {"text": "他不是学习，进而去玩游戏。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示替换，“进而”不能用在否定后表示替代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先看懂了题目，而进而写出了答案。", "corrected_sentence": "他先看懂了题目，进而写出了答案。", "error_description": "连词重复：“进而”本身已是连词，前面不能再加“而”。错误形式是“而进而”，正确形式是“进而”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先认真练习发音，进而进而流利地交谈。", "corrected_sentence": "他先认真练习发音，进而流利地交谈。", "error_description": "连词重复：“进而”已是连词，不能在同一位置连用两次。错误形式是“进而进而”，正确形式是“进而”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
