INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过于是比应该的多太多。", "primary_collocate": null, "pronunciation": "guò yú", "ipa": "kuɔ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "你不要过于紧张。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对孩子过于严格。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个问题过于复杂，我不会做。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈过于担心他的身体。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服颜色过于鲜艳，我不喜欢。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话过于直接，朋友有点不高兴。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她过于在意别人的看法。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别过于着急，慢慢来。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试题目过于简单，大家都得了高分。", "target_word": "过于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里过于安静，我有点害怕。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "過於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过于·guò yú·比应该的程度多太多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过于", "is_correct": true, "explanation": "“过于”表示超过适当限度，与“你不要…紧张”的劝阻语气相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已然发生，与“不要”的劝阻语气不相合，“不要已经紧张”不通。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，与“不要…紧张”这一状态的劝阻不相合。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示程度最高，与“不要…紧张”的劝阻不相合，说“不要最紧张”不通。"}], "explanations": {"过于": "“过于”表示超过适当限度，与“你不要…紧张”的劝阻语气相合。", "已经": "语义：“已经”表示已然发生，与“不要”的劝阻语气不相合，“不要已经紧张”不通。", "正在": "语义：“正在”表示动作进行中，与“不要…紧张”这一状态的劝阻不相合。", "最": "语义：“最”表示程度最高，与“不要…紧张”的劝阻不相合，说“不要最紧张”不通。"}, "sentence_index": 0, "correct_answer": "过于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他过于吃了三碗饭，肚子很疼。", "explanation": "这里应该去掉〈过于〉。〈过于〉修饰形容词或心理动词，不能修饰〈吃〉这样的动作。"}, {"text": "我们今天过于去超市买东西。", "explanation": "这里应该去掉〈过于〉。〈过于〉修饰形容词或心理动词，不能修饰〈去〉这类动作。"}, {"text": "这个班过于四十人，教室坐不下。", "explanation": "这里应该用〈超过〉。〈过于〉修饰程度，不用来表示人数超出某个界限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过于", "is_correct": true, "explanation": "“过于”表示超过适当限度，“过于在意别人的看法”符合句意。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与“不”“没”连用表示彻底否定，单独修饰“在意”说不通。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”引导被动句，需要施事，“她被在意别人的看法”不成立。"}, {"text": "对", "is_correct": false, "explanation": "语法：“对”是介词，后面要接对象名词，“她对在意别人的看法”不成立。"}], "explanations": {"过于": "“过于”表示超过适当限度，“过于在意别人的看法”符合句意。", "根本": "搭配：“根本”多与“不”“没”连用表示彻底否定，单独修饰“在意”说不通。", "被": "语法：“被”引导被动句，需要施事，“她被在意别人的看法”不成立。", "对": "语法：“对”是介词，后面要接对象名词，“她对在意别人的看法”不成立。"}, "sentence_index": 6, "correct_answer": "过于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次郊游我们过于走了很远的路。", "explanation": "这里应该去掉〈过于〉。〈过于〉修饰形容词或心理动词，不能修饰〈走〉这样的动作。"}, {"text": "妈妈过于街去买菜。", "explanation": "这里应该用〈过〉。〈过于〉没有“经过”的意思，“过街”的“过”不带“于”。"}, {"text": "他的成绩过于进步，老师很惊讶。", "explanation": "这里应该用〈很大〉。〈过于〉表示超出限度，不修饰〈进步〉这类表示变化的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的计划很过于复杂，公司不会同意。", "corrected_sentence": "我们的计划过于复杂，公司不会同意。", "error_description": "多余的“很”：“过于”已经表示程度，不能与“很”叠用，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她过于的在意别人的看法，常常睡不好。", "corrected_sentence": "她过于在意别人的看法，常常睡不好。", "error_description": "多余的“的”：“过于”是副词，后面直接接动词或形容词，不能加“的”，应说“过于在意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除脏东西，与远离没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时不走，与距离远近没有对应关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与远离没有反义关系。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。", "打扫": "打扫指清除脏东西，与远离没有反义关系。", "停留": "停留指暂时不走，与距离远近没有对应关系。", "研究": "研究指深入探讨，与远离没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。"}, {"text": "保留", "is_correct": false, "explanation": "保留指留住不失去，与距离远近没有关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造，与远离没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子想问题，与远近无关。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。", "保留": "保留指留住不失去，与距离远近没有关系。", "修建": "修建指建造，与远离没有反义关系。", "思考": "思考指用脑子想问题，与远近无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "远离是离得很远，不靠近。", "primary_collocate": null, "pronunciation": "yuǎn lí", "ipa": "y̯ɛn²¹⁴ li³⁵", "syllable_count": 2, "sentences": [{"text": "我们的学校远离市中心，很安静。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子远离大路，很少有车。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区远离工厂，空气很好。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家远离城市，住在山里。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂远离河流，不会让水变脏。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院应该远离吵闹的马路。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方远离人群，只有风的声音。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小岛远离陆地，船要开一天。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的房子远离海边，没有海风。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小学远离县城，路很难走。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远离了", "label": "体标"}, {"form": "远离过", "label": "体标"}, {"form": "遠離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某处所距离另一处很远，不靠近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与市中心距离很远，与“很安静”的描写一致。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：逃离指躲避危险或困境，学校不会逃跑，整句说不通。"}, {"text": "穿过", "is_correct": false, "explanation": "语义：穿过指从中间经过，与“很安静”的描写相反，学校也不会穿过市中心。"}, {"text": "包围", "is_correct": false, "explanation": "配价：包围要求有施事围住对象，学校不能包围市中心。"}], "explanations": {"远离": "正确：远离表示与市中心距离很远，与“很安静”的描写一致。", "逃离": "语义：逃离指躲避危险或困境，学校不会逃跑，整句说不通。", "穿过": "语义：穿过指从中间经过，与“很安静”的描写相反，学校也不会穿过市中心。", "包围": "配价：包围要求有施事围住对象，学校不能包围市中心。"}, "sentence_index": 0, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直远离我，却天天坐在我旁边。", "explanation": "这里应该用〈靠近〉。远离是离得很远，与“天天坐在我旁边”的意思矛盾。"}, {"text": "他在桌子旁边远离了一下，给别人让路。", "explanation": "这里应该用〈让开〉。远离指距离很远，只挪一步让路不能说远离。"}, {"text": "那只猫总是远离主人，一直蹭在他的腿边。", "explanation": "这里应该用〈靠近〉。远离是离得很远，与“一直蹭在他的腿边”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与人群距离很远，与“只有风的声音”的安静环境一致。"}, {"text": "包围", "is_correct": false, "explanation": "语义：包围是从四周围住，与“只有风的声音”的安静环境矛盾。"}, {"text": "接近", "is_correct": false, "explanation": "语义：接近是靠近，地方接近人群就不会只有风声，前后矛盾。"}, {"text": "闯入", "is_correct": false, "explanation": "配价：闯入需要有人作主语，“这个地方”不能闯入人群。"}], "explanations": {"远离": "正确：远离表示与人群距离很远，与“只有风的声音”的安静环境一致。", "包围": "语义：包围是从四周围住，与“只有风的声音”的安静环境矛盾。", "接近": "语义：接近是靠近，地方接近人群就不会只有风声，前后矛盾。", "闯入": "配价：闯入需要有人作主语，“这个地方”不能闯入人群。"}, "sentence_index": 6, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父母总是远离孩子，每天都陪着他一起吃饭。", "explanation": "这里应该用〈陪伴〉。远离是离得很远，与“每天都陪着他一起吃饭”的意思矛盾。"}, {"text": "他慢慢远离了那只小狗，想跟它玩。", "explanation": "这里应该用〈接近〉。远离是离得很远，与“想跟它玩”的意思矛盾，要靠近小狗应说接近。"}, {"text": "他的家远离学校，走两分钟就到了。", "explanation": "这里应该用〈靠近〉。远离是离得很远，与“走两分钟就到了”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个农场从远离铁路，每天都很安静。", "corrected_sentence": "这个农场远离铁路，每天都很安静。", "error_description": "“远离”是动词，前面不能直接加“从”；“从”只用于引出动作的起点，应说“这个农场远离铁路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座寺庙远离在村子，很清静。", "corrected_sentence": "这座寺庙远离村子，很清静。", "error_description": "“远离”后直接带宾语，中间不能插入“在”，应说“远离村子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与主动离开的义项对立。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复正常，与远近没有关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与远离没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指出门游览，与远离没有反义关系。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与主动离开的义项对立。", "修理": "修理指使损坏的东西恢复正常，与远近没有关系。", "讨论": "讨论指交换意见，与远离没有反义关系。", "旅行": "旅行指出门游览，与远离没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与主动离开的义项对立。"}, {"text": "种植", "is_correct": false, "explanation": "种植指栽种植物，与远离没有反义关系。"}, {"text": "接待", "is_correct": false, "explanation": "接待指招待客人，与远离没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与远近没有反义关系。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与主动离开的义项对立。", "种植": "种植指栽种植物，与远离没有反义关系。", "接待": "接待指招待客人，与远离没有反义关系。", "观察": "观察指仔细看，与远近没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离得很远；离开。", "primary_collocate": null, "pronunciation": "yuǎn lí", "ipa": "y̯ɛn²¹⁴ li³⁵", "syllable_count": 2, "sentences": [{"text": "他远离家乡，一个人去了大城市。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，她远离了父母，到外地工作。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体好，他远离了烟和酒。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想远离吵闹的城市，去山里住。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他远离亲人十年，终于回家了。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那只大狗，小女孩马上远离了它。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要远离坏朋友，别学他们。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想远离烦人的事，安静地休息几天。", "target_word": "远离", "complexity_tier": "T3", "furigana": "tā xiǎng yuǎnlí fánrén de shì ānjìng de xiūxi jǐ tiān", "sentence_source": "generated"}, {"text": "她远离了朋友们，一个人住在海边。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人远离城市生活，回到了老家。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远离了", "label": "体标"}, {"form": "远离过", "label": "体标"}, {"form": "遠離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人主动离开某人、某地或某事物，不再接近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示主动离开家乡，与“一个人去了大城市”一致。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：陪伴要求有生命的对象，家乡不能被陪伴。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是把一种语言转换成另一种，家乡不能被翻译，整句说不通。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：照顾通常用于人或动物，不说照顾家乡。"}], "explanations": {"远离": "正确：远离表示主动离开家乡，与“一个人去了大城市”一致。", "陪伴": "配价：陪伴要求有生命的对象，家乡不能被陪伴。", "翻译": "语义：翻译是把一种语言转换成另一种，家乡不能被翻译，整句说不通。", "照顾": "搭配：照顾通常用于人或动物，不说照顾家乡。"}, "sentence_index": 0, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈慢慢远离了哭闹的孩子，想抱抱他。", "explanation": "这里应该用〈接近〉。远离是离得很远，与“想抱抱他”的意思矛盾，要靠近孩子应说接近。"}, {"text": "他远离家门，整天待在屋里不出去。", "explanation": "这里应该用〈留在〉。远离指离得很远，与“整天待在屋里不出去”的意思矛盾。"}, {"text": "孩子紧紧远离着妈妈，不肯松手。", "explanation": "这里应该用〈贴近〉。远离是离得很远，与“紧紧”“不肯松手”的意思矛盾，要紧挨着妈妈应说贴近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与坏朋友保持距离，与“别学他们”的劝告一致。"}, {"text": "结交", "is_correct": false, "explanation": "语义：结交是交朋友，与“别学他们”的劝告矛盾。"}, {"text": "包庇", "is_correct": false, "explanation": "语义：包庇是替人隐瞒过错，与“别学他们”的劝告矛盾。"}, {"text": "报答", "is_correct": false, "explanation": "搭配：报答通常接恩情，不说报答坏朋友。"}], "explanations": {"远离": "正确：远离表示与坏朋友保持距离，与“别学他们”的劝告一致。", "结交": "语义：结交是交朋友，与“别学他们”的劝告矛盾。", "包庇": "语义：包庇是替人隐瞒过错，与“别学他们”的劝告矛盾。", "报答": "搭配：报答通常接恩情，不说报答坏朋友。"}, "sentence_index": 6, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直远离着妻子，却每天都和她一起吃晚饭。", "explanation": "这里应该用〈陪伴〉。远离是离得很远，与“每天都和她一起吃晚饭”的意思矛盾。"}, {"text": "他远离了那场车祸，只受了点轻伤。", "explanation": "这里应该用〈躲过〉。远离指距离远，不能说远离了一场车祸。"}, {"text": "他远离着生病的母亲，寸步不离。", "explanation": "这里应该用〈陪伴〉。远离指离得很远，与“寸步不离”的意思矛盾，照顾生病的母亲应说陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从远离老家，独自去北方打工。", "corrected_sentence": "他远离老家，独自去北方打工。", "error_description": "“远离”是动词，前面不能直接加“从”，应说“他远离老家”，不用“从”引出出发地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我决定远离了坏习惯，每天早起运动。", "corrected_sentence": "我决定远离坏习惯，每天早起运动。", "error_description": "“决定”后面说的是将来的打算，应说“决定远离坏习惯”，不用“远离了”表示已经完成的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "还本是把借来的钱还回去。", "primary_collocate": null, "pronunciation": "huán běn", "ipa": "xwan˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他答应月底前还本，利息另算。", "target_word": "还本", "complexity_tier": "T3", "furigana": "tā dā yìng yuè dǐ qián huán běn, lì xī lìng suàn.", "sentence_source": "generated"}, {"text": "这笔借款我会分期还本，利息另付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zhè bǐ jiè kuǎn wǒ huì fēn qī huán běn, lì xī lìng fù.", "sentence_source": "generated"}, {"text": "他不要利息，只要你还本就行。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借款人应当按期还本，不得拖欠。", "target_word": "还本", "complexity_tier": "T3", "furigana": "jiè kuǎn rén yīng dāng àn qī huán běn, bù dé tuō qiàn.", "sentence_source": "generated"}, {"text": "朋友借给我两千元，约定一年后还本，利息免了。", "target_word": "还本", "complexity_tier": "T3", "furigana": "péng yǒu jiè gěi wǒ liǎng qiān yuán, yuē dìng yì nián hòu huán běn, lì xī miǎn le.", "sentence_source": "generated"}, {"text": "他先还本，再慢慢给我利息。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔借款到期还本，利息每月支付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zhè bǐ jiè kuǎn dào qī huán běn, lì xī měi yuè zhī fù.", "sentence_source": "generated"}, {"text": "借钱时他说好了，三个月后还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈借我的钱，我已分批还本，利息照付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "mā ma jiè wǒ de qián, wǒ yǐ fēn pī huán běn, lì xī zhào fù.", "sentence_source": "generated"}, {"text": "资金周转不开，他只能先付利息，等有钱再还本。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zī jīn zhōu zhuǎn bù kāi, tā zhǐ néng xiān fù lì xī, děng yǒu qián zài huán běn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "還本", "label": "繁体"}, {"form": "还本付息", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把借来的钱还给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还借来的本金，与「利息另算」搭配，句意通顺。"}, {"text": "退房", "is_correct": false, "explanation": "语义：「退房」是退掉住宿，与借款和利息无关，句子不通。"}, {"text": "还书", "is_correct": false, "explanation": "搭配：「还书」的对象是书，没有利息这一概念，「利息另算」不能与之搭配。"}, {"text": "放假", "is_correct": false, "explanation": "语义：「放假」与借款、利息毫无关系，句子不通。"}], "explanations": {"还本": "「还本」指偿还借来的本金，与「利息另算」搭配，句意通顺。", "退房": "语义：「退房」是退掉住宿，与借款和利息无关，句子不通。", "还书": "搭配：「还书」的对象是书，没有利息这一概念，「利息另算」不能与之搭配。", "放假": "语义：「放假」与借款、利息毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借来的图书应当按期还本，不得拖欠。", "explanation": "这里应该用〈归还〉。还本只指偿还所借款项的本金，借来的书要说归还。"}, {"text": "放贷人应当按期还本给借款人，不得拖欠。", "explanation": "这里应该用〈收回〉。还本是借款人偿还本金，放贷人只能说收回本金，不能把本金还给借款人。"}, {"text": "借款人应当按期把利息还本，不得拖欠。", "explanation": "这里应该用〈付息〉。还本的宾语是本金，利息应说付息或还利息，不能说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还本金，与「到期」和「利息每月支付」的还款安排相符。"}, {"text": "退货", "is_correct": false, "explanation": "语义：「退货」是把商品退回，与借款无关，句子不通。"}, {"text": "出租", "is_correct": false, "explanation": "语义：借款不能出租，句子不通。"}, {"text": "登机", "is_correct": false, "explanation": "搭配：「登机」只用于乘坐飞机的场合，与「借款到期」不搭配。"}], "explanations": {"还本": "「还本」指偿还本金，与「到期」和「利息每月支付」的还款安排相符。", "退货": "语义：「退货」是把商品退回，与借款无关，句子不通。", "出租": "语义：借款不能出租，句子不通。", "登机": "搭配：「登机」只用于乘坐飞机的场合，与「借款到期」不搭配。"}, "sentence_index": 6, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欠的房租终于还本了。", "explanation": "这里应该用〈还清〉。还本只指偿还借款的本金，房租这类欠款不说还本。"}, {"text": "他想把老板还本，好让老板高兴。", "explanation": "这里应该用〈还给〉。还本的宾语只能是本金，不能是人。"}, {"text": "他去银行把自己存的钱还本了。", "explanation": "这里应该用〈取出〉。还本指偿还借来的本金，拿回自己存的钱不说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱我打算明年把还本。", "corrected_sentence": "这笔钱我打算明年还本。", "error_description": "错误：“明年把还本”。“把”字句需要动词后有宾语或补语，“还本”前不能加“把”，应删去“把”，说“这笔钱我打算明年还本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他分三个还本，利息另付。", "corrected_sentence": "他分三次还本，利息另付。", "error_description": "量词错误：「分三个还本」应改为「分三次还本」。表示还款次数的量词要用「次」，不能用「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
