INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "偿还本金。", "primary_collocate": null, "pronunciation": "huán běn", "ipa": "xwan˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这笔贷款前三年只付利息，第四年才开始还本。", "target_word": "还本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月他先付利息，到期再还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司钱不够，银行同意晚一年还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱他分五年还本，每年还一部分。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要先还本，利息可以以后再给。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说今年生意好，打算提前还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了还本的日子，他去银行办手续。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司每年付利息，三年后一次还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边工作一边存钱，想早点还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年他们只付了利息，明年再还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "還本", "label": "繁体"}, {"form": "还本付息", "label": "复合"}], "register": "书面语", "sense_fingerprint": "偿还贷款或借款的本金，常与付息相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还借款的本金，与「前三年只付利息、第四年才开始」的还款安排相符。"}, {"text": "付息", "is_correct": false, "explanation": "语义：前半句已说「只付利息」，「第四年才开始付息」与前三年只付利息的对照矛盾。"}, {"text": "打折", "is_correct": false, "explanation": "搭配：「打折」用于商品价格，不能用于贷款的还款安排。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」与贷款的还款安排无关，句子不通。"}], "explanations": {"还本": "「还本」指偿还借款的本金，与「前三年只付利息、第四年才开始」的还款安排相符。", "付息": "语义：前半句已说「只付利息」，「第四年才开始付息」与前三年只付利息的对照矛盾。", "打折": "搭配：「打折」用于商品价格，不能用于贷款的还款安排。", "结婚": "语义：「结婚」与贷款的还款安排无关，句子不通。"}, "sentence_index": 0, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借来的字典要按时还本，不能拖到期末。", "explanation": "这里应该用〈归还〉。还本只指偿还借款的本金，字典这类物品要说归还。"}, {"text": "他终于把拖欠的房租还本了。", "explanation": "这里应该用〈还清〉。还本只用于偿还借来的钱的本金，房租这类欠款不说还本。"}, {"text": "银行每月向我们还本，我们只需按时付息。", "explanation": "这里应该用〈放贷〉。还本的主体是借款人，银行向借款人放款，不能说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还本金，「到了……的日子」去银行办手续，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳的日子不需要去银行办手续，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨的日子与去银行办手续无关，句子不合逻辑。"}, {"text": "放风筝", "is_correct": false, "explanation": "语义：放风筝与去银行办手续无关，句意不通。"}], "explanations": {"还本": "「还本」指偿还本金，「到了……的日子」去银行办手续，句意通顺。", "游泳": "语义：游泳的日子不需要去银行办手续，句意不通。", "下雨": "语义：下雨的日子与去银行办手续无关，句子不合逻辑。", "放风筝": "语义：放风筝与去银行办手续无关，句意不通。"}, "sentence_index": 6, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先把欠的利息还本，本金以后再说。", "explanation": "这里应该用〈还息〉。还本只指偿还本金，利息不能说还本。"}, {"text": "他想把老板还本，好让老板放心。", "explanation": "这里应该用〈还给〉。还本的宾语只能是本金，不能是人。"}, {"text": "他去银行把自己的存款还本了。", "explanation": "这里应该用〈取出〉。还本指偿还借来的本金，取出自己的存款不说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每月按时还本了，利息另付。", "corrected_sentence": "他每月按时还本，利息另付。", "error_description": "体标错误：这里说的是每月按时的习惯性还款，不应在“还本”后加“了”，应说“他每月按时还本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "借款到期后，他一次性还本着，利息另付。", "corrected_sentence": "借款到期后，他一次性还本，利息另付。", "error_description": "体标错误：「一次性还本」是一次完成的动作，不能加表示持续的「着」，应说「他一次性还本」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
