INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93969, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻碍是挡在中间，让别人没法往前走。", "primary_collocate": null, "pronunciation": "zǔ ài", "ipa": "tsu˨˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "路上的大树阻碍了汽车前进。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪阻碍了我们回家的路。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面停着的车阻碍了后面的车。", "target_word": "阻碍", "complexity_tier": "T3", "furigana": "qián miàn tíng zhe de chē zǔ ài le hòu miàn de chē", "sentence_source": "generated"}, {"text": "请不要把行李放在门口阻碍大家。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那堵墙阻碍了我们往前走。", "target_word": "阻碍", "complexity_tier": "T3", "furigana": "nà dǔ qiáng zǔ ài le wǒ men wǎng qián zǒu", "sentence_source": "generated"}, {"text": "河水太大，阻碍了船往前走。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路中间，阻碍别人通过。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "倒下的树阻碍着消防车通过。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的石头阻碍了我们往上走。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你让开，不要阻碍我们走路。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻碍了", "label": "体标"}, {"form": "阻碍着", "label": "体标"}, {"form": "阻碍过", "label": "体标"}], "register": "中性", "sense_fingerprint": "挡在路上，使人或车无法前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻碍", "is_correct": true, "explanation": "阻碍：挡在中间，让别人没法往前走，与“路上的大树”和“汽车前进”相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：大树不会帮助汽车前进，这一搭配的语义不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：大树不会欢迎汽车，“欢迎汽车前进”与场景矛盾。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者和受事，句中“送了汽车前进”成分不完整。"}], "explanations": {"阻碍": "阻碍：挡在中间，让别人没法往前走，与“路上的大树”和“汽车前进”相符。", "帮助": "语义：大树不会帮助汽车前进，这一搭配的语义不通。", "欢迎": "语义：大树不会欢迎汽车，“欢迎汽车前进”与场景矛盾。", "送": "配价：“送”需要接受者和受事，句中“送了汽车前进”成分不完整。"}, "sentence_index": 0, "correct_answer": "阻碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他阻碍了我们，让我们很快到达了目的地。", "explanation": "这里应该用〈帮助〉。阻碍是挡住、使人无法前进，与“很快到达”矛盾，不能表示帮助。"}, {"text": "这次培训阻碍了大家的进步，大家都进步很快。", "explanation": "这里应该用〈促进〉。阻碍是使事情受阻，与“进步很快”矛盾，表示推动时应用〈促进〉。"}, {"text": "保安阻碍了想进门的人，让大家都顺利进入了。", "explanation": "这里应该用〈放行〉。阻碍是挡住、使人无法通过，与“顺利进入”矛盾，不能表示放行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻碍", "is_correct": true, "explanation": "阻碍：挡在中间，让别人没法往前走，与“他站在路中间”的场景相符。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“别人”作宾语，句子不通。"}, {"text": "驾临", "is_correct": false, "explanation": "配价：“驾临”指尊贵的客人到来，不能带“别人通过”这样的成分，句子不通。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：“欢送”多指送人离开，不与“别人通过”搭配。"}], "explanations": {"阻碍": "阻碍：挡在中间，让别人没法往前走，与“他站在路中间”的场景相符。", "消失": "配价：“消失”是不及物动词，不能带“别人”作宾语，句子不通。", "驾临": "配价：“驾临”指尊贵的客人到来，不能带“别人通过”这样的成分，句子不通。", "欢送": "搭配：“欢送”多指送人离开，不与“别人通过”搭配。"}, "sentence_index": 6, "correct_answer": "阻碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他顺利地阻碍了这次活动的筹备，大家都很感谢他。", "explanation": "这里应该用〈推动〉。阻碍是使事情受阻，与“顺利”和“感谢”矛盾，不能表示推动筹备。"}, {"text": "医生阻碍了他的感冒，他很快就好了。", "explanation": "这里应该用〈治疗〉。阻碍是使事情受阻，不用于治病；“很快就好了”也与阻碍矛盾。"}, {"text": "老师用图画阻碍了我们的理解，我们都学会了。", "explanation": "这里应该用〈讲明白〉。阻碍是使事情受阻，与“我们都学会了”矛盾，不能表示把道理讲明白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一块大石头阻碍了了车队前进。", "corrected_sentence": "一块大石头阻碍了车队前进。", "error_description": "“了”只用一次，紧跟动词“阻碍”即可，应说“阻碍了车队前进”，不能重复成“阻碍了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一辆卡车停在路中间，阻碍了过救护车通过。", "corrected_sentence": "一辆卡车停在路中间，阻碍着救护车通过。", "error_description": "“了”与“过”不能同时用在同一个动词后，应只用其一；这里表示持续的状态，应说“阻碍着救护车通过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": true, "explanation": "促进与“阻碍”意思相反，指推动事情顺利进行，与“没有人能阻碍孩子学习”构成反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察与“阻碍”没有反义关系，二者意思不相关。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾与“阻碍”没有反义关系，指整理物品。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行与“阻碍”没有反义关系，指出外游览。"}], "correct_answer": "促进", "explanations": {"促进": "促进与“阻碍”意思相反，指推动事情顺利进行，与“没有人能阻碍孩子学习”构成反义关系。", "观察": "观察与“阻碍”没有反义关系，二者意思不相关。", "收拾": "收拾与“阻碍”没有反义关系，指整理物品。", "旅行": "旅行与“阻碍”没有反义关系，指出外游览。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": true, "explanation": "促进与“阻碍”意思相反，指推动事情顺利进行，与“交通不方便阻碍了小镇的发展”构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步与“阻碍”没有反义关系，指随意走动。"}, {"text": "聊天", "is_correct": false, "explanation": "聊天与“阻碍”没有反义关系，指交谈。"}, {"text": "休息", "is_correct": false, "explanation": "休息与“阻碍”没有反义关系，指停下来放松。"}], "correct_answer": "促进", "explanations": {"促进": "促进与“阻碍”意思相反，指推动事情顺利进行，与“交通不方便阻碍了小镇的发展”构成反义关系。", "散步": "散步与“阻碍”没有反义关系，指随意走动。", "聊天": "聊天与“阻碍”没有反义关系，指交谈。", "休息": "休息与“阻碍”没有反义关系，指停下来放松。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使不能顺利通过或发展。", "primary_collocate": null, "pronunciation": "zǔ ài", "ipa": "tsu˨˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "语言问题阻碍了他的工作。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少钱会阻碍公司发展。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气阻碍着比赛的进行。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能阻碍孩子学习。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该阻碍孩子的梦想。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨阻碍了工程的进度。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体不好阻碍了他的学习。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定阻碍着城市发展。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的困难阻碍过他。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通不方便阻碍了小镇的发展。", "target_word": "阻碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻碍了", "label": "体标"}, {"form": "阻碍着", "label": "体标"}, {"form": "阻碍过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使事情不能顺利进行或发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻碍", "is_correct": true, "explanation": "阻碍：使事情不能顺利进行，与“语言问题”和“他的工作”相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：语言问题不能帮助工作，这一搭配语义不通。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：“养成”多用于习惯，不说“养成工作”。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”的对象是景点，不能用来描述工作，语义不通。"}], "explanations": {"阻碍": "阻碍：使事情不能顺利进行，与“语言问题”和“他的工作”相符。", "帮助": "语义：语言问题不能帮助工作，这一搭配语义不通。", "养成": "搭配：“养成”多用于习惯，不说“养成工作”。", "游览": "语义：“游览”的对象是景点，不能用来描述工作，语义不通。"}, "sentence_index": 0, "correct_answer": "阻碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察阻碍了一场斗殴。", "explanation": "这里应该用〈阻止〉。阻碍针对的是事情的进展，不用于阻止某件事情发生。"}, {"text": "医生阻碍了病人的生命。", "explanation": "这里应该用〈挽救〉。阻碍是使事情受阻，不能用于生命。"}, {"text": "他这么努力，阻碍了自己的梦想，真是太好了。", "explanation": "这里应该用〈实现〉。阻碍是使事情受阻，与“真是太好了”矛盾，应说“实现了自己的梦想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻碍", "is_correct": true, "explanation": "阻碍：使事情不能顺利进行，与“身体不好”和“他的学习”相符。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”的对象须是可以给予的东西，“学习”不能赠送，句子不通。"}, {"text": "驾临", "is_correct": false, "explanation": "语义：“驾临”指尊贵的客人到来，“身体不好”不能驾临“学习”，句子不通。"}, {"text": "莅临", "is_correct": false, "explanation": "语义：“莅临”指贵宾到某地，主语须是人，“身体不好”不能莅临。"}], "explanations": {"阻碍": "阻碍：使事情不能顺利进行，与“身体不好”和“他的学习”相符。", "赠送": "语义：“赠送”的对象须是可以给予的东西，“学习”不能赠送，句子不通。", "驾临": "语义：“驾临”指尊贵的客人到来，“身体不好”不能驾临“学习”，句子不通。", "莅临": "语义：“莅临”指贵宾到某地，主语须是人，“身体不好”不能莅临。"}, "sentence_index": 6, "correct_answer": "阻碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天都在阻碍环境。", "explanation": "这里应该用〈保护〉。阻碍是使事情受阻，不用于保护环境。"}, {"text": "妈妈每天都在阻碍生病的孩子。", "explanation": "这里应该用〈照顾〉。阻碍是使人或事受阻，不能用来表示照顾。"}, {"text": "父母每天阻碍孩子，让孩子很快乐。", "explanation": "这里应该用〈陪伴〉。阻碍是使人或事受阻，与“孩子很快乐”矛盾，不能用来表示陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资金不足阻碍了了这个项目的进展。", "corrected_sentence": "资金不足阻碍了这个项目的进展。", "error_description": "“了”只用一次，紧跟动词“阻碍”即可，应说“阻碍了这个项目的进展”，不能重复成“阻碍了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些规定阻碍了过城市的发展。", "corrected_sentence": "这些规定阻碍过城市的发展。", "error_description": "“过”表示经历，应紧跟动词，说“阻碍过”，不能放在“了”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
