INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集会是很多人聚在一个地方，一起做一件事。", "primary_collocate": null, "pronunciation": "jí huì", "ipa": "tɕi˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "周末很多人在广场上集会。", "target_word": "集会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在操场集会，听校长讲话。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们到公园集会了。", "target_word": "集会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民每年春天都在河边集会。", "target_word": "集会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多市民在广场上集会，支持保护环境。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在城市中心集会，一起唱歌跳舞。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，人们还是来到广场集会。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全校老师在大礼堂集会，讨论新学期的安排。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，村里人都到庙前集会。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年们集会过几次，每次都有很多人。", "target_word": "集会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集会了", "label": "体标"}, {"form": "集会过", "label": "体标"}, {"form": "集会地点", "label": "复合"}], "register": "书面", "sense_fingerprint": "很多人聚到同一个地点，共同做一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集会", "is_correct": true, "explanation": "集会：许多人聚在一起做同一件事，是正确答案。"}, {"text": "机会", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，“机会”意思是时机，与集会的声调不同。"}, {"text": "寄回", "is_correct": false, "explanation": "两个音节的声调都与集会不同（jì、huí），意思是邮寄返还。"}, {"text": "急坏", "is_correct": false, "explanation": "第二音节 huài 的韵母与 huì 不同，声调相同，意思是因着急而难受。"}], "explanations": {"集会": "集会：许多人聚在一起做同一件事，是正确答案。", "机会": "jī（第一声）与 jí（第二声）声调不同，“机会”意思是时机，与集会的声调不同。", "寄回": "两个音节的声调都与集会不同（jì、huí），意思是邮寄返还。", "急坏": "第二音节 huài 的韵母与 huì 不同，声调相同，意思是因着急而难受。"}, "sentence_index": null, "correct_answer": "集会"}, "level_3": {"options": [{"text": "集会", "is_correct": true, "explanation": "集会：许多人为同一件事聚在一起，符合“很多人在广场上”的句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：广场上不能洗澡，与“很多人在广场上”的场合不合。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于展览、活动的开始，不说人群在广场上开幕。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体不适，不是许多人在广场上一起做的事。"}], "explanations": {"集会": "集会：许多人为同一件事聚在一起，符合“很多人在广场上”的句意。", "洗澡": "语义：广场上不能洗澡，与“很多人在广场上”的场合不合。", "开幕": "搭配：“开幕”用于展览、活动的开始，不说人群在广场上开幕。", "发烧": "语义：发烧是身体不适，不是许多人在广场上一起做的事。"}, "sentence_index": 0, "correct_answer": "集会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和几个老同学周末在家里集会，一起吃饭聊天。", "explanation": "这里应该用〈聚会〉。集会指为某件事召集起来的较多人群，几个老同学在家相聚吃饭要用聚会。"}, {"text": "我和女朋友每周六都在咖啡馆集会，聊聊最近的生活。", "explanation": "这里应该用〈约会〉。集会要许多人聚在一起，两个人单独相见要用约会。"}, {"text": "校长在办公室里和一位家长集会，谈孩子的学习情况。", "explanation": "这里应该用〈会面〉。集会针对多人聚集，与一位家长正式见面要用会面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集会", "is_correct": true, "explanation": "集会：许多人聚在一起做事，与“还是来到广场”的句意相合。"}, {"text": "晒太阳", "is_correct": false, "explanation": "语义：下雨时不能晒太阳，与“下雨了”的情境矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：广场上不能游泳，也与下雨的情境不合。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”多用于车船，不用于人来到广场。"}], "explanations": {"集会": "集会：许多人聚在一起做事，与“还是来到广场”的句意相合。", "晒太阳": "语义：下雨时不能晒太阳，与“下雨了”的情境矛盾。", "游泳": "语义：广场上不能游泳，也与下雨的情境不合。", "停靠": "搭配：“停靠”多用于车船，不用于人来到广场。"}, "sentence_index": 6, "correct_answer": "集会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一家人在过年时集会，很开心。", "explanation": "这里应该用〈团聚〉。集会指为某事聚集起来的人群，一家人过年团圆要用团聚。"}, {"text": "我和王老师明天下午在办公室集会，商量学生的事情。", "explanation": "这里应该用〈见面〉。集会针对多人聚集，两人见面商量事情要用见面。"}, {"text": "两国领导人在首都集会，讨论贸易问题。", "explanation": "这里应该用〈会谈〉。集会指许多人聚在一起，两国领导人正式商谈贸易要用会谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民们到田边集会了了，商量浇水的事。", "corrected_sentence": "农民们到田边集会了，商量浇水的事。", "error_description": "错误：“集会了”后面多写了一个“了”，只需一个“了”，应为“集会了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师们到办公室集会了了，讨论期末考试的安排。", "corrected_sentence": "老师们到办公室集会了，讨论期末考试的安排。", "error_description": "错误：“集会了”后面多写了一个“了”，只需一个“了”，应为“集会了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
