INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的青年时期；年轻的时光。", "primary_collocate": null, "pronunciation": "qīng chūn", "ipa": "tɕʰiŋ˥ tʂʰwən˥", "syllable_count": 2, "sentences": [{"text": "我的青春在北京度过。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把青春留在了山里。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是我们共同的青春。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常讲他的青春故事。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春很短，要好好用。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年青春，她都给了孩子们。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春过去了，我们都老了。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里是妈妈的青春。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外度过了青春。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回头看，青春像一场梦。", "target_word": "青春", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段青春", "label": "量词"}], "register": "中性", "sense_fingerprint": "青春：人的青年时期，年轻的那段时光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "青春", "is_correct": true, "explanation": "正确。“我的青春在北京度过”中，青春指年轻的时光。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体的数值，不能“在北京度过”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是钱，不能“在北京度过”，与句意不符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是机构，不能“在北京度过”。"}], "explanations": {"青春": "正确。“我的青春在北京度过”中，青春指年轻的时光。", "身高": "体貌：身高是身体的数值，不能“在北京度过”。", "工资": "语义：工资是钱，不能“在北京度过”，与句意不符。", "银行": "语义：银行是机构，不能“在北京度过”。"}, "sentence_index": 0, "correct_answer": "青春"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的青春在厨房里做饭。", "explanation": "这里把“青春”当成了〈厨师〉来用。青春是人生的时期，不能在厨房做饭。"}, {"text": "现在青春是下午三点。", "explanation": "这里把“青春”当成了〈时刻〉来用。青春是一段时期，不是某个时刻。"}, {"text": "他的青春很胖。", "explanation": "这里把“青春”当成了〈人体形态〉来用。青春是人生的时期，没有胖瘦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青春", "is_correct": true, "explanation": "正确。“青春过去了，我们都老了”中，青春指年轻的时光。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会“过去”，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的分量，不会“过去”。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是账目，不能说“过去了”。"}], "explanations": {"青春": "正确。“青春过去了，我们都老了”中，青春指年轻的时光。", "作业": "语义：作业不会“过去”，与句意不符。", "体重": "体貌：体重是身体的分量，不会“过去”。", "账单": "语义：账单是账目，不能说“过去了”。"}, "sentence_index": 6, "correct_answer": "青春"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把青春装进了口袋。", "explanation": "这里把“青春”当成了〈物品〉来用。青春是一段时期，不能装进口袋。"}, {"text": "这段青春很硬。", "explanation": "这里把“青春”当成了〈石块〉一类有软硬的东西来用。青春是人生的时期，没有软硬。"}, {"text": "这段青春是一台电脑。", "explanation": "这里把“青春”当成了〈电脑〉这类物品来用。青春是一段时期，不是机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个青春在上海度过。", "corrected_sentence": "这段青春在上海度过。", "error_description": "量词错误。青春指一段时期，应该用“段”：这段青春。“这个”不用于时期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个青春很美好。", "corrected_sentence": "那段青春很美好。", "error_description": "量词错误。青春指一段时期，应该用“段”：那段青春。“那个”不用于时期。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
