INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "面向是脸朝着一个方向。", "primary_collocate": null, "pronunciation": "miàn xiàng", "ipa": "mi̯ɛn⁵¹ ɕi̯ɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "请大家面向老师站好。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他面向窗户坐着，看外面的雨。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们面向国旗，唱起了国歌。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人面向大海，一动不动地站着。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练瑜伽时，要面向东边站直。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转过身来，面向我笑了笑。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做操时，同学们面向前面站好。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他面向墙壁，不想看任何人。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家面向讲台，安静地听校长说话。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你面向镜头，笑一笑。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面向着", "label": "体标"}, {"form": "面向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人的脸朝向某个方向或某个对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。面向指脸或身体朝着某个方向或对象。"}, {"text": "现象", "is_correct": false, "explanation": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。"}, {"text": "变向", "is_correct": false, "explanation": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是改变方向。"}, {"text": "面酱", "is_correct": false, "explanation": "第二音节声母 j 与 x 不同（jiàng 与 xiàng），意思是用面粉等做成的调味酱。"}], "explanations": {"面向": "正确答案。面向指脸或身体朝着某个方向或对象。", "现象": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。", "变向": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是改变方向。", "面酱": "第二音节声母 j 与 x 不同（jiàng 与 xiàng），意思是用面粉等做成的调味酱。"}, "sentence_index": null, "correct_answer": "面向"}, "level_3": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。句子要的是脸朝着老师的动作，只有“面向”能填入。"}, {"text": "投奔", "is_correct": false, "explanation": "语义：“投奔”指去依附某人，与让大家站好的意思不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是责备，不能用来表示站的方向。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”是不及物动词，不能带“老师”作宾语。"}], "explanations": {"面向": "正确答案。句子要的是脸朝着老师的动作，只有“面向”能填入。", "投奔": "语义：“投奔”指去依附某人，与让大家站好的意思不合。", "批评": "语义：“批评”是责备，不能用来表示站的方向。", "洗澡": "配价：“洗澡”是不及物动词，不能带“老师”作宾语。"}, "sentence_index": 0, "correct_answer": "面向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河面向大海。", "explanation": "这里应该用〈流向〉。河水是流动的，要说流向大海，不说面向。"}, {"text": "他面向我借了五块钱。", "explanation": "这里应该用〈找〉。“面向”只表示脸朝着某个方向，不能用来说向别人借钱；借钱要说“找我借”。"}, {"text": "他面向了三份礼物。", "explanation": "这里应该用〈拿到〉。“面向”只表示脸朝着某个方向，不能表示得到礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93975, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。面向指脸或身体朝着某个方向或对象。"}, {"text": "现象", "is_correct": false, "explanation": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。"}, {"text": "变相", "is_correct": false, "explanation": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是换个形式。"}, {"text": "面上", "is_correct": false, "explanation": "第二音节声母 sh 与 x 不同（shàng 与 xiàng），意思是表面上、脸上。"}], "explanations": {"面向": "正确答案。面向指脸或身体朝着某个方向或对象。", "现象": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。", "变相": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是换个形式。", "面上": "第二音节声母 sh 与 x 不同（shàng 与 xiàng），意思是表面上、脸上。"}, "sentence_index": null, "correct_answer": "面向"}, "level_3": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。句子要的是同学们脸朝前面站好，只有“面向”能填入。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”表示逃开，与站好的动作相冲突。"}, {"text": "收拾", "is_correct": false, "explanation": "配价：“收拾”要带物体作宾语，不能直接接“前面”这样的方位词。"}, {"text": "报名", "is_correct": false, "explanation": "配价：“报名”指参加活动登记，不能接方位词作宾语。"}], "explanations": {"面向": "正确答案。句子要的是同学们脸朝前面站好，只有“面向”能填入。", "逃离": "语义：“逃离”表示逃开，与站好的动作相冲突。", "收拾": "配价：“收拾”要带物体作宾语，不能直接接“前面”这样的方位词。", "报名": "配价：“报名”指参加活动登记，不能接方位词作宾语。"}, "sentence_index": 6, "correct_answer": "面向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司现在面向很大的压力。", "explanation": "这里应该用〈面临〉。“面向”指脸朝着某个方向，遇到困难、压力要说“面临”。"}, {"text": "他面向了一个好工作。", "explanation": "这里应该用〈找到〉。“面向”只表示脸朝着某个方向，不能表示得到工作。"}, {"text": "他面向我借了一本书。", "explanation": "这里应该用〈向〉。借东西要说“向我借”，“面向”表示脸朝着，不能引出借的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v