INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把面向老师站好，等待通知。", "corrected_sentence": "他面向老师站好，等待通知。", "error_description": "多余的“把”：“面向”是不能用于处置式的动词，前面不能加“把”，应说“他面向老师站好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
