INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93977, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高速公路是车子可以开得很快的宽宽的大路。", "primary_collocate": null, "pronunciation": "gāo sù gōng lù", "ipa": "kaʊ˥ su˥˩ kʊŋ˥ lu˥˩", "syllable_count": 4, "sentences": [{"text": "高速公路上的车开得很快。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们从北京开车上高速公路去上海。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高速公路又宽又长。", "target_word": "高速公路", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸开车带我们走高速公路回家。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高速公路上不能停车，也不能走路。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去机场要走高速公路，只要半小时。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条新的高速公路让两个城市近了很多。", "target_word": "高速公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，高速公路上要开慢一点。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高速公路的两边都是绿色的树。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在高速公路上开了三个小时的车。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "车子开得很快的宽大道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高速公路", "is_correct": true, "explanation": "「高速公路」是车辆可以快速行驶的道路，与「车开得很快」相符。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场上的车不会开得很快，句意矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：车不能在天空上行驶，句子不通。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「上」不与「教室」组合，也不说车在教室里开得快。"}], "explanations": {"高速公路": "「高速公路」是车辆可以快速行驶的道路，与「车开得很快」相符。", "停车场": "语义：停车场上的车不会开得很快，句意矛盾。", "天空": "语义：车不能在天空上行驶，句子不通。", "教室": "搭配：「上」不与「教室」组合，也不说车在教室里开得快。"}, "sentence_index": 0, "correct_answer": "高速公路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着高速公路散步回家。", "explanation": "这里应该用〈小路〉。高速公路只供汽车行驶，不能用来散步。"}, {"text": "我们在高速公路上骑自行车回家。", "explanation": "这里应该用〈马路〉。高速公路专供汽车高速行驶，骑自行车要在马路上。"}, {"text": "妈妈每天在高速公路上种菜，很辛苦。", "explanation": "这里应该用〈菜地〉。高速公路专供汽车高速行驶，种菜要去菜地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高速公路", "is_correct": true, "explanation": "「高速公路」是交通设施，能让两个城市的距离变近，与句意相符。"}, {"text": "围巾", "is_correct": false, "explanation": "搭配：「让两个城市近了」要搭配交通设施，「围巾」不能与之搭配。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：一条鱼不会让两个城市近很多，句意不通。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链不能让两个城市的距离变近，句子不合逻辑。"}], "explanations": {"高速公路": "「高速公路」是交通设施，能让两个城市的距离变近，与句意相符。", "围巾": "搭配：「让两个城市近了」要搭配交通设施，「围巾」不能与之搭配。", "鱼": "语义：一条鱼不会让两个城市近很多，句意不通。", "项链": "语义：项链不能让两个城市的距离变近，句子不合逻辑。"}, "sentence_index": 6, "correct_answer": "高速公路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在高速公路上坐了三个小时的火车。", "explanation": "这里应该用〈铁路〉。火车在铁路上行驶，高速公路只供汽车行驶。"}, {"text": "我们住在高速公路里，每天很安静。", "explanation": "这里应该用〈小区〉。高速公路是道路，不是居住的地方。"}, {"text": "他是我的高速公路。", "explanation": "这里应该用〈朋友〉。高速公路是道路，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
