INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用三颗星表示的等级或评分，如酒店、餐厅的星级。", "primary_collocate": null, "pronunciation": "sān xīng", "ipa": "san˥˥ ɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这家酒店是三星的，住一晚不太贵。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆得了三星，很多客人专门来吃饭。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的是三星酒店，房间干净，早饭也不错。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家宾馆只有三星，别对它期望太高。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个餐厅评了三星，所以今天要早点订位子。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时我常住三星，又干净又便宜。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给这部电影打了三星，说不好也不坏。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上说那家店是三星，可是我觉得像四星。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行我们订的是三星，不是五星。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三星的房间不大，但是住着很舒服。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三星级", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用三颗星表示的等级，如酒店、餐厅的三星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三星", "is_correct": true, "explanation": "“三星”是酒店等级，“这家酒店是三星的，住一晚不太贵”符合句意。"}, {"text": "五星", "is_correct": false, "explanation": "语义：“五星”指高档酒店，与“住一晚不太贵”矛盾。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”指天上的星体，不表示酒店的等级。"}, {"text": "金牌", "is_correct": false, "explanation": "搭配：酒店的等级用星级表示，不说“金牌的酒店”。"}], "explanations": {"三星": "“三星”是酒店等级，“这家酒店是三星的，住一晚不太贵”符合句意。", "五星": "语义：“五星”指高档酒店，与“住一晚不太贵”矛盾。", "星星": "语义：“星星”指天上的星体，不表示酒店的等级。", "金牌": "搭配：酒店的等级用星级表示，不说“金牌的酒店”。"}, "sentence_index": 0, "correct_answer": "三星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是三星的，大家都很喜欢他。", "explanation": "这里应该用〈优秀〉或〈好〉。〈三星〉是给酒店、餐厅等评定的等级，不用来评价人。"}, {"text": "这盘菜很三星，我们都吃光了。", "explanation": "这里应该用〈很好吃〉。〈三星〉是名词，不能放在“很”后面作形容词。"}, {"text": "这辆车的座位是三星的，我们坐得很舒服。", "explanation": "这里应该去掉〈三星〉。〈三星〉只用来为酒店、餐厅等评定等级，不用来描述座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三星", "is_correct": true, "explanation": "“三星”是评分，“打了三星，说不好也不坏”符合句意。"}, {"text": "五星", "is_correct": false, "explanation": "语义：“五星”表示很好，与“说不好也不坏”矛盾。"}, {"text": "一星", "is_correct": false, "explanation": "语义：“一星”表示很差，与“也不坏”矛盾。"}, {"text": "星级", "is_correct": false, "explanation": "搭配：评分要说“几星”，不说“打了星级”。"}], "explanations": {"三星": "“三星”是评分，“打了三星，说不好也不坏”符合句意。", "五星": "语义：“五星”表示很好，与“说不好也不坏”矛盾。", "一星": "语义：“一星”表示很差，与“也不坏”矛盾。", "星级": "搭配：评分要说“几星”，不说“打了星级”。"}, "sentence_index": 6, "correct_answer": "三星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生考了三星，老师很高兴。", "explanation": "这里应该用〈满分〉或〈一百分〉。〈三星〉是给酒店、餐厅等评定的等级，学生的成绩不用星级表示。"}, {"text": "这张三星的桌子很便宜。", "explanation": "这里应该去掉〈三星〉。〈三星〉是等级，不用来描述桌子之类的家具。"}, {"text": "这次演讲比赛，他拿了三星的好成绩。", "explanation": "这里应该用〈满分〉或〈好〉。〈三星〉是给酒店、餐厅等评定的等级，不用来表示比赛成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家酒店是很三星的，住一晚很便宜。", "corrected_sentence": "这家酒店是三星的，住一晚很便宜。", "error_description": "多余的“很”：“三星”是名词，表示酒店等级，不能受“很”修饰，应说“是三星的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给这家餐厅打了过三星，服务一般。", "corrected_sentence": "他给这家餐厅打过三星，服务一般。", "error_description": "了、过并用：“过”表示曾经有过的经历，与“了”不能同时用在同一个动词上，应去掉“了”，说“打过三星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
