INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "上下是差不多，多一点或少一点。", "primary_collocate": null, "pronunciation": "shàng xià", "ipa": "ʂɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服的价格在一百块上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的温度在二十五度上下，很舒服。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体重一直在六十公斤上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的客人有五十位上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月的电话费在八十块上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离我家走路二十分钟上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡觉的时间在七个小时上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的价钱三十块上下，不算贵。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一台这样的电视，两千块上下就够了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有三百人上下，不算大。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在数量后，表示差不多、略多或略少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "“上下”表示约数，“一百块上下”说明价格大约在一百块左右。"}, {"text": "上面", "is_correct": false, "explanation": "语法：“上面”是方位词，指位置，“在一百块上面”不能表示价格约数。"}, {"text": "多", "is_correct": false, "explanation": "语法：“多”要放在“块”前，如“一百多块”，“在一百块多”不成立。"}, {"text": "有余", "is_correct": false, "explanation": "语域：“有余”是书面语，口语介绍价格时很少这样说。"}], "explanations": {"上下": "“上下”表示约数，“一百块上下”说明价格大约在一百块左右。", "上面": "语法：“上面”是方位词，指位置，“在一百块上面”不能表示价格约数。", "多": "语法：“多”要放在“块”前，如“一百多块”，“在一百块多”不成立。", "有余": "语域：“有余”是书面语，口语介绍价格时很少这样说。"}, "sentence_index": 0, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我得了一百分上下。", "explanation": "这里应该去掉〈上下〉。〈上下〉表示大约，分数要说准确数，如“一百分”。"}, {"text": "这次活动有上下很多人参加。", "explanation": "这里应该去掉〈上下〉。〈上下〉是约数，必须紧跟数量词（如“三百人上下”），句中没有数量，应说“这次活动有很多人参加”。"}, {"text": "这台电脑的价格比那台上下三百块。", "explanation": "这里应该用〈多〉或〈少〉。〈上下〉是约数，不用于比较句中表示差额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "“上下”表示约数，“七个小时上下”说明睡觉时间大约是七小时。"}, {"text": "下面", "is_correct": false, "explanation": "语法：“下面”是方位词，指位置。“在七个小时下面”不能表示时间约数。"}, {"text": "附近", "is_correct": false, "explanation": "搭配：“附近”指地点周围，不能放在时间数量后表示约数。"}, {"text": "高低", "is_correct": false, "explanation": "语义：“高低”指高度或好坏，不表示约数，“七个小时高低”不成立。"}], "explanations": {"上下": "“上下”表示约数，“七个小时上下”说明睡觉时间大约是七小时。", "下面": "语法：“下面”是方位词，指位置。“在七个小时下面”不能表示时间约数。", "附近": "搭配：“附近”指地点周围，不能放在时间数量后表示约数。", "高低": "语义：“高低”指高度或好坏，不表示约数，“七个小时高低”不成立。"}, "sentence_index": 6, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司正好有三百人上下，一个不多。", "explanation": "这里应该去掉〈上下〉。〈上下〉表示约数，而句子强调人数准确，两者意思相反。"}, {"text": "比赛的奖金上下很高，大家都很开心。", "explanation": "这里应该用〈大约〉或〈左右〉。〈上下〉是放在数量后面的约数，不能直接修饰〈高〉这类形容词。"}, {"text": "今天的温度比昨天上下两度。", "explanation": "这里应该用〈高〉或〈低〉。〈上下〉是放在数量后面的约数，不用于比较句中表示差额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裙子的价格在两百块上下左右，有点贵。", "corrected_sentence": "这条裙子的价格在两百块上下，有点贵。", "error_description": "重复：“上下”已经表示约数，不能再加“左右”，应去掉“左右”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天走路的时间在一个小时上下左右。", "corrected_sentence": "他每天走路的时间在一个小时上下。", "error_description": "重复：“上下”已经表示约数，不能再加“左右”，应去掉“左右”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
