INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "表示大约的数量，用在数词后面。", "primary_collocate": null, "pronunciation": "shàng xià", "ipa": "ʂɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "那个男人四十岁上下，穿着一件黑衣服。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的个子一米六上下，不高也不矮。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上九点上下，外面下起雨来了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的学生有三十人上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明天早上六点上下就会到车站。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一个二十岁上下的女孩。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路长三公里上下，走路很快。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗五公斤上下，不算大。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买这本书花了五十块上下，我记不清了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的孩子七岁上下，很爱看书。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用在年龄、身高、时间等数词后表示大约", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。上下 shàng xià 表示大约的数量，用在数词后面。"}, {"text": "上限", "is_correct": false, "explanation": "xiàn（第四声）比 xià 多了韵尾 n，意思是“上限”，指最高限度。"}, {"text": "上校", "is_correct": false, "explanation": "xiào（第四声）与 xià 的韵母不同，意思是“上校”，一种军衔。"}, {"text": "上架", "is_correct": false, "explanation": "jià（第四声）与 xià 声母不同（j 与 x），意思是“上架”，即放到架子上。"}, {"text": "山下", "is_correct": false, "explanation": "shān（第一声）与 shàng 韵母不同（an 与 ang），声调也不同，意思是“山下”。"}], "explanations": {"上下": "正确答案。上下 shàng xià 表示大约的数量，用在数词后面。", "上限": "xiàn（第四声）比 xià 多了韵尾 n，意思是“上限”，指最高限度。", "上校": "xiào（第四声）与 xià 的韵母不同，意思是“上校”，一种军衔。", "上架": "jià（第四声）与 xià 声母不同（j 与 x），意思是“上架”，即放到架子上。", "山下": "shān（第一声）与 shàng 韵母不同（an 与 ang），声调也不同，意思是“山下”。"}, "sentence_index": null, "correct_answer": "上下"}, "level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。“上下”表示大约数量，用在“四十岁”这类数词后面。"}, {"text": "上面", "is_correct": false, "explanation": "语法：“上面”指位置，“四十岁上面”不能表示年龄约数。"}, {"text": "多少", "is_correct": false, "explanation": "语法：“多少”用来提问数量，“四十岁多少”不成立。"}, {"text": "余", "is_correct": false, "explanation": "语域：「余」是书面语，“四十岁余”与这句口语化的描述风格不符。"}], "explanations": {"上下": "正确答案。“上下”表示大约数量，用在“四十岁”这类数词后面。", "上面": "语法：“上面”指位置，“四十岁上面”不能表示年龄约数。", "多少": "语法：“多少”用来提问数量，“四十岁多少”不成立。", "余": "语域：「余」是书面语，“四十岁余”与这句口语化的描述风格不符。"}, "sentence_index": 0, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动正好三十人上下。", "explanation": "这里应该用〈整〉。“上下”表示大约，句中要说明确切人数，应说“整三十人”；“上下”不能表示确切数量。"}, {"text": "这个包很上下，我不想买。", "explanation": "这里应该去掉〈上下〉。“上下”要用在数量词后面表示大约，不能受“很”修饰作形容词。"}, {"text": "我们上下三十人去了公园。", "explanation": "这里应该说“三十人上下”。“上下”表示大约时必须放在数量词后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。“上下”表示大约的长度，用在数量词后面。"}, {"text": "下面", "is_correct": false, "explanation": "语法：“下面”指位置，“三公里下面”不能表示长度约数。"}, {"text": "旁边", "is_correct": false, "explanation": "搭配：“旁边”指位置，不能放在数量后表示大约。"}, {"text": "里面", "is_correct": false, "explanation": "语法：“里面”是方位词，“长三公里里面”不成立。"}], "explanations": {"上下": "正确答案。“上下”表示大约的长度，用在数量词后面。", "下面": "语法：“下面”指位置，“三公里下面”不能表示长度约数。", "旁边": "搭配：“旁边”指位置，不能放在数量后表示大约。", "里面": "语法：“里面”是方位词，“长三公里里面”不成立。"}, "sentence_index": 6, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子上下很高。", "explanation": "这里应该去掉〈上下〉。“上下”要跟在数量词后面表示大约，不能修饰“很高”。"}, {"text": "这次活动有三十多人上下。", "explanation": "这里应该去掉〈上下〉。“三十多”本身已是不确定的大约数，再加“上下”重复，应只说“三十多人”。"}, {"text": "这个孩子上下七岁。", "explanation": "这里应该说“七岁上下”。“上下”表示大约时要放在数量词后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个司机三十岁上下左右，很热情。", "corrected_sentence": "那个司机三十岁上下，很热情。", "error_description": "重复：“上下”已经表示大约，不能再加“左右”，应去掉“左右”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这箱苹果有二十斤上下左右。", "corrected_sentence": "这箱苹果有二十斤上下。", "error_description": "重复：“上下”已经表示大约，不能再加“左右”，应去掉“左右”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
