INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上进是想学得更好，想变得更好。", "primary_collocate": null, "pronunciation": "shàng jìn", "ipa": "ʂaŋ˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "小明很上进，总想把字写得更好。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很上进，所以每天多练习一小时。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥不太上进，只想玩游戏。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上进的学生会主动问老师问题。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想变得更好，所以特别上进。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹很上进，天天都想学新词。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做人要上进，不能总是懒懒的。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都很上进，都想考好。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前不上进，现在变了。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢上进的新同事。", "target_word": "上进", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "上進", "label": "繁体"}, {"form": "上进心", "label": "复合"}], "register": "中性", "sense_fingerprint": "想学得更好、想变得更好的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上进", "is_correct": true, "explanation": "上进（shàng jìn）：想学得更好，想变得更好，是正确答案。"}, {"text": "上镜", "is_correct": false, "explanation": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。"}, {"text": "上紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。"}, {"text": "上季", "is_correct": false, "explanation": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}], "explanations": {"上进": "上进（shàng jìn）：想学得更好，想变得更好，是正确答案。", "上镜": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。", "上紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。", "上季": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}, "sentence_index": null, "correct_answer": "上进"}, "level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境吵闹，不能用来修饰小明这样的人。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指想学得更好、想变得更好，与后句“总想把字写得更好”一致。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容人的品性。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容土地、天空等空间，不能修饰人。"}], "explanations": {"嘈杂": "搭配：“嘈杂”形容声音或环境吵闹，不能用来修饰小明这样的人。", "上进": "正确答案：“上进”指想学得更好、想变得更好，与后句“总想把字写得更好”一致。", "干燥": "语义：“干燥”指缺少水分，不能用来形容人的品性。", "辽阔": "搭配：“辽阔”形容土地、天空等空间，不能修饰人。"}, "sentence_index": 0, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的及格率很上进，比上次高了十个百分点。", "explanation": "这里应该用〈提高〉。上进形容人努力向上，及格率的增长要说提高，不能用上进。"}, {"text": "这个小区的环境很上进，周围的绿化一年比一年好。", "explanation": "这里应该用〈优美〉。上进用来形容人的态度，环境的美好要说优美。"}, {"text": "这块地的土质很上进，今年的庄稼长得特别好。", "explanation": "这里应该用〈肥沃〉。上进形容人想学得更好、想变得更好，土地的肥沃要说肥沃，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用于做人的要求。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“做人要上进”指做人要求进步、向上，与“不能总是懒懒的”一致。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水多，不能用来形容做人的态度。"}, {"text": "富丽", "is_correct": false, "explanation": "搭配：“富丽”形容建筑、陈设的华美，不能用于做人的要求。"}], "explanations": {"嘹亮": "搭配：“嘹亮”形容声音，不能用于做人的要求。", "上进": "正确答案：“做人要上进”指做人要求进步、向上，与“不能总是懒懒的”一致。", "潮湿": "语义：“潮湿”指空气或物体含水多，不能用来形容做人的态度。", "富丽": "搭配：“富丽”形容建筑、陈设的华美，不能用于做人的要求。"}, "sentence_index": 6, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很上进，坐起来特别舒服。", "explanation": "这里应该用〈舒适〉。上进只形容人想学得更好、想变得更好，不能用来形容椅子的舒适程度。"}, {"text": "这家店的生意很上进，周末总是排很长的队。", "explanation": "这里应该用〈兴隆〉。上进形容人努力向上，生意红火要说兴隆，不能用上进。"}, {"text": "这个城市的经济很上进，每年的收入都在增长。", "explanation": "这里应该用〈发达〉。上进形容人想学得更好、想变得更好，城市经济的繁荣要说发达，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很上进心，每天主动找老师问问题。", "corrected_sentence": "她很上进，每天主动找老师问问题。", "error_description": "错误：“很上进心”。“上进心”是名词，不能受程度副词“很”修饰作谓语，应说“很上进”，去掉“心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很上进学生。", "corrected_sentence": "他是一个很上进的学生。", "error_description": "错误：“很上进学生”。“很上进”这样带程度副词的形容词短语修饰名词时，中间必须加“的”，应为“很上进的学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
