INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "努力向上，要求进步。", "primary_collocate": null, "pronunciation": "shàng jìn", "ipa": "ʂaŋ˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他是一个很上进的学生。", "target_word": "上进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她学习很上进，每天都学新东西。", "target_word": "上进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上进的人不会满足于现在的样子。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟很上进，晚上还在看书。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师喜欢上进又努力的孩子。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻上进，公司的人都很看好他。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想上进的人，总是愿意多学一点。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这么上进，一定会有好成绩。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就上进，考试总是第一名。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个年轻人又聪明又上进。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上進", "label": "繁体"}, {"form": "上进心", "label": "复合"}], "register": "中性", "sense_fingerprint": "人努力向上、要求进步的品质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上进", "is_correct": true, "explanation": "上进（shàng jìn）：努力向上，要求进步，是正确答案。"}, {"text": "上镜", "is_correct": false, "explanation": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。"}, {"text": "上紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。"}, {"text": "上季", "is_correct": false, "explanation": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}], "explanations": {"上进": "上进（shàng jìn）：努力向上，要求进步，是正确答案。", "上镜": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。", "上紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。", "上季": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}, "sentence_index": null, "correct_answer": "上进"}, "level_3": {"options": [{"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水分多，不能用来形容学生的品质。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指努力向上、要求进步，能够描述学生的品质。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不能用来修饰学生这样的人。"}, {"text": "富丽", "is_correct": false, "explanation": "搭配：“富丽”形容建筑、陈设的华美，不能用来修饰学生。"}], "explanations": {"潮湿": "语义：“潮湿”指空气或物体含水分多，不能用来形容学生的品质。", "上进": "正确答案：“上进”指努力向上、要求进步，能够描述学生的品质。", "冷清": "搭配：“冷清”形容场所或气氛，不能用来修饰学生这样的人。", "富丽": "搭配：“富丽”形容建筑、陈设的华美，不能用来修饰学生。"}, "sentence_index": 0, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月公司的销售额很上进，比上个月多了三成。", "explanation": "这里应该用〈上升〉。上进形容人努力向上、要求进步，销售额的增长要说上升，不能用上进。"}, {"text": "这个社区的人数今年很上进，比去年多了两百人。", "explanation": "这里应该用〈增加〉。上进只用于形容人的态度，人数增多要说增加，不能说人数很上进。"}, {"text": "他的成绩很上进，这学期提高了很多。", "explanation": "这里应该用〈进步〉。上进形容人努力向上、要求进步的态度，成绩的变化要说进步，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与后句“总是愿意多学一点”的态度相反，搭配上不成立。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用来描述“想……的人”的态度。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指想学得更好、想变得更好，与“愿意多学一点”一致。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢、不灵活，与“愿意多学一点”的意思矛盾。"}], "explanations": {"懒惰": "语义：“懒惰”与后句“总是愿意多学一点”的态度相反，搭配上不成立。", "嘹亮": "搭配：“嘹亮”形容声音，不能用来描述“想……的人”的态度。", "上进": "正确答案：“上进”指想学得更好、想变得更好，与“愿意多学一点”一致。", "迟钝": "语义：“迟钝”指反应慢、不灵活，与“愿意多学一点”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆的生意很上进，每到周末都要排队。", "explanation": "这里应该用〈兴隆〉。上进形容人努力向上，生意红火要说兴隆，不能用上进。"}, {"text": "他的脸色很上进，看起来精神饱满。", "explanation": "这里应该用〈红润〉。上进只用来描述人的态度，形容脸色要说红润。"}, {"text": "妈妈做的菜很上进，大家都吃得很满意。", "explanation": "这里应该用〈可口〉。上进形容人的品质，形容菜的味道要说可口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位很上进老师。", "corrected_sentence": "他是一位很上进的老师。", "error_description": "错误：“很上进老师”。形容词“上进”修饰名词时，中间要加“的”，应为“很上进的老师”。漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很上进过，每天都早起学习。", "corrected_sentence": "她很上进，每天都早起学习。", "error_description": "体标误用：“很上进过”不成立。程度副词“很”描述的是现在的性质，后面又说“每天都早起学习”，说明她现在一直如此，不能用表示过去经历的“过”；应删去“过”，即“她很上进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失信", "is_correct": true, "explanation": "失信：失去信用，与“信用”构成反义关系（守信／失信）。"}, {"text": "天气", "is_correct": false, "explanation": "天气与“信用”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子与“信用”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流与“信用”没有反义关系。"}], "correct_answer": "失信", "explanations": {"失信": "失信：失去信用，与“信用”构成反义关系（守信／失信）。", "天气": "天气与“信用”没有反义关系。", "桌子": "桌子与“信用”没有反义关系。", "河流": "河流与“信用”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失信", "is_correct": true, "explanation": "失信：失去信用，与“信用”构成反义关系（守信／失信）。"}, {"text": "墙壁", "is_correct": false, "explanation": "墙壁与“信用”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头与“信用”没有反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶与“信用”没有反义关系。"}], "correct_answer": "失信", "explanations": {"失信": "失信：失去信用，与“信用”构成反义关系（守信／失信）。", "墙壁": "墙壁与“信用”没有反义关系。", "石头": "石头与“信用”没有反义关系。", "树叶": "树叶与“信用”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信用是一个人说话算数，别人相信他。", "primary_collocate": null, "pronunciation": "xìn yòng", "ipa": "ɕin⁵¹ jʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "他说话算数，很有信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意最重要的是信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人没有信用，别借钱给他。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不骗人，大家都看重他的信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要讲信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了信用，没人再相信他。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王总是迟到，信用越来越差。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保住信用，他每次都准时到。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很讲信用，说给钱就给钱。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信用比钱更重要。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信用卡", "label": "复合"}, {"form": "信用度", "label": "复合"}], "register": "中性", "sense_fingerprint": "说话算数而让人相信的品质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信用", "is_correct": true, "explanation": "信用：守约而让人相信的品质，与“说话算数”相符，句意通顺。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“很有”后接性质或能力类名词，不接“木头”，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很有”可以接“分量”“信用”，但不说“很有体重”。"}, {"text": "胡子", "is_correct": false, "explanation": "语义：“说话算数”与胡子无关，“很有胡子”也不成立。"}], "explanations": {"信用": "信用：守约而让人相信的品质，与“说话算数”相符，句意通顺。", "木头": "搭配：“很有”后接性质或能力类名词，不接“木头”，句子不通。", "体重": "搭配：“很有”可以接“分量”“信用”，但不说“很有体重”。", "胡子": "语义：“说话算数”与胡子无关，“很有胡子”也不成立。"}, "sentence_index": 0, "correct_answer": "信用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这次考试很有信用。", "explanation": "这里应该用〈信心〉。信用指守约而被人相信的品质，对考试的把握要用“信心”。"}, {"text": "他对宗教有很深的信用。", "explanation": "这里应该用〈信仰〉。信用指守约而被信任的品质，对宗教的信奉要用“信仰”。"}, {"text": "手机没有信用，电话打不出去。", "explanation": "这里应该用〈信号〉。信用指守约而被信任的品质，手机收不到的无线电讯号要说“信号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信用", "is_correct": true, "explanation": "信用：守约而让人相信的品质，与“迟到”形成对比，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：小王迟到不会影响天气，“天气越来越差”与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：说体重变化用“重”，不说“体重越来越差”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：迟到与窗户无关，“窗户越来越差”不通。"}], "explanations": {"信用": "信用：守约而让人相信的品质，与“迟到”形成对比，句意通顺。", "天气": "语义：小王迟到不会影响天气，“天气越来越差”与句意不符。", "体重": "搭配：说体重变化用“重”，不说“体重越来越差”。", "窗户": "语义：迟到与窗户无关，“窗户越来越差”不通。"}, "sentence_index": 6, "correct_answer": "信用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对理想很有信用。", "explanation": "这里应该用〈信念〉。信用指守约而被信任的品质，对理想的坚定信心要用“信念”。"}, {"text": "我收到了他的信用。", "explanation": "这里应该用〈信件〉。信用指守约而被信任的品质，收到的书信要说“信件”，不能说“信用”。"}, {"text": "他关上了信用，不再说话。", "explanation": "这里应该用〈门〉。信用指守约而被信任的品质，不能用来关上，应说“关上门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事一直守约，很信用。", "corrected_sentence": "他做事一直守约，很有信用。", "error_description": "名词“信用”不能直接受“很”修饰，前面要加动词“有”或“讲”。应说“很有信用”，不说“很信用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他守约很多年，信用已经建立起了来。", "corrected_sentence": "他守约很多年，信用已经建立起来了。", "error_description": "趋向补语“起来”中间不能插入“了”，“了”应放在“起来”后面，应说“建立起来了”，不说“建立起了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
