INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失信", "is_correct": true, "explanation": "失信：失去信用，与“信用”构成反义关系（守信／失信）。"}, {"text": "书包", "is_correct": false, "explanation": "书包与“信用”没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "草地与“信用”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与“信用”没有反义关系。"}], "correct_answer": "失信", "explanations": {"失信": "失信：失去信用，与“信用”构成反义关系（守信／失信）。", "书包": "书包与“信用”没有反义关系。", "草地": "草地与“信用”没有反义关系。", "雨伞": "雨伞与“信用”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遵守诺言、实践约定而取得的信任。", "primary_collocate": null, "pronunciation": "xìn yòng", "ipa": "ɕin⁵¹ jʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "他按时还钱，慢慢有了信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每次按时交货，在客户中信用很好。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用行动建立自己的信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次说谎，会让多年的信用消失。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他守约十年，在城里很有信用。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从不卖假货，所以信用很好。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要赢得信用，先要遵守诺言。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次都做到了，信用就这样建立了。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行看他的信用，再决定借不借钱。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直守约，在同事中信用很高。", "target_word": "信用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信用卡", "label": "复合"}, {"form": "信用度", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠守约、按时兑现承诺而赢得的信任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信用", "is_correct": true, "explanation": "信用：遵守诺言换来的信任，与“按时还钱”相符，句意通顺。"}, {"text": "雨", "is_correct": false, "explanation": "语义：按时还钱与“有了雨”无关，句意不通。"}, {"text": "债", "is_correct": false, "explanation": "语义：按时还钱说明没有欠债，“慢慢有了债”与句意相反。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：按时还钱不会让人“有了翅膀”，句意不通。"}], "explanations": {"信用": "信用：遵守诺言换来的信任，与“按时还钱”相符，句意通顺。", "雨": "语义：按时还钱与“有了雨”无关，句意不通。", "债": "语义：按时还钱说明没有欠债，“慢慢有了债”与句意相反。", "翅膀": "语义：按时还钱不会让人“有了翅膀”，句意不通。"}, "sentence_index": 0, "correct_answer": "信用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对明天的计划很有信用。", "explanation": "这里应该用〈信心〉。信用指遵守诺言换来的信任，对计划的把握要用“信心”。"}, {"text": "他在山里走了一天，手机一直没有信用。", "explanation": "这里应该用〈信号〉。信用指遵守诺言换来的信任，手机收不到的无线电讯号要说“信号”。"}, {"text": "他推开了信用，走进屋里。", "explanation": "这里应该用〈门〉。信用指遵守诺言换来的信任，不能用来推开，应说“推开门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信用", "is_correct": true, "explanation": "信用：遵守诺言换来的信任，与“遵守诺言”相符，句意通顺。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是靠遵守诺言得到的，句意不通。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“赢得”后接荣誉、信任等好的东西，不说“赢得疾病”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是靠遵守诺言得到的，句意不通。"}], "explanations": {"信用": "信用：遵守诺言换来的信任，与“遵守诺言”相符，句意通顺。", "名字": "语义：名字不是靠遵守诺言得到的，句意不通。", "疾病": "搭配：“赢得”后接荣誉、信任等好的东西，不说“赢得疾病”。", "影子": "语义：影子不是靠遵守诺言得到的，句意不通。"}, "sentence_index": 6, "correct_answer": "信用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对科学有深深的信用。", "explanation": "这里应该用〈信仰〉。信用指遵守诺言换来的信任，对科学的信奉要用“信仰”。"}, {"text": "我收到了朋友的信用，很高兴。", "explanation": "这里应该用〈信件〉。信用指遵守诺言换来的信任，朋友寄来的书信要说“信件”，不能说“信用”。"}, {"text": "他的信用漏雨了。", "explanation": "这里应该用〈房子〉。信用指遵守诺言换来的信任，不是建筑物，不能说“漏雨”，应说“房子漏雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他守约十年，在同行中很信用。", "corrected_sentence": "他守约十年，在同行中很有信用。", "error_description": "“信用”前要有动词“有”，应说“很有信用”。漏掉“有”，说“很信用”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是提前还钱，所以信用慢慢建立起了来。", "corrected_sentence": "他总是提前还钱，所以信用慢慢建立起来了。", "error_description": "趋向补语“起来”中间不能插入“了”，“了”应放在“起来”后面，应说“建立起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "债权", "is_correct": true, "explanation": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。"}, {"text": "工资", "is_correct": false, "explanation": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。"}, {"text": "房租", "is_correct": false, "explanation": "「房租」指租房要付的钱，与「债务」不构成反义关系。"}, {"text": "收入", "is_correct": false, "explanation": "「收入」与「支出」相对，与「债务」不构成反义关系。"}], "correct_answer": "债权", "explanations": {"债权": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。", "工资": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。", "房租": "「房租」指租房要付的钱，与「债务」不构成反义关系。", "收入": "「收入」与「支出」相对，与「债务」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "债权", "is_correct": true, "explanation": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。"}, {"text": "工资", "is_correct": false, "explanation": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。"}, {"text": "利润", "is_correct": false, "explanation": "「利润」指经营后的收益，与「债务」不构成反义关系。"}, {"text": "税收", "is_correct": false, "explanation": "「税收」指国家收的税，与「债务」不构成反义关系。"}], "correct_answer": "债权", "explanations": {"债权": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。", "工资": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。", "利润": "「利润」指经营后的收益，与「债务」不构成反义关系。", "税收": "「税收」指国家收的税，与「债务」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债务是你借了别人的钱，要还给别人。", "primary_collocate": null, "pronunciation": "zhài wù", "ipa": "ʈʂaɪ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "他借了很多钱，现在背着一大笔债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了还债务，他每天打两份工。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的债务越来越多。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于还清了所有债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父亲去世后，儿子替他还了债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想借钱，因为不想有债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用工资一点一点还债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮他解决了债务问题。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚工作，已经有五万元债务了。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有债务，所以不敢买新房子。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔债务", "label": "量词"}, {"form": "債務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "债务：名词，借别人的钱后要还的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc29dc70-dc3b-43f5-8c12-a16457eab3c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债务", "is_correct": true, "explanation": "「债务」指欠别人的钱，需要偿还，是本题的正确答案。"}, {"text": "账务", "is_correct": false, "explanation": "「账务」（zhàngwù）与「债务」（zhàiwù）只有韵母不同：ài 与 àng，意思是账目方面的事务。"}, {"text": "债户", "is_correct": false, "explanation": "「债户」（zhàihù）与「债务」（zhàiwù）第二个字声母不同：h 与 w，意思是欠债的人。"}, {"text": "站务", "is_correct": false, "explanation": "「站务」（zhànwù）与「债务」（zhàiwù）韵母不同：an 与 ai，意思是车站的事务。"}], "explanations": {"债务": "「债务」指欠别人的钱，需要偿还，是本题的正确答案。", "账务": "「账务」（zhàngwù）与「债务」（zhàiwù）只有韵母不同：ài 与 àng，意思是账目方面的事务。", "债户": "「债户」（zhàihù）与「债务」（zhàiwù）第二个字声母不同：h 与 w，意思是欠债的人。", "站务": "「站务」（zhànwù）与「债务」（zhàiwù）韵母不同：an 与 ai，意思是车站的事务。"}, "sentence_index": null, "correct_answer": "债务"}, "level_3": {"options": [{"text": "债务", "is_correct": true, "explanation": "正确：借了很多钱之后欠下的钱正是「债务」，与句意一致。"}, {"text": "存款", "is_correct": false, "explanation": "语义：存款是存进银行的钱，与「借了很多钱」的负债情况正好相反，句子不通。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是额外得到的钱，与「借钱」无关，放在这里句意矛盾。"}, {"text": "债主", "is_correct": false, "explanation": "搭配：「一大笔」修饰的是钱款，不能修饰人；「债主」指借钱给别人的人。"}], "explanations": {"债务": "正确：借了很多钱之后欠下的钱正是「债务」，与句意一致。", "存款": "语义：存款是存进银行的钱，与「借了很多钱」的负债情况正好相反，句子不通。", "奖金": "语义：奖金是额外得到的钱，与「借钱」无关，放在这里句意矛盾。", "债主": "搭配：「一大笔」修饰的是钱款，不能修饰人；「债主」指借钱给别人的人。"}, "sentence_index": 0, "correct_answer": "债务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向同事申请了一笔债务，买了新电脑。", "explanation": "这里应该用〈借款〉。申请的是借款；债务指已经欠下、需要偿还的钱，不能去申请。"}, {"text": "这家银行向小企业发放了很多债务。", "explanation": "这里应该用〈贷款〉。银行发放的是贷款；债务是已经欠下的钱，不能由银行发放。"}, {"text": "他拥有一笔债务，对方到期会还他钱。", "explanation": "这里应该用〈债权〉。债权是别人欠自己的钱，对方要还钱给他，应该说债权；债务是自己欠别人的钱，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "债务", "is_correct": true, "explanation": "正确：用工资一点一点偿还的是「债务」，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是用来还债的手段，不能再作为被还的对象，句子自相矛盾。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：「还」的对象是欠下的钱，不能说「还收入」。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：利润是赚来的钱，不能说「还利润」。"}], "explanations": {"债务": "正确：用工资一点一点偿还的是「债务」，句意通顺。", "工资": "语义：工资是用来还债的手段，不能再作为被还的对象，句子自相矛盾。", "收入": "搭配：「还」的对象是欠下的钱，不能说「还收入」。", "利润": "搭配：利润是赚来的钱，不能说「还利润」。"}, "sentence_index": 6, "correct_answer": "债务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都向银行存入一笔债务。", "explanation": "这里不能用「存入」。存入银行的是存款；债务是欠别人的钱，要还，不能存进银行。"}, {"text": "这笔债务的颜色很鲜艳。", "explanation": "这里把〈债务〉当成了〈布料〉这类有颜色的实物。债务是欠钱的关系，没有颜色，不能用「鲜艳」形容。"}, {"text": "他每天都在给债务打电话。", "explanation": "「打电话」的对象必须是人或机构，债务不能打电话；这里应该说「还债务」之类的表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一年内终于还清了一只债务。", "corrected_sentence": "他一年内终于还清了一笔债务。", "error_description": "量词错误：「债务」应搭配量词「笔」，不能用「只」。正确说法是「一笔债务」，「只」只用于动物、成对物品中的单个等，不能修饰「债务」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每个月都还在债务，压力很大。", "corrected_sentence": "他每个月都在还债务，压力很大。", "error_description": "错误：进行体「在」位置不对。正确说法是「在还债务」，「在」要放在动词「还」前面，不能说「还在债务」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
