INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93990, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于成套书籍的分册：指书的本数，或某一分册的序号（第几册）。", "primary_collocate": null, "pronunciation": "cè", "ipa": "tsʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "这套书一共有三册。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经看完了第一册。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二册的内容比第一册难。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说有五册，我只买了两册。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借了这套词典的第三册。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下个月我们学第四册。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套漫画书一共十册，很好看。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把第一册拿给我，谢谢。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里只有第六册，别的都借走了。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套百科全书共二十册，非常厚。", "target_word": "册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "册：量词，用于成套书籍的本数或分册序号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "册", "is_correct": true, "explanation": "册：装订成册的书，作量词用于成套书籍的本数，即正确答案。"}, {"text": "次", "is_correct": false, "explanation": "cì（第四声）与 cè 声调相同，韵母不同（i 与 e），意思是次数。"}, {"text": "色", "is_correct": false, "explanation": "sè（第四声）与 cè 声调相同，声母不同（s 与 c），意思是颜色。"}, {"text": "撤", "is_correct": false, "explanation": "chè（第四声）与 cè 声调相同，声母不同（ch 与 c），意思是撤回。"}, {"text": "热", "is_correct": false, "explanation": "rè（第四声）与 cè 声调相同，声母不同（r 与 c），意思是温度高。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 cè 声调相同，韵母不同（u 与 e），意思是醋。"}], "explanations": {"册": "册：装订成册的书，作量词用于成套书籍的本数，即正确答案。", "次": "cì（第四声）与 cè 声调相同，韵母不同（i 与 e），意思是次数。", "色": "sè（第四声）与 cè 声调相同，声母不同（s 与 c），意思是颜色。", "撤": "chè（第四声）与 cè 声调相同，声母不同（ch 与 c），意思是撤回。", "热": "rè（第四声）与 cè 声调相同，声母不同（r 与 c），意思是温度高。", "醋": "cù（第四声）与 cè 声调相同，韵母不同（u 与 e），意思是醋。"}, "sentence_index": null, "correct_answer": "册"}, "level_3": {"options": [{"text": "册", "is_correct": true, "explanation": "册：量词，指成套书籍的本数，与“三”搭配，符合句意。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸张、平面的东西，不用来数书。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”多用于衣物、事情，不用来数书。"}, {"text": "页", "is_correct": false, "explanation": "语义：“页”数的是书页，不是套书的本数，与“一共有三”不符。"}], "explanations": {"册": "册：量词，指成套书籍的本数，与“三”搭配，符合句意。", "张": "搭配：“张”用于纸张、平面的东西，不用来数书。", "件": "搭配：“件”多用于衣物、事情，不用来数书。", "页": "语义：“页”数的是书页，不是套书的本数，与“一共有三”不符。"}, "sentence_index": 0, "correct_answer": "册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我桌上有三册照片。", "explanation": "这里应该用〈张〉。照片是平面的，用“张”计量；“册”只用于装订成册的书籍。"}, {"text": "我家里有两册冰箱。", "explanation": "这里应该用〈台〉。冰箱用“台”计量；“册”只用于书籍。"}, {"text": "我昨天喝了一册牛奶。", "explanation": "这里应该用〈瓶〉。牛奶用“瓶”“盒”等计量；“册”只用于装订成册的书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "册", "is_correct": true, "explanation": "册：装订成册的书，作量词用于成套书籍的本数，即正确答案。"}, {"text": "刺", "is_correct": false, "explanation": "cì（第四声）与 cè 声调相同，韵母不同（i 与 e），意思是刺。"}, {"text": "舍", "is_correct": false, "explanation": "shè（第四声）与 cè 声调相同，声母不同（sh 与 c），意思是房屋，如宿舍。"}, {"text": "热", "is_correct": false, "explanation": "rè（第四声）与 cè 声调相同，声母不同（r 与 c），意思是温度高。"}], "explanations": {"册": "册：装订成册的书，作量词用于成套书籍的本数，即正确答案。", "刺": "cì（第四声）与 cè 声调相同，韵母不同（i 与 e），意思是刺。", "舍": "shè（第四声）与 cè 声调相同，声母不同（sh 与 c），意思是房屋，如宿舍。", "热": "rè（第四声）与 cè 声调相同，声母不同（r 与 c），意思是温度高。"}, "sentence_index": null, "correct_answer": "册"}, "level_3": {"options": [{"text": "册", "is_correct": true, "explanation": "册：量词，指成套书籍的本数，与“十”搭配，符合句意。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于画作、字画，不用来数书。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”用于文章，不是漫画书套书的册数，与“一共十”不符。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不用来数书。"}], "explanations": {"册": "册：量词，指成套书籍的本数，与“十”搭配，符合句意。", "幅": "搭配：“幅”用于画作、字画，不用来数书。", "篇": "语义：“篇”用于文章，不是漫画书套书的册数，与“一共十”不符。", "首": "搭配：“首”用于诗歌、歌曲，不用来数书。"}, "sentence_index": 6, "correct_answer": "册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看了一册电影。", "explanation": "这里应该用〈部〉。电影用“部”计量；“册”只用于装订成册的书籍。"}, {"text": "我买了一册面包。", "explanation": "这里应该用〈个〉。面包用“个”计量；“册”只用于书籍。"}, {"text": "这册手机很好。", "explanation": "这里应该用〈部〉。手机用“部”计量；“册”只用于装订成册的书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买的那套故事书一共有四个册。", "corrected_sentence": "他买的那套故事书一共有四册。", "error_description": "错误：“册”本身就是量词，数词后直接接“册”，前面不能再加量词“个”。应说“四册”，不说“四个册”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两本册书。", "corrected_sentence": "我买了两册书。", "error_description": "错误：量词“册”前面已有量词“本”，两个量词叠用，应只用“册”，即“两册书”，不能说“两本册书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
