INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93991, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "凡是所有的，只要是这样的都包括。", "primary_collocate": null, "pronunciation": "fán", "ipa": "fan˧˥", "syllable_count": 1, "sentences": [{"text": "凡爱学习的孩子，老师都喜欢。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡学过汉语的人，都知道四声。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡有票的人，都能进去。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡没通过考试的人，下个月可以再考。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡去过北京的朋友，都说那儿很热闹。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡我认识的人，都知道这件事。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡在这里工作的人，都要早起。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡生病的人，都应该多休息。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡要进门的客人，都得先换鞋。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡会开车的人，都要遵守交通规则。", "target_word": "凡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，引出条件范围，只要符合这个条件的全都包括在内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93991, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凡", "is_correct": true, "explanation": "凡（fán，第二声）：凡是所有的，即本词。"}, {"text": "反", "is_correct": false, "explanation": "反（fǎn，第三声）与凡（fán，第二声）声调不同，意思是相反。"}, {"text": "饭", "is_correct": false, "explanation": "饭（fàn，第四声）与凡（fán，第二声）声调不同，意思是米饭。"}, {"text": "房", "is_correct": false, "explanation": "房（fáng）与凡（fán）韵母不同，是 ang 与 an 之别，意思是房子。"}, {"text": "寒", "is_correct": false, "explanation": "寒（hán）与凡（fán）声母不同，是 h 与 f 之别，意思是寒冷。"}, {"text": "帆", "is_correct": false, "explanation": "帆（fān，第一声）与凡（fán，第二声）声调不同，意思是船帆。"}], "explanations": {"凡": "凡（fán，第二声）：凡是所有的，即本词。", "反": "反（fǎn，第三声）与凡（fán，第二声）声调不同，意思是相反。", "饭": "饭（fàn，第四声）与凡（fán，第二声）声调不同，意思是米饭。", "房": "房（fáng）与凡（fán）韵母不同，是 ang 与 an 之别，意思是房子。", "寒": "寒（hán）与凡（fán）声母不同，是 h 与 f 之别，意思是寒冷。", "帆": "帆（fān，第一声）与凡（fán，第二声）声调不同，意思是船帆。"}, "sentence_index": null, "correct_answer": "凡"}, "level_3": {"options": [{"text": "凡", "is_correct": true, "explanation": "凡（fán）表示只要是这样的都包括在内，与后文“都”呼应，符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常、少数情况，与“老师都喜欢”所表达的全部包括相矛盾。"}, {"text": "大多", "is_correct": false, "explanation": "语义：“大多”表示大部分而非全部，与“都”所表达的包括全部不符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，而“爱”是持续的心理状态，不能用进行体修饰。"}], "explanations": {"凡": "凡（fán）表示只要是这样的都包括在内，与后文“都”呼应，符合句意。", "偶尔": "语义：“偶尔”表示不经常、少数情况，与“老师都喜欢”所表达的全部包括相矛盾。", "大多": "语义：“大多”表示大部分而非全部，与“都”所表达的包括全部不符。", "正在": "体貌：“正在”表示进行中，而“爱”是持续的心理状态，不能用进行体修饰。"}, "sentence_index": 0, "correct_answer": "凡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凡小明没通过考试，下个月可以再考。", "explanation": "“凡”只能引出一类人或事物（如“凡……的人”），表示其中全部，不能直接带“小明”这样的特定个人。应去掉“凡”，说“小明没通过考试，下个月可以再考”。"}, {"text": "这只是一件凡俗的小事，不必放在心上。", "explanation": "这里的“凡”是“凡俗”的意思，指平常、世俗，属于另一个义项，与“凡是”表示全部的意思无关。"}, {"text": "我昨天遇到了凡没通过考试的人。", "explanation": "这里应该用〈那些〉。“凡”指范围内的全部，不能用来指向过去具体遇到的人，这里说的是特定的一批人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93991, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凡", "is_correct": true, "explanation": "凡（fán，第二声）：凡是所有的，即本词。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān，第一声）与凡（fán，第二声）声调不同，意思是翻动、翻译。"}, {"text": "范", "is_correct": false, "explanation": "范（fàn，第四声）与凡（fán，第二声）声调不同，意思是范围、模范。"}, {"text": "防", "is_correct": false, "explanation": "防（fáng）与凡（fán）韵母不同，是 ang 与 an 之别，意思是防止。"}, {"text": "含", "is_correct": false, "explanation": "含（hán）与凡（fán）声母不同，是 h 与 f 之别，意思是包含。"}, {"text": "犯", "is_correct": false, "explanation": "犯（fàn，第四声）与凡（fán，第二声）声调不同，意思是犯错。"}], "explanations": {"凡": "凡（fán，第二声）：凡是所有的，即本词。", "翻": "翻（fān，第一声）与凡（fán，第二声）声调不同，意思是翻动、翻译。", "范": "范（fàn，第四声）与凡（fán，第二声）声调不同，意思是范围、模范。", "防": "防（fáng）与凡（fán）韵母不同，是 ang 与 an 之别，意思是防止。", "含": "含（hán）与凡（fán）声母不同，是 h 与 f 之别，意思是包含。", "犯": "犯（fàn，第四声）与凡（fán，第二声）声调不同，意思是犯错。"}, "sentence_index": null, "correct_answer": "凡"}, "level_3": {"options": [{"text": "凡", "is_correct": true, "explanation": "凡（fán）表示在一定范围内无例外，与后文“都”呼应，符合句意。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，表示承认让步，与句子的语气和语义都不协调。"}, {"text": "一共", "is_correct": false, "explanation": "配价：“一共”需要带数量成分，这里缺少数量，结构不完整。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”修饰形容词或心理动词，不能修饰“在这里工作”这类动作短语。"}], "explanations": {"凡": "凡（fán）表示在一定范围内无例外，与后文“都”呼应，符合句意。", "诚然": "语域：“诚然”是书面语，表示承认让步，与句子的语气和语义都不协调。", "一共": "配价：“一共”需要带数量成分，这里缺少数量，结构不完整。", "最": "搭配：“最”修饰形容词或心理动词，不能修饰“在这里工作”这类动作短语。"}, "sentence_index": 6, "correct_answer": "凡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早已看破了凡尘，不再关心俗事。", "explanation": "这里的“凡”指尘世、人间，属于“凡尘”一词的另一义项，与表示全部的“凡是”无关。"}, {"text": "他只是个凡人，没有什么特别的天赋。", "explanation": "这里应该用〈普通〉。“凡人”中的“凡”指平常、普通，与表示全部的“凡是”不同。"}, {"text": "凡会开车的人，大多要遵守交通规则。", "explanation": "这里应该用〈都〉。“大多”表示大部分而非全部，与“凡”表示的全部无例外相矛盾，应改为“都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有凡病的学生，都可以请假。", "corrected_sentence": "凡有病的学生，都可以请假。", "error_description": "错误：“凡”位于动词“有”之后，插在“有”与宾语“病”之间，位置不当。“凡”只能位于句首统领整个主语，不能嵌在谓语内部。正确：“凡有病的学生”，“凡”位于句首，与“都”呼应。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凡进入实验室人，都要戴手套。", "corrected_sentence": "凡进入实验室的人，都要戴手套。", "error_description": "错误：“进入实验室”与中心词“人”之间漏掉结构助词“的”，定语结构不完整。正确：“凡进入实验室的人”，“的”连接修饰语与中心词，“凡”位于句首，与“都”呼应。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
