INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "划是用笔或刀在东西上画出一道线。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "他用笔在纸上划一条线。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在书上划出了重点。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在答案下面划线。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用铅笔在木板上划了一道线。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有人用粉笔划了一道线。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时，请把错的句子划掉。", "target_word": "划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地图上划着一条红线。", "target_word": "划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书时，我喜欢在好句子下面划线。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在桌子上乱划，这是新的。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿出尺子，在本子上划了两条线。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "划了", "label": "完成体"}, {"form": "划过", "label": "经历体"}, {"form": "劃", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划·huà·用笔或刀在物体上画出线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "划", "is_correct": true, "explanation": "正确答案。划 huà 指用笔或刀在物体上画出一道线。"}, {"text": "花", "is_correct": false, "explanation": "声调不同：huā（第一声）与 huà（第四声）不同，意思是花朵。"}, {"text": "华", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）不同，意思是中华、华丽。"}, {"text": "换", "is_correct": false, "explanation": "韵尾不同：huàn 比 huà 多一个 -n，意思是交换。"}, {"text": "挂", "is_correct": false, "explanation": "声母不同：guà 的声母是 g，不是 h，意思是悬挂。"}], "explanations": {"划": "正确答案。划 huà 指用笔或刀在物体上画出一道线。", "花": "声调不同：huā（第一声）与 huà（第四声）不同，意思是花朵。", "华": "声调不同：huá（第二声）与 huà（第四声）不同，意思是中华、华丽。", "换": "韵尾不同：huàn 比 huà 多一个 -n，意思是交换。", "挂": "声母不同：guà 的声母是 g，不是 h，意思是悬挂。"}, "sentence_index": null, "correct_answer": "划"}, "level_3": {"options": [{"text": "划", "is_correct": true, "explanation": "正确。“用笔在纸上”与画出一道线的意思相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去痕迹，不能用笔在纸上擦出一条线。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连缀，与“用笔”不相配。"}, {"text": "切", "is_correct": false, "explanation": "搭配：切需要刀类工具，不能用笔切出一条线。"}], "explanations": {"划": "正确。“用笔在纸上”与画出一道线的意思相合。", "擦": "语义：擦是抹去痕迹，不能用笔在纸上擦出一条线。", "缝": "语义：缝是用针线连缀，与“用笔”不相配。", "切": "搭配：切需要刀类工具，不能用笔切出一条线。"}, "sentence_index": 0, "correct_answer": "划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用笔在纸上划了一只小猫。", "explanation": "这里应该用〈画〉。划只表示用笔、刀等在物体上画出线条或痕迹，画猫这类图形要用〈画〉。"}, {"text": "他用笔在纸上划了一个名字。", "explanation": "这里应该用〈写〉。划指画线，写名字是用笔写字，要用〈写〉。"}, {"text": "他在纸上划了一幅画。", "explanation": "这里应该用〈画〉。划只表示用笔、刀在物体上画出线条或痕迹，画成完整的图画要用〈画〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93995, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "划", "is_correct": true, "explanation": "正确答案。划 huà 指用笔或刀在物体上画出一道线。"}, {"text": "怀", "is_correct": false, "explanation": "韵母不同：huái 比 huà 多一个元音 -i，意思是怀抱。"}, {"text": "滑", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）不同，意思是光滑。"}, {"text": "跨", "is_correct": false, "explanation": "声母不同：kuà 的声母是 k，不是 h，意思是跨越。"}], "explanations": {"划": "正确答案。划 huà 指用笔或刀在物体上画出一道线。", "怀": "韵母不同：huái 比 huà 多一个元音 -i，意思是怀抱。", "滑": "声调不同：huá（第二声）与 huà（第四声）不同，意思是光滑。", "跨": "声母不同：kuà 的声母是 k，不是 h，意思是跨越。"}, "sentence_index": null, "correct_answer": "划"}, "level_3": {"options": [{"text": "划", "is_correct": true, "explanation": "正确。画出线条，与地图和红线相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣服或穿过孔洞，不说在地图上穿一条线。"}, {"text": "削", "is_correct": false, "explanation": "语义：削是除去物体表层，不能在地图上削出一条红线。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕会破坏纸面，不能撕出一条红线。"}], "explanations": {"划": "正确。画出线条，与地图和红线相合。", "穿": "搭配：穿用于衣服或穿过孔洞，不说在地图上穿一条线。", "削": "语义：削是除去物体表层，不能在地图上削出一条红线。", "撕": "语义：撕会破坏纸面，不能撕出一条红线。"}, "sentence_index": 6, "correct_answer": "划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用橡皮划了两条线。", "explanation": "这里应该用〈擦〉。用橡皮去掉痕迹说〈擦〉，划表示画出线条。"}, {"text": "他用蜡笔在纸上划了一大片红色。", "explanation": "这里应该用〈涂〉。涂指把颜色铺满一个面，划只表示画出线条。"}, {"text": "她用尺子划了桌子的长度。", "explanation": "这里应该用〈量〉。量是测定长短，用尺子量长度不是画线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上了划一条直线。", "corrected_sentence": "他在纸上划了一条直线。", "error_description": "“了”放错位置：应放在动词后，说“划了一条直线”，不能放在“划”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在黑板上划了一只线。", "corrected_sentence": "老师在黑板上划了一条线。", "error_description": "量词错误：“线”的量词应为“条”，不能用“只”，应说“划了一条线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
