INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93997, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "勒是用绳子拉紧，缠住东西。", "primary_collocate": null, "pronunciation": "lēi", "ipa": "leɪ˥", "syllable_count": 1, "sentences": [{"text": "书包带勒得我肩膀很疼。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的腰带勒得太紧。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子勒在手上，留下了红印。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的领带勒得脖子不舒服。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的绳子勒着脖子，它很难受。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子的带子勒得我下巴疼。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子的提手勒着手指。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头绳勒得她头皮有点疼。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太紧的袜子会勒着腿。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背了一天的包，肩上勒出了红印。", "target_word": "勒", "complexity_tier": "T3", "furigana": "tā bēi le yì tiān de bāo, jiān shang lēi chū le hóng yìn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "勒紧", "label": "复合"}, {"form": "勒住", "label": "复合"}, {"form": "勒了", "label": "体标"}, {"form": "勒着", "label": "体标"}, {"form": "勒过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：绳子、带子缠住并紧紧压在身体或物体上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '239c4ca9-a8a6-4a41-8dd0-af48221448b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勒", "is_correct": true, "explanation": "lēi（第一声）意思是用带子、绳子缠住身体或物体并紧紧压住。"}, {"text": "累", "is_correct": false, "explanation": "lèi（第四声）与 lēi（第一声）声调不同，意思是劳累。"}, {"text": "雷", "is_correct": false, "explanation": "léi（第二声）与 lēi（第一声）声调不同，意思是雷电。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 lēi（第一声）声调不同，意思是堆砌、垒起。"}], "explanations": {"勒": "lēi（第一声）意思是用带子、绳子缠住身体或物体并紧紧压住。", "累": "lèi（第四声）与 lēi（第一声）声调不同，意思是劳累。", "雷": "léi（第二声）与 lēi（第一声）声调不同，意思是雷电。", "垒": "lěi（第三声）与 lēi（第一声）声调不同，意思是堆砌、垒起。"}, "sentence_index": null, "correct_answer": "勒"}, "level_3": {"options": [{"text": "勒", "is_correct": true, "explanation": "“书包带勒得我肩膀很疼”指背带缠紧压在肩上，与“得”引出的状态相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：书包带不会唱，“唱得我肩膀疼”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语义：书包带不会跑，“跑得我肩膀疼”的主语不合理。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，与背带压在肩上的状态不符。"}], "explanations": {"勒": "“书包带勒得我肩膀很疼”指背带缠紧压在肩上，与“得”引出的状态相符。", "唱": "语义：书包带不会唱，“唱得我肩膀疼”不成立。", "跑": "语义：书包带不会跑，“跑得我肩膀疼”的主语不合理。", "扔": "语义：“扔”是抛掷，与背带压在肩上的状态不符。"}, "sentence_index": 0, "correct_answer": "勒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他勒着眼镜读书。", "explanation": "这里应该用〈戴〉。勒指用绳子、带子缠紧身体，眼镜是架在脸上的，不能说“勒着眼镜”。"}, {"text": "他勒着伞走路。", "explanation": "这里应该用〈撑〉。勒指带子、绳子缠紧，伞不能被“勒”。"}, {"text": "妈妈用手勒着面团。", "explanation": "这里应该用〈揉〉。勒指绳带等缠紧压住，不能用手去“勒”面团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勒", "is_correct": true, "explanation": "“袋子的提手勒着手指”指提手紧紧压住手指，与“着”表示的持续状态相符。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“手指”作宾语。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”需要有人的动作，袋子的提手不能去摸手指。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是口腔的动作，提手不会咬东西，与“勒”的压紧意义不合。"}], "explanations": {"勒": "“袋子的提手勒着手指”指提手紧紧压住手指，与“着”表示的持续状态相符。", "笑": "配价：“笑”是不及物动词，不能带“手指”作宾语。", "摸": "语义：“摸”需要有人的动作，袋子的提手不能去摸手指。", "咬": "语义：“咬”是口腔的动作，提手不会咬东西，与“勒”的压紧意义不合。"}, "sentence_index": 6, "correct_answer": "勒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蚊子勒出了几个红包。", "explanation": "这里应该用〈咬〉。勒指用带子等紧紧缠压，蚊子不能“勒”人。"}, {"text": "石头勒出了一个坑。", "explanation": "这里应该用〈砸〉。勒是缠紧压住，不能表示砸击形成坑。"}, {"text": "他勒了一幅画，很好看。", "explanation": "这里应该用〈画〉。勒不表示绘画，应说“画了一幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衬衫的领口勒了我脖子疼。", "corrected_sentence": "这件衬衫的领口勒得我脖子疼。", "error_description": "补语错误：“勒”后引出状态要用“得”，“勒了”不能带状态补语，应说“勒得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的领带勒了着脖子，很难受。", "corrected_sentence": "他的领带勒着脖子，很难受。", "error_description": "体标错误：“勒着”表示持续状态，“了”与“着”不能并用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
