INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用绳子等套住物体用力拉紧。", "primary_collocate": null, "pronunciation": "lēi", "ipa": "leɪ˥", "syllable_count": 1, "sentences": [{"text": "他用绳子把箱子勒紧了。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这根带子勒紧一点。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把草捆勒得很紧。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用铁丝勒住木头。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用力勒了一下行李上的绳子。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把绳子勒得太紧，手腕很疼。", "target_word": "勒", "complexity_tier": "T3", "furigana": "tā bǎ shéngzi lēi de tài jǐn, shǒuwàn hěn téng.", "sentence_source": "generated"}, {"text": "司机用绳子勒住车上的东西。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用绳子把纸箱勒紧了，怕它散开。", "target_word": "勒", "complexity_tier": "T3", "furigana": "māma yòng shéngzi bǎ zhǐxiāng lēijǐn le, pà tā sànkāi.", "sentence_source": "generated"}, {"text": "小心，别把包上的带子勒得太紧。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力勒着绳子，不让箱子掉下来。", "target_word": "勒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勒紧", "label": "复合"}, {"form": "勒住", "label": "复合"}, {"form": "勒了", "label": "体标"}, {"form": "勒着", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：用绳子、带子套住东西并用力拉紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '239c4ca9-a8a6-4a41-8dd0-af48221448b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勒", "is_correct": true, "explanation": "lēi（第一声）意思是用绳子等套住物体用力拉紧。"}, {"text": "累", "is_correct": false, "explanation": "lèi（第四声）与 lēi（第一声）声调不同，意思是劳累。"}, {"text": "雷", "is_correct": false, "explanation": "léi（第二声）与 lēi（第一声）声调不同，意思是雷电。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 lēi（第一声）声调不同，意思是堆砌、垒起。"}], "explanations": {"勒": "lēi（第一声）意思是用绳子等套住物体用力拉紧。", "累": "lèi（第四声）与 lēi（第一声）声调不同，意思是劳累。", "雷": "léi（第二声）与 lēi（第一声）声调不同，意思是雷电。", "垒": "lěi（第三声）与 lēi（第一声）声调不同，意思是堆砌、垒起。"}, "sentence_index": null, "correct_answer": "勒"}, "level_3": {"options": [{"text": "勒", "is_correct": true, "explanation": "“勒紧”指用绳子套住箱子并拉紧，与“用绳子”和“紧了”的语境吻合。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是割开，不能把箱子切紧。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与绳子、箱子无关，不能把箱子唱紧。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“箱子”作宾语，不能说“把箱子跑紧”。"}], "explanations": {"勒": "“勒紧”指用绳子套住箱子并拉紧，与“用绳子”和“紧了”的语境吻合。", "切": "语义：“切”是割开，不能把箱子切紧。", "唱": "语义：“唱”与绳子、箱子无关，不能把箱子唱紧。", "跑": "配价：“跑”是不及物动词，不能带“箱子”作宾语，不能说“把箱子跑紧”。"}, "sentence_index": 0, "correct_answer": "勒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用刀勒菜。", "explanation": "这里应该用〈切〉。勒指用绳子等套住拉紧，不能用来切割。"}, {"text": "工人把木头勒了一个洞。", "explanation": "这里应该用〈钻〉。勒指用绳子套住拉紧，不能用来在木头上打洞。"}, {"text": "他用手勒住了木头。", "explanation": "这里应该用〈按〉。勒需要借助绳子、带子等套住物体，不能用手勒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勒", "is_correct": true, "explanation": "“勒住东西”指用绳子套住并拉紧，与“用绳子”和“住”的结果义吻合。"}, {"text": "梳", "is_correct": false, "explanation": "语义：“梳”是梳理头发的动作，不能用绳子捆住东西。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“东西”作宾语，不能说“笑住东西”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是使物体落下，与用绳子固定东西的动作不合。"}], "explanations": {"勒": "“勒住东西”指用绳子套住并拉紧，与“用绳子”和“住”的结果义吻合。", "梳": "语义：“梳”是梳理头发的动作，不能用绳子捆住东西。", "笑": "配价：“笑”是不及物动词，不能带“东西”作宾语，不能说“笑住东西”。", "摔": "语义：“摔”是使物体落下，与用绳子固定东西的动作不合。"}, "sentence_index": 6, "correct_answer": "勒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力勒着笑声，不让它传出来。", "explanation": "这里应该用〈憋〉。勒指用绳子等缠紧，不能用来形容笑声，应说“憋着笑声”。"}, {"text": "他勒了一封长信。", "explanation": "这里应该用〈写〉。勒不表示书写，应说“写了一封长信”。"}, {"text": "他把花勒在瓶子里。", "explanation": "这里应该用〈插〉。勒指用绳子套住拉紧，不能表示把花插进瓶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用皮带把行李勒了紧。", "corrected_sentence": "他用皮带把行李勒紧了。", "error_description": "复合词错误：“勒紧”是复合动词，“了”应放在整个复合词之后，不能插在“勒”和“紧”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用绳子把纸箱勒紧着，怕它散开。", "corrected_sentence": "妈妈用绳子把纸箱勒紧了，怕它散开。", "error_description": "体标错误：“勒紧”是动结式，表示动作已有结果，后面应该用“了”，不能用表示持续的“着”，应说“把纸箱勒紧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
