INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "即使如此，结果也不会改变，表示假设让步。", "primary_collocate": null, "pronunciation": "jí huò", "ipa": "tɕi˧˥ xuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "即或明天下雨，比赛也要照常举行。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或再难，我们也不会放弃。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或你不同意，我也会这样做。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或路很远，他也每天走着去学校。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或失败了，我们也学到了很多。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或天气很冷，孩子们也玩得很高兴。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或没有钱，他也愿意帮助别人。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或再忙，她也会抽时间看望父母。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或有人反对，这个计划也要做下去。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或到了晚上，街上也还有很多人。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "即或……也……，假设让步，结果不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：即或，表示假设让步，即使如此结果也不变。"}, {"text": "激活", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，huó（第二声）与 huò（第四声）声调也不同，“激活”意思是使事物重新有活力。"}, {"text": "集会", "is_correct": false, "explanation": "“集”与“即”读音相同，但第二音节 huì 与 huò 韵母不同，“集会”意思是人们聚在一起开会。"}, {"text": "急火", "is_correct": false, "explanation": "“急”与“即”读音相同，第二音节 huǒ（第三声）与 huò（第四声）声调不同，“急火”意思是心里着急、火气大。"}, {"text": "几何", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，hé 与 huò 韵母、声调都不同，“几何”指研究图形的数学分科。"}], "explanations": {"即或": "正确：即或，表示假设让步，即使如此结果也不变。", "激活": "jī（第一声）与 jí（第二声）声调不同，huó（第二声）与 huò（第四声）声调也不同，“激活”意思是使事物重新有活力。", "集会": "“集”与“即”读音相同，但第二音节 huì 与 huò 韵母不同，“集会”意思是人们聚在一起开会。", "急火": "“急”与“即”读音相同，第二音节 huǒ（第三声）与 huò（第四声）声调不同，“急火”意思是心里着急、火气大。", "几何": "jǐ（第三声）与 jí（第二声）声调不同，hé 与 huò 韵母、声调都不同，“几何”指研究图形的数学分科。"}, "sentence_index": null, "correct_answer": "即或"}, "level_3": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：“即或”表示假设让步，后句用“也”呼应，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“明天下雨”不能作为“比赛照常举行”的原因，句子逻辑不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，句首没有前因，且与“也要照常举行”的让步语义冲突。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接已经发生的事，不能用于句首引出将来的假设。"}], "explanations": {"即或": "正确：“即或”表示假设让步，后句用“也”呼应，符合句意。", "因为": "语义：“因为”表示原因，“明天下雨”不能作为“比赛照常举行”的原因，句子逻辑不通。", "所以": "语义：“所以”表示结果，句首没有前因，且与“也要照常举行”的让步语义冲突。", "于是": "搭配：“于是”承接已经发生的事，不能用于句首引出将来的假设。"}, "sentence_index": 0, "correct_answer": "即或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "即或努力，才能进步。", "explanation": "这里应该用〈只有〉。“即或”表示让步，不表示唯一的必要条件，后面也不能接“才”。"}, {"text": "即或明天下雨，我们就取消比赛。", "explanation": "这里应该用〈如果〉。“即或”强调条件变化后结果也不变，不能和“就取消比赛”这种条件结果搭配。"}, {"text": "即或他病了，所以没来。", "explanation": "这里应该用〈因为〉。“即或”只表示让步，不能说明原因，后面也不能接“所以”引出的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：“即或”引出假设让步，“没有钱”是让步条件，后句用“也”呼应。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，没有钱不能导致“也愿意帮助别人”。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”需承接前文的转折，单独放在句首，前后逻辑不通。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”用于补充理由，“没有钱”无法引出让步的结论。"}], "explanations": {"即或": "正确：“即或”引出假设让步，“没有钱”是让步条件，后句用“也”呼应。", "因此": "语义：“因此”表示结果，没有钱不能导致“也愿意帮助别人”。", "然而": "搭配：“然而”需承接前文的转折，单独放在句首，前后逻辑不通。", "况且": "语义：“况且”用于补充理由，“没有钱”无法引出让步的结论。"}, "sentence_index": 6, "correct_answer": "即或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "即或你已经决定了，我们就支持你。", "explanation": "这里应该用〈既然〉。“既然”表示已成事实的前提，“即或”表示假设让步，不能用于已经确定的事情。"}, {"text": "这本书很好看，即或很便宜。", "explanation": "这里应该用〈而且〉，表示并列补充。“即或”表示让步，后面要用“也”呼应，不能表示递进补充。"}, {"text": "下雨了，即或我们取消了比赛。", "explanation": "这里应该用〈所以〉。“即或”表示让步，不能引出“因此就怎样”的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即或天气不好，所以我们也会按时出发。", "corrected_sentence": "即或天气不好，我们也会按时出发。", "error_description": "错误：“即或”表示让步，“所以”表示结果，二者搭配矛盾。正确应为“即或天气不好，我们也会按时出发。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即或工作再忙，所以他会每天锻炼身体。", "corrected_sentence": "即或工作再忙，他也会每天锻炼身体。", "error_description": "错误：“即或”表示让步，“所以”表示结果，二者搭配矛盾。正确应为“即或工作再忙，他也会每天锻炼身体。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "即使；就算。多用于书面语。", "primary_collocate": null, "pronunciation": "jí huò", "ipa": "tɕi˧˥ xuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "即或身体不好，他也坚持上班。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或是专家，也会有出错的时候。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或明天不能见面，我们也可以通电话。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或价格再低，这样的东西我也不买。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或过了很多年，我也不会忘记这件事。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或遇到困难，我们也要往前走。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或是冬天，这里的花也开得很好。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或你说得对，也不应该这样大声说话。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或再给我一次机会，我还是会选择这条路。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即或没人帮忙，他也能把事情做完。", "target_word": "即或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "即使、就算，多用于书面语的让步连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：即或，表示假设让步，即使如此结果也不变。"}, {"text": "激活", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，huó（第二声）与 huò（第四声）声调也不同，“激活”意思是使事物重新有活力。"}, {"text": "集会", "is_correct": false, "explanation": "“集”与“即”读音相同，但第二音节 huì 与 huò 韵母不同，“集会”意思是人们聚在一起开会。"}, {"text": "急火", "is_correct": false, "explanation": "“急”与“即”读音相同，第二音节 huǒ（第三声）与 huò（第四声）声调不同，“急火”意思是心里着急、火气大。"}, {"text": "几何", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，hé 与 huò 韵母、声调都不同，“几何”指研究图形的数学分科。"}], "explanations": {"即或": "正确：即或，表示假设让步，即使如此结果也不变。", "激活": "jī（第一声）与 jí（第二声）声调不同，huó（第二声）与 huò（第四声）声调也不同，“激活”意思是使事物重新有活力。", "集会": "“集”与“即”读音相同，但第二音节 huì 与 huò 韵母不同，“集会”意思是人们聚在一起开会。", "急火": "“急”与“即”读音相同，第二音节 huǒ（第三声）与 huò（第四声）声调不同，“急火”意思是心里着急、火气大。", "几何": "jǐ（第三声）与 jí（第二声）声调不同，hé 与 huò 韵母、声调都不同，“几何”指研究图形的数学分科。"}, "sentence_index": null, "correct_answer": "即或"}, "level_3": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：“即或”表示假设让步，“身体不好”是让步条件，后句用“也”呼应。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，身体不好不能导致“他也坚持上班”。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接已经发生的事，句首单用不能引出这样的让步关系。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”需承接前文的转折，单独放在句首，前后逻辑不通。"}], "explanations": {"即或": "正确：“即或”表示假设让步，“身体不好”是让步条件，后句用“也”呼应。", "因此": "语义：“因此”表示结果，身体不好不能导致“他也坚持上班”。", "于是": "搭配：“于是”承接已经发生的事，句首单用不能引出这样的让步关系。", "然而": "搭配：“然而”需承接前文的转折，单独放在句首，前后逻辑不通。"}, "sentence_index": 0, "correct_answer": "即或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "即或天气好，我们就去公园。", "explanation": "这里应该用〈只要〉。“即或”表示让步，不表示充分条件，条件关系应用“只要……就……”。"}, {"text": "即或下雪，学校放假了。", "explanation": "这里应该用〈因为〉。“即或”表示让步，不表示原因，“学校放假”是下雪引起的结果。"}, {"text": "即或努力，才能进步。", "explanation": "这里应该用〈只有〉。“即或”表示让步，不表示唯一的必要条件；此句的“才”表示必要条件，应与“只有”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即或", "is_correct": true, "explanation": "正确：“即或”引出假设让步，“是冬天”是让步条件，后句用“也”呼应。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，冬天不能导致“花也开得很好”，句子逻辑不通。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“是冬天”不能说明“这里的花也开得很好”。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”需承接前面的理由，句首单用不能引出这样的让步句。"}], "explanations": {"即或": "正确：“即或”引出假设让步，“是冬天”是让步条件，后句用“也”呼应。", "所以": "语义：“所以”表示结果，冬天不能导致“花也开得很好”，句子逻辑不通。", "因为": "语义：“因为”表示原因，“是冬天”不能说明“这里的花也开得很好”。", "况且": "搭配：“况且”需承接前面的理由，句首单用不能引出这样的让步句。"}, "sentence_index": 6, "correct_answer": "即或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "即或你已经同意了，我们就出发吧。", "explanation": "这里应该用〈既然〉。“既然”表示已成事实的前提，“即或”表示假设让步，不能用于已经确定的事情。"}, {"text": "下雨了，即或我们取消了比赛。", "explanation": "这里应该用〈所以〉。“即或”表示让步，不能引出“因此就怎样”的结果。"}, {"text": "这个方法很简单，即或很便宜。", "explanation": "这里应该用〈而且〉，表示并列补充。“即或”表示让步，后面要用“也”呼应，不能表示递进补充。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即或天很热，所以我们也要坚持训练。", "corrected_sentence": "即或天很热，我们也要坚持训练。", "error_description": "错误：“即或”引出让步条件，后句不能再接表示结果的“所以”；去掉“所以”即正确：“即或天很热，我们也要坚持训练。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即或没有时间，因此他也会坚持读书。", "corrected_sentence": "即或没有时间，他也会坚持读书。", "error_description": "错误：“即或”表示让步，不能与表示结果的“因此”连用；去掉“因此”即正确：“即或没有时间，他也会坚持读书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
