INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94003, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "呼吸是把空气吸进身体里，再吹出来。", "primary_collocate": null, "pronunciation": "hū xī", "ipa": "xu⁵⁵ ɕi⁵⁵", "syllable_count": 2, "sentences": [{"text": "早上到公园呼吸新鲜空气。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，呼吸一下外面的空气。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛，深深地呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边呼吸着海风。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紧张的时候，先呼吸三次。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在雪地里，呼吸着冷空气。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太闷，我快不能呼吸了。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用鼻子呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的空气好，我呼吸得很舒服。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天早上练习呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吸了", "label": "体标"}, {"form": "呼吸着", "label": "体标"}, {"form": "呼吸过", "label": "体标"}, {"form": "呼吸道", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常有意识地吸气和吐气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "正确：“呼吸新鲜空气”是常用搭配，指吸入清新的空气。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是水、饮料等液体，不说饮用新鲜空气。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”是把食物嚼碎，与公园和空气无关，句子不通。"}, {"text": "呼气", "is_correct": false, "explanation": "配价：“呼气”是不及物动词，不能直接带“新鲜空气”作宾语。"}], "explanations": {"呼吸": "正确：“呼吸新鲜空气”是常用搭配，指吸入清新的空气。", "饮用": "搭配：“饮用”的对象是水、饮料等液体，不说饮用新鲜空气。", "咀嚼": "语义：“咀嚼”是把食物嚼碎，与公园和空气无关，句子不通。", "呼气": "配价：“呼气”是不及物动词，不能直接带“新鲜空气”作宾语。"}, "sentence_index": 0, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山谷里大声呼吸朋友的名字。", "explanation": "这里应该用〈呼唤〉。“呼吸”不能带人名作宾语表示喊人，叫人要用“呼唤”。"}, {"text": "他渴坏了，一口气呼吸了一大杯水。", "explanation": "这里应该用〈喝〉。“呼吸”指吸入和呼出空气，不能用来喝水，喝水要用“喝”。"}, {"text": "他把那封信呼吸了一遍。", "explanation": "这里应该用〈读〉。“呼吸”指吸入和呼出空气，不能表示阅读，读信要用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "正确：“房间太闷，我快不能呼吸了”符合语境，指空气不足、透不过气。"}, {"text": "想念", "is_correct": false, "explanation": "语义：“想念”表示思念某人，与“房间太闷”的情境无关，句子不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“房间太闷”无关，句子表达的是没法呼吸，不是没法吃饭。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指装饰房屋，与“快不能……了”的意思无关，句子不通。"}], "explanations": {"呼吸": "正确：“房间太闷，我快不能呼吸了”符合语境，指空气不足、透不过气。", "想念": "语义：“想念”表示思念某人，与“房间太闷”的情境无关，句子不通。", "吃饭": "语义：“吃饭”与“房间太闷”无关，句子表达的是没法呼吸，不是没法吃饭。", "装修": "语义：“装修”指装饰房屋，与“快不能……了”的意思无关，句子不通。"}, "sentence_index": 6, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "叔叔每天呼吸一包，咳嗽越来越厉害。", "explanation": "这里应该用〈吸烟〉。“呼吸”不能用“一包”计量，烟要说“吸烟”。"}, {"text": "他在河边大声呼吸救命。", "explanation": "这里应该用〈呼喊〉。“呼吸”不能用来求救，大声求救要用“呼喊”。"}, {"text": "他在台上认真地呼吸了一首歌。", "explanation": "这里应该用〈唱〉。“呼吸”指吸入和呼出空气，不能用来表示唱歌，唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们出去呼吸一个新鲜空气吧。", "corrected_sentence": "我们出去呼吸一下新鲜空气吧。", "error_description": "量词误用：动词“呼吸”后表示短暂动作要用动量词“一下”，不能用“一个”。应说“呼吸一下”，不说“呼吸一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们慢慢地把鼻子呼吸。", "corrected_sentence": "老师让我们慢慢地用鼻子呼吸。", "error_description": "介词误用：表示“用什么”应用“用”，不用“把”。应说“慢慢地用鼻子呼吸”，不说“慢慢地把鼻子呼吸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
