INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把空气吸入体内再排出体外。", "primary_collocate": null, "pronunciation": "hū xī", "ipa": "xu⁵⁵ ɕi⁵⁵", "syllable_count": 2, "sentences": [{"text": "人每天都要呼吸空气。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里也能呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人呼吸很慢，医生很担心。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑完步，呼吸变得很快。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你慢慢呼吸，不要紧张。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经能自己呼吸了。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上空气少，呼吸有点难。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉时，他的呼吸很轻。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的时候要学会呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里没有空气，人不能呼吸。", "target_word": "呼吸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吸了", "label": "体标"}, {"form": "呼吸着", "label": "体标"}, {"form": "呼吸过", "label": "体标"}], "register": "中性", "sense_fingerprint": "生物吸入空气并排出的生理活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "正确：“呼吸空气”是常用搭配，指吸入和呼出空气。"}, {"text": "呼气", "is_correct": false, "explanation": "配价：“呼气”是不及物动词，不能直接带“空气”作宾语，句子不通。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”是把食物嚼碎，与“空气”无关，句子不通。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是水、饮料等液体，不说饮用空气。"}], "explanations": {"呼吸": "正确：“呼吸空气”是常用搭配，指吸入和呼出空气。", "呼气": "配价：“呼气”是不及物动词，不能直接带“空气”作宾语，句子不通。", "咀嚼": "语义：“咀嚼”是把食物嚼碎，与“空气”无关，句子不通。", "饮用": "搭配：“饮用”的对象是水、饮料等液体，不说饮用空气。"}, "sentence_index": 0, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子在院子里大声呼吸妈妈。", "explanation": "这里应该用〈呼喊〉。“呼吸”指吸气和呼气，不能用来叫人，大声叫人要用“呼喊”。"}, {"text": "他饿坏了，很快呼吸了一碗饭。", "explanation": "这里应该用〈吃〉。“呼吸”指把空气吸入体内再排出，不能用来吃饭，吃东西要用“吃”。"}, {"text": "医生让病人呼吸药剂，每天三次。", "explanation": "这里应该用〈吸入〉。“呼吸”不能带“药剂”作宾语，吸入药剂要用“吸入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "正确：“山上空气少，呼吸有点难”符合语境，指高处吸入空气困难。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰外表，与“空气少”无关，句子不通。"}, {"text": "赌博", "is_correct": false, "explanation": "语义：“赌博”与“空气少”毫无关系，句子不通。"}, {"text": "想念", "is_correct": false, "explanation": "语义：“想念”表示思念某人，与高山缺氧的情境无关，句子不通。"}], "explanations": {"呼吸": "正确：“山上空气少，呼吸有点难”符合语境，指高处吸入空气困难。", "打扮": "语义：“打扮”指修饰外表，与“空气少”无关，句子不通。", "赌博": "语义：“赌博”与“空气少”毫无关系，句子不通。", "想念": "语义：“想念”表示思念某人，与高山缺氧的情境无关，句子不通。"}, "sentence_index": 6, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他累坏了，呼吸了一个好觉。", "explanation": "这里应该用〈睡〉。“呼吸”只指吸气和呼气，不能表示睡觉，睡一个好觉要用“睡”。"}, {"text": "他站在路边大声呼吸朋友。", "explanation": "这里应该用〈呼唤〉。“呼吸”不能用来叫人，叫朋友要用“呼唤”。"}, {"text": "爸爸一天呼吸两包，妈妈很担心。", "explanation": "这里应该用〈吸烟〉。“呼吸”不能用“两包”计量，烟要说“吸烟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他爬完楼梯，呼吸的很厉害。", "corrected_sentence": "他爬完楼梯，呼吸得很厉害。", "error_description": "“呼吸”后面表示程度的补语要用“得”，不用“的”。应说“呼吸得很厉害”，不说“呼吸的很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爬到山顶，呼吸一个新鲜空气。", "corrected_sentence": "他爬到山顶，呼吸一下新鲜空气。", "error_description": "量词误用：“呼吸”后面不能用“一个”计量空气，应说“呼吸一下新鲜空气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
