INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94005, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "咬是用牙齿夹住东西。", "primary_collocate": null, "pronunciation": "yǎo", "ipa": "jɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "小狗咬着一个球跑过来了。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴里咬着一支笔，在想问题。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫咬住了老鼠的尾巴。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用嘴咬着线头，把衣服缝好。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩咬着手指头，看着窗外。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟咬着一条小虫飞回了家。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗咬住我的裤子，不让我走。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咬着面包，急急忙忙跑出门。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫咬着妈妈的耳朵玩。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的鱼咬住了钩子。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咬了", "label": "完成体"}, {"form": "咬着", "label": "持续体"}, {"form": "咬过", "label": "经历体"}, {"form": "咬住", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用牙或嘴夹住、叼住东西不放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1cb6519-50d5-4b10-bf39-77cfccca4eff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。咬 yǎo 表示用牙或嘴夹住、叼住东西。"}, {"text": "摇", "is_correct": false, "explanation": "yáo（第二声）与 yǎo（第三声）声调不同，意思是“摇动”。"}, {"text": "好", "is_correct": false, "explanation": "h 与 y 声母不同，声调相同，意思是“好”。"}, {"text": "老", "is_correct": false, "explanation": "l 与 y 声母不同，声调相同，意思是“老”。"}, {"text": "考", "is_correct": false, "explanation": "k 与 y 声母不同，声调相同，意思是“考试”。"}], "explanations": {"咬": "正确答案。咬 yǎo 表示用牙或嘴夹住、叼住东西。", "摇": "yáo（第二声）与 yǎo（第三声）声调不同，意思是“摇动”。", "好": "h 与 y 声母不同，声调相同，意思是“好”。", "老": "l 与 y 声母不同，声调相同，意思是“老”。", "考": "k 与 y 声母不同，声调相同，意思是“考试”。"}, "sentence_index": null, "correct_answer": "咬"}, "level_3": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。“咬着一个球”表示用嘴叼着球，符合句意。"}, {"text": "握", "is_correct": false, "explanation": "语义：握需要用手，小狗没有手，“握着一个球”与语境不符。"}, {"text": "提", "is_correct": false, "explanation": "语义：提需要用手提起，与小狗用嘴叼球的动作不符。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔着”表示抛出，不能表示持续地叼着，与“跑过来”搭配不当。"}], "explanations": {"咬": "正确答案。“咬着一个球”表示用嘴叼着球，符合句意。", "握": "语义：握需要用手，小狗没有手，“握着一个球”与语境不符。", "提": "语义：提需要用手提起，与小狗用嘴叼球的动作不符。", "扔": "搭配：“扔着”表示抛出，不能表示持续地叼着，与“跑过来”搭配不当。"}, "sentence_index": 0, "correct_answer": "咬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他咬着一篮子鸡蛋，慢慢走进了村子。", "explanation": "这里应该用〈提〉。篮子要用手提，用嘴咬着一篮子东西不合常理。"}, {"text": "他咬着手机，一边走一边打电话。", "explanation": "这里应该用〈拿〉。手机要用手拿着打电话，用嘴咬着无法通话。"}, {"text": "她咬着一个大西瓜跑了。", "explanation": "这里应该用〈抱〉。西瓜太大，用嘴咬着拿不起来，“咬着”只适合叼起较小的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94005, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。咬 yǎo 表示用牙或嘴夹住、叼住东西。"}, {"text": "早", "is_correct": false, "explanation": "z 与 y 声母不同，声调相同，意思是“早上”。"}, {"text": "草", "is_correct": false, "explanation": "c 与 y 声母不同，声调相同，意思是“草”。"}, {"text": "饱", "is_correct": false, "explanation": "b 与 y 声母不同，声调相同，意思是“吃饱”。"}, {"text": "跑", "is_correct": false, "explanation": "p 与 y 声母不同，声调相同，意思是“跑步”。"}], "explanations": {"咬": "正确答案。咬 yǎo 表示用牙或嘴夹住、叼住东西。", "早": "z 与 y 声母不同，声调相同，意思是“早上”。", "草": "c 与 y 声母不同，声调相同，意思是“草”。", "饱": "b 与 y 声母不同，声调相同，意思是“吃饱”。", "跑": "p 与 y 声母不同，声调相同，意思是“跑步”。"}, "sentence_index": null, "correct_answer": "咬"}, "level_3": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。“咬住我的裤子”表示用嘴咬住裤子不放，符合句意。"}, {"text": "捏", "is_correct": false, "explanation": "语义：捏需要用手指，狗没有手指，与“咬住”的动作不符。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇住”不是常见搭配，“摇”指摆动，与“裤子”后接“住”搭配不当。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”多指用脚踢，“踢住”搭配不当，与用嘴固定裤子的意思不符。"}], "explanations": {"咬": "正确答案。“咬住我的裤子”表示用嘴咬住裤子不放，符合句意。", "捏": "语义：捏需要用手指，狗没有手指，与“咬住”的动作不符。", "摇": "搭配：“摇住”不是常见搭配，“摇”指摆动，与“裤子”后接“住”搭配不当。", "踢": "搭配：“踢”多指用脚踢，“踢住”搭配不当，与用嘴固定裤子的意思不符。"}, "sentence_index": 6, "correct_answer": "咬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咬了一下门，门就开了。", "explanation": "这里应该用〈推〉。“咬”表示用牙齿夹住东西，推门应说“推”，不能说“咬”。"}, {"text": "她咬着一个大箱子，慢慢走进了车站。", "explanation": "这里应该用〈提〉。箱子太大太重，用嘴咬着拿不起来，应该用手提。"}, {"text": "他咬着一本书，在教室里大声朗读。", "explanation": "这里应该用〈拿〉。书要用手拿，用嘴咬着无法大声朗读，“咬着”只适用于叼起较小的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他咬了着一颗糖，慢慢走回家。", "corrected_sentence": "他咬着一颗糖，慢慢走回家。", "error_description": "错误形式“咬了着”，正确形式“咬着”。持续体“着”紧跟动词，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他咬了住面包，不肯松口。", "corrected_sentence": "他咬住了面包，不肯松口。", "error_description": "错误形式“咬了住”，正确形式“咬住了”。结果补语“住”必须紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c0e686-d042-4010-b3c3-f309e153e57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
