INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94011, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大力是用很大的力气，非常用心地去做。", "primary_collocate": null, "pronunciation": "dà lì", "ipa": "ta˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "政府大力支持小公司。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要大力发展经济。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校大力推广读书活动。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市长说，要大力保护环境。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年，这个城市大力发展了旅游。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师大力鼓励同学们多读书。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司大力培养年轻人，所以大家都很努力。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让更多人知道，他们大力宣传这个活动。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院大力引进新设备，帮助了很多病人。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大家大力支持，这次活动办得很成功。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "副词：全力、用心地推动某事（大力支持、大力发展）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94011, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力（dà lì）指用很大的努力、全力去推动或支持，与题目要求一致。"}, {"text": "大礼", "is_correct": false, "explanation": "大礼（dàlǐ）与大力的第二个音节声调不同（礼为第三声，力为第四声），意思是隆重的礼仪。"}, {"text": "打理", "is_correct": false, "explanation": "打理（dǎlǐ）两个音节的声调都与大力不同，意思是料理、管理。"}, {"text": "搭理", "is_correct": false, "explanation": "搭理（dālǐ）两个音节的声调都与大力不同，意思是理会、答理。"}], "explanations": {"大力": "大力（dà lì）指用很大的努力、全力去推动或支持，与题目要求一致。", "大礼": "大礼（dàlǐ）与大力的第二个音节声调不同（礼为第三声，力为第四声），意思是隆重的礼仪。", "打理": "打理（dǎlǐ）两个音节的声调都与大力不同，意思是料理、管理。", "搭理": "搭理（dālǐ）两个音节的声调都与大力不同，意思是理会、答理。"}, "sentence_index": null, "correct_answer": "大力"}, "level_3": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力修饰“支持”，表示用很大的力量全力支持，与句意相符。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”指胡乱、无章法，与“大力支持”的积极含义相反。"}, {"text": "狠狠", "is_correct": false, "explanation": "语义：“狠狠”含有猛击、狠打的意思，与“支持”不搭。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突然，不表示持续的支持。"}], "explanations": {"大力": "大力修饰“支持”，表示用很大的力量全力支持，与句意相符。", "乱": "语义：“乱”指胡乱、无章法，与“大力支持”的积极含义相反。", "狠狠": "语义：“狠狠”含有猛击、狠打的意思，与“支持”不搭。", "猛然": "语义：“猛然”表示突然，不表示持续的支持。"}, "sentence_index": 0, "correct_answer": "大力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大力喜欢这本书。", "explanation": "这里应该用〈非常〉。大力只修饰有力度的动作，不能修饰“喜欢”这类心理动词。"}, {"text": "他大力迟到了。", "explanation": "这里应该用〈严重〉。大力表示用很大力气或非常用心地去做，不能修饰“迟到”这种结果；“严重迟到”要用严重。"}, {"text": "他大力知道了这个答案。", "explanation": "这里应该用〈早就〉。大力修饰用力去做的动作，不修饰“知道”这类认知状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94011, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力（dà lì）指用很大的努力、全力去推动或支持，与题目要求一致。"}, {"text": "打理", "is_correct": false, "explanation": "打理（dǎlǐ）与大力（dà lì）声母韵母相同，只有声调不同，属于声调混淆；意思是料理、管理。"}, {"text": "答理", "is_correct": false, "explanation": "答理（dālǐ）两个音节的声调都与大力不同，意思是搭理、回应。"}, {"text": "大理", "is_correct": false, "explanation": "大理（dàlǐ）是云南的地名，第二个音节声调与大力不同（理为第三声）。"}], "explanations": {"大力": "大力（dà lì）指用很大的努力、全力去推动或支持，与题目要求一致。", "打理": "打理（dǎlǐ）与大力（dà lì）声母韵母相同，只有声调不同，属于声调混淆；意思是料理、管理。", "答理": "答理（dālǐ）两个音节的声调都与大力不同，意思是搭理、回应。", "大理": "大理（dàlǐ）是云南的地名，第二个音节声调与大力不同（理为第三声）。"}, "sentence_index": null, "correct_answer": "大力"}, "level_3": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力修饰“培养”，表示用很大的力量全力培养，与“大家都很努力”的结果相符。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示随意、不认真，与“大家都很努力”的结果不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“培养”的持续性及后面的结果不合。"}, {"text": "草草", "is_correct": false, "explanation": "搭配：“草草”指马虎、敷衍，不说“草草培养年轻人”。"}], "explanations": {"大力": "大力修饰“培养”，表示用很大的力量全力培养，与“大家都很努力”的结果相符。", "随便": "语义：“随便”表示随意、不认真，与“大家都很努力”的结果不合。", "偶尔": "语义：“偶尔”表示不经常，与“培养”的持续性及后面的结果不合。", "草草": "搭配：“草草”指马虎、敷衍，不说“草草培养年轻人”。"}, "sentence_index": 6, "correct_answer": "大力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一本大力的书。", "explanation": "这里应该用〈好〉。大力是用很大力气做动作的副词，不能用来描述书的好坏；评价书要用好。"}, {"text": "他是大力的人。", "explanation": "这里应该用〈力气大〉。大力是修饰动作的副词，不能作“的”字定语描述人。"}, {"text": "我大力相信这个故事。", "explanation": "这里应该用〈深信〉。大力修饰有力度的动作，不修饰“相信”这类心理动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很大力发展农业。", "corrected_sentence": "我们大力发展农业。", "error_description": "错误：副词“大力”前面不能加“很”。“大力”本身已表示用很大的力气，不能再用“很”修饰。正确说法是“大力发展农业”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们大力的帮助了贫困的学生。", "corrected_sentence": "他们大力帮助了贫困的学生。", "error_description": "错误：状语标记应写“地”而不是“的”。正确说法是“大力帮助了”或“大力地帮助了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
