INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94012, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用很大的力量；花很大气力。", "primary_collocate": null, "pronunciation": "dà lì", "ipa": "ta˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他大力拍桌子。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请不要大力关门。", "target_word": "大力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟大力踢球，球飞出去很远。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们大力鼓掌，欢迎客人。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大力推了一下门，门就开了。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你大力拉一下这根绳子。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大力拍了拍我的肩。", "target_word": "大力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大力拧着瓶盖，可是还是打不开。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈大力擦着桌子，想把脏东西擦掉。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把球大力扔向远处，球落在了河里。", "target_word": "大力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：动作用很大的力气（大力推门、大力鼓掌）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力（dà lì）指用很大的力气去做动作，与题目要求一致。"}, {"text": "大礼", "is_correct": false, "explanation": "大礼（dàlǐ）与大力的第二个音节声调不同（礼为第三声），意思是隆重的礼仪。"}, {"text": "打理", "is_correct": false, "explanation": "打理（dǎlǐ）两个音节的声调都与大力不同，意思是料理、管理。"}, {"text": "答理", "is_correct": false, "explanation": "答理（dālǐ）两个音节的声调都与大力不同，意思是搭理、回应。"}], "explanations": {"大力": "大力（dà lì）指用很大的力气去做动作，与题目要求一致。", "大礼": "大礼（dàlǐ）与大力的第二个音节声调不同（礼为第三声），意思是隆重的礼仪。", "打理": "打理（dǎlǐ）两个音节的声调都与大力不同，意思是料理、管理。", "答理": "答理（dālǐ）两个音节的声调都与大力不同，意思是搭理、回应。"}, "sentence_index": null, "correct_answer": "大力"}, "level_3": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力修饰“拍”，表示用很大的力气拍，与句意相符。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”强调态度端正，不表示用力击打。"}, {"text": "仔细", "is_correct": false, "explanation": "搭配：“仔细”修饰细致的动作，不说“仔细拍桌子”。"}, {"text": "悠闲", "is_correct": false, "explanation": "语义：“悠闲”表示从容自在，与用力拍击不合。"}], "explanations": {"大力": "大力修饰“拍”，表示用很大的力气拍，与句意相符。", "认真": "语义：“认真”强调态度端正，不表示用力击打。", "仔细": "搭配：“仔细”修饰细致的动作，不说“仔细拍桌子”。", "悠闲": "语义：“悠闲”表示从容自在，与用力拍击不合。"}, "sentence_index": 0, "correct_answer": "大力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大力地微笑着看着我。", "explanation": "这里应该用〈灿烂〉。大力表示用很大力气做动作，不能修饰“微笑”这种表情。"}, {"text": "他大力想念远方的家人。", "explanation": "这里应该用〈深切〉。大力修饰用力去做的动作，不修饰“想念”这类心理动词。"}, {"text": "我大力喜欢这首歌。", "explanation": "这里应该用〈非常〉。大力修饰有力度的动作，不修饰“喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94012, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力（dà lì）指用很大的力气去做动作，与题目要求一致。"}, {"text": "打理", "is_correct": false, "explanation": "打理（dǎlǐ）与大力（dà lì）声母韵母相同，只有声调不同，属于声调混淆；意思是料理、管理。"}, {"text": "搭理", "is_correct": false, "explanation": "搭理（dālǐ）两个音节的声调都与大力不同，意思是理会、答理。"}, {"text": "大理", "is_correct": false, "explanation": "大理（dàlǐ）是云南的地名，第二个音节声调与大力不同（理为第三声）。"}], "explanations": {"大力": "大力（dà lì）指用很大的力气去做动作，与题目要求一致。", "打理": "打理（dǎlǐ）与大力（dà lì）声母韵母相同，只有声调不同，属于声调混淆；意思是料理、管理。", "搭理": "搭理（dālǐ）两个音节的声调都与大力不同，意思是理会、答理。", "大理": "大理（dàlǐ）是云南的地名，第二个音节声调与大力不同（理为第三声）。"}, "sentence_index": null, "correct_answer": "大力"}, "level_3": {"options": [{"text": "大力", "is_correct": true, "explanation": "大力修饰“拍了拍”，表示用较大的力气拍，与句意相符。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说、叫等发声动作，不修饰拍肩。"}, {"text": "轻声", "is_correct": false, "explanation": "搭配：“轻声”修饰说话，不修饰拍肩。"}, {"text": "高声", "is_correct": false, "explanation": "搭配：“高声”修饰发声动作，不修饰拍肩。"}], "explanations": {"大力": "大力修饰“拍了拍”，表示用较大的力气拍，与句意相符。", "大声": "搭配：“大声”修饰说、叫等发声动作，不修饰拍肩。", "轻声": "搭配：“轻声”修饰说话，不修饰拍肩。", "高声": "搭配：“高声”修饰发声动作，不修饰拍肩。"}, "sentence_index": 6, "correct_answer": "大力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一个大力的球。", "explanation": "这里应该用〈有力〉。大力是用很大力气去做动作的副词，不能用来描述球本身；形容球的力量要用有力。"}, {"text": "他大力忘记了这件事。", "explanation": "这里应该用〈彻底〉。大力修饰用力气或用心去做的动作，不修饰“忘记”这种状态；忘得干净要用彻底。"}, {"text": "他大力知道了远处有河。", "explanation": "这里应该用〈清楚〉。大力修饰用力去做的动作，不修饰“知道”这类认知状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 