INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94013, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太太是已经结婚的女人，别人这样叫她。", "primary_collocate": null, "pronunciation": "tài tai", "ipa": "tʰaɪ˥˩ tʰaɪ", "syllable_count": 2, "sentences": [{"text": "王太太住在我们楼上。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位太太正在给花浇水。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张太太今天穿了一件红衣服。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的太太每天早上都跑步。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有一位太太在买菜。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈太太请我们去她家吃饭。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您是林太太吗？", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位太太坐在公园的长椅上聊天。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刘太太已经结婚十年了。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位太太，您的包忘在车上了。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太太们", "label": "复数"}, {"form": "位", "label": "量词"}, {"form": "老太太", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：对别人家已婚女子的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '239c4ca9-a8a6-4a41-8dd0-af48221448b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太太", "is_correct": true, "explanation": "“王太太”是对王姓已婚女子的称呼，“王”作姓氏，与“太太”搭配。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能“住在楼上”，也不能作为姓氏后的称呼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能与姓氏“王”组成称呼，也不会居住。"}, {"text": "人", "is_correct": false, "explanation": "搭配：姓氏后面要接称谓，“王人”不成称呼，应说“王太太”。"}], "explanations": {"太太": "“王太太”是对王姓已婚女子的称呼，“王”作姓氏，与“太太”搭配。", "窗户": "语义：窗户是物件，不能“住在楼上”，也不能作为姓氏后的称呼。", "桌子": "语义：桌子不是人，不能与姓氏“王”组成称呼，也不会居住。", "人": "搭配：姓氏后面要接称谓，“王人”不成称呼，应说“王太太”。"}, "sentence_index": 0, "correct_answer": "太太"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位太太还在上高中，常来图书馆学习。", "explanation": "这里应该用〈女生〉。太太只称已婚女子，上高中的学生未婚，应称〈女生〉。"}, {"text": "我的同学还没结婚，我们都叫她王太太。", "explanation": "这里应该用〈小姐〉。太太只称已婚女子，未婚女子应称〈小姐〉。"}, {"text": "对面来了三只太太，每天早上都跑步。", "explanation": "这里应该用〈位〉。太太指人，量词要用〈位〉，“只”用于动物或物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太太", "is_correct": true, "explanation": "“林太太”是对林姓已婚女子的称呼，符合“请问，您是林……吗”的礼貌询问。"}, {"text": "老娘", "is_correct": false, "explanation": "语域：“老娘”是粗俗口语，向陌生人问身份时很失礼，不能用于礼貌询问。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：大衣是衣服，不能作为对人的称呼或用来问对方的身份。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是材料，不是人，不能用“您是林……吗”来问对方。"}], "explanations": {"太太": "“林太太”是对林姓已婚女子的称呼，符合“请问，您是林……吗”的礼貌询问。", "老娘": "语域：“老娘”是粗俗口语，向陌生人问身份时很失礼，不能用于礼貌询问。", "大衣": "语义：大衣是衣服，不能作为对人的称呼或用来问对方的身份。", "木头": "语义：木头是材料，不是人，不能用“您是林……吗”来问对方。"}, "sentence_index": 6, "correct_answer": "太太"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楼下那位太太今年五岁了。", "explanation": "这里应该用〈小姑娘〉。太太指成年已婚女子，不能用来称呼五岁的小女孩。"}, {"text": "大家都亲切地喊她小丽太太。", "explanation": "这里应该用〈李太太〉这类“姓氏＋太太”的称呼。“太太”前只能加姓氏，不能加名字。"}, {"text": "那位太太是男的，在银行工作。", "explanation": "这里应该用〈先生〉。太太只用于女子，男子应称〈先生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只太太，她住在三楼。", "corrected_sentence": "我认识一位太太，她住在三楼。", "error_description": "量词错误：“太太”指人，应用量词“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "您是那只李太太吗？", "corrected_sentence": "您是那位李太太吗？", "error_description": "量词错误：“太太”指人，应用量词“位”，不能用“只”。“只”多用于动物或物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
