INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "奇迹是特别神奇、没人想到会发生的好事。", "primary_collocate": null, "pronunciation": "qí jì", "ipa": "tɕʰi˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛真是一个奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没想到会有奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病好了，医生说这是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赢了，大家都说这是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奇迹发生了，大家都哭了。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信生活里有奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小队创造了奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们还在等着奇迹出现。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子活下来，就是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨后，村子还在，这真是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个奇迹", "label": "量词"}, {"form": "奇蹟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奇迹：没人想到会发生的神奇好事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94015, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹（qí jì）：没人想到会发生的神奇好事，是这里要辨认的词。"}, {"text": "齐集", "is_correct": false, "explanation": "齐集（qí jí）与奇迹只有第二个音节声调不同（第二声 jí 与第四声 jì），意思是聚集到一起。"}, {"text": "齐聚", "is_correct": false, "explanation": "齐聚（qí jù）与奇迹只有第二个音节韵母不同（jù 与 jì），意思是齐齐地聚在一起。"}, {"text": "期冀", "is_correct": false, "explanation": "期冀（qī jì）与奇迹只有第一个音节声调不同（第一声 qī 与第二声 qí），意思是希望、盼望。"}], "explanations": {"奇迹": "奇迹（qí jì）：没人想到会发生的神奇好事，是这里要辨认的词。", "齐集": "齐集（qí jí）与奇迹只有第二个音节声调不同（第二声 jí 与第四声 jì），意思是聚集到一起。", "齐聚": "齐聚（qí jù）与奇迹只有第二个音节韵母不同（jù 与 jì），意思是齐齐地聚在一起。", "期冀": "期冀（qī jì）与奇迹只有第一个音节声调不同（第一声 qī 与第二声 qí），意思是希望、盼望。"}, "sentence_index": null, "correct_answer": "奇迹"}, "level_3": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹：没人想到会发生的神奇好事，可以用来评价这次比赛。"}, {"text": "天气", "is_correct": false, "explanation": "语义：比赛不是天气，“真是一个天气”无法用来评价这次比赛。"}, {"text": "石头", "is_correct": false, "explanation": "语义：比赛不是石头，不能这样比喻这次比赛。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”指日常餐食，“真是一个早饭”不能用来评价比赛。"}], "explanations": {"奇迹": "奇迹：没人想到会发生的神奇好事，可以用来评价这次比赛。", "天气": "语义：比赛不是天气，“真是一个天气”无法用来评价这次比赛。", "石头": "语义：比赛不是石头，不能这样比喻这次比赛。", "早饭": "搭配：“早饭”指日常餐食，“真是一个早饭”不能用来评价比赛。"}, "sentence_index": 0, "correct_answer": "奇迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把奇迹装进了箱子里寄走了。", "explanation": "这里应该用〈礼物〉。奇迹是抽象的好事，不是能装进箱子寄走的实物；寄走的应是〈礼物〉这类实物。"}, {"text": "这次事故是一场奇迹，几百人都遇难了。", "explanation": "这里应该用〈悲剧〉。奇迹指特别神奇的好事，不能用来形容造成几百人遇难的事故。"}, {"text": "他得了一种很重的奇迹，需要住院治疗。", "explanation": "这里应该用〈疾病〉。奇迹指好事，不是病；“得了一种很重的”后面要接〈疾病〉这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94015, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹（qí jì）：没人想到会发生的神奇好事，是这里要辨认的词。"}, {"text": "骑士", "is_correct": false, "explanation": "骑士（qí shì）与奇迹只有第二个音节声母不同（sh 与 j），意思是中世纪的武士。"}, {"text": "旗帜", "is_correct": false, "explanation": "旗帜（qí zhì）与奇迹只有第二个音节声母不同（zh 与 j），意思是旗子。"}, {"text": "其次", "is_correct": false, "explanation": "其次（qí cì）与奇迹只有第二个音节声母不同（c 与 j），意思是次一等、然后。"}], "explanations": {"奇迹": "奇迹（qí jì）：没人想到会发生的神奇好事，是这里要辨认的词。", "骑士": "骑士（qí shì）与奇迹只有第二个音节声母不同（sh 与 j），意思是中世纪的武士。", "旗帜": "旗帜（qí zhì）与奇迹只有第二个音节声母不同（zh 与 j），意思是旗子。", "其次": "其次（qí cì）与奇迹只有第二个音节声母不同（c 与 j），意思是次一等、然后。"}, "sentence_index": null, "correct_answer": "奇迹"}, "level_3": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹：没人想到会发生的神奇好事，“创造奇迹”是常见搭配。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：早晨是自然的时间，不能被“创造”出来。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“创造”通常接成绩、纪录、历史等，不接“呼吸”这类生理活动。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：季节是自然现象，“创造了冬天”不成立。"}], "explanations": {"奇迹": "奇迹：没人想到会发生的神奇好事，“创造奇迹”是常见搭配。", "早晨": "语义：早晨是自然的时间，不能被“创造”出来。", "呼吸": "搭配：“创造”通常接成绩、纪录、历史等，不接“呼吸”这类生理活动。", "冬天": "语义：季节是自然现象，“创造了冬天”不成立。"}, "sentence_index": 6, "correct_answer": "奇迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是学校的奇迹，每个人都要遵守。", "explanation": "这里应该用〈规定〉。奇迹指特别神奇的好事，不能用来说学校的要求；要遵守的应是〈规定〉。"}, {"text": "他的奇迹是计算机，大学学的就是这个。", "explanation": "这里应该用〈专业〉。奇迹指特别神奇的好事，不能用来说一个人的学习方向；这里要用〈专业〉。"}, {"text": "他的脾气很坏，经常和同学打架，这种行为是奇迹的表现。", "explanation": "这里应该用〈问题〉。奇迹指好事，不能用来形容打架这类坏行为；这里应该用〈问题〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场车祸里他没有受伤，真是一只奇迹。", "corrected_sentence": "那场车祸里他没有受伤，真是一个奇迹。", "error_description": "量词错误：“奇迹”应搭配量词“个”，“只”用于动物等，不能修饰这种抽象的好事；正确说法是“一个奇迹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大火之后，他竟然活了下来，真是很奇迹。", "corrected_sentence": "那场大火之后，他竟然活了下来，真是奇迹。", "error_description": "错误形式是在“奇迹”前加了程度副词“很”。“很”修饰形容词或动词，不能修饰名词“奇迹”，应说“真是奇迹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
