INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "令人惊奇的、不可思议的事情。", "primary_collocate": null, "pronunciation": "qí jì", "ipa": "tɕʰi˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这座桥是建筑上的奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是世界上的奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人走完这条路，真是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然有很多奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人搬走了大石头，像奇迹一样。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市十年就变了样，真是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次开口说话，让妈妈看到了奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙漠里种出了树，这是奇迹。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的奇迹不常见。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，这不是奇迹，是努力。", "target_word": "奇迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个奇迹", "label": "量词"}, {"form": "奇蹟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奇迹：令人惊奇、不可思议的事情或成就", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94016, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹（qí jì）：令人惊奇、不可思议的事情或成就，是这里要辨认的词。"}, {"text": "齐集", "is_correct": false, "explanation": "齐集（qí jí）与奇迹只有第二个音节声调不同（第二声 jí 与第四声 jì），意思是聚集到一起。"}, {"text": "齐聚", "is_correct": false, "explanation": "齐聚（qí jù）与奇迹只有第二个音节韵母不同（jù 与 jì），意思是齐齐地聚在一起。"}, {"text": "企及", "is_correct": false, "explanation": "企及（qǐ jí）与奇迹两个音节的声调都不同（第三声 qǐ、第二声 jí），意思是达到、赶上。"}], "explanations": {"奇迹": "奇迹（qí jì）：令人惊奇、不可思议的事情或成就，是这里要辨认的词。", "齐集": "齐集（qí jí）与奇迹只有第二个音节声调不同（第二声 jí 与第四声 jì），意思是聚集到一起。", "齐聚": "齐聚（qí jù）与奇迹只有第二个音节韵母不同（jù 与 jì），意思是齐齐地聚在一起。", "企及": "企及（qǐ jí）与奇迹两个音节的声调都不同（第三声 qǐ、第二声 jí），意思是达到、赶上。"}, "sentence_index": null, "correct_answer": "奇迹"}, "level_3": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹：令人赞叹的建筑成就，可以放在“建筑上的”之后。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“建筑上的”限定的是工程或成就，情绪不是建筑的特点，句子不通。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：早晨是时间，不能说“建筑上的早晨”。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“建筑上的”修饰结构、风格、成就，不能修饰“笑声”。"}], "explanations": {"奇迹": "奇迹：令人赞叹的建筑成就，可以放在“建筑上的”之后。", "情绪": "语义：“建筑上的”限定的是工程或成就，情绪不是建筑的特点，句子不通。", "早晨": "语义：早晨是时间，不能说“建筑上的早晨”。", "笑声": "搭配：“建筑上的”修饰结构、风格、成就，不能修饰“笑声”。"}, "sentence_index": 0, "correct_answer": "奇迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把奇迹放进了柜子里。", "explanation": "这里应该用〈物品〉。奇迹指令人惊奇的事情，是抽象的，不能放进柜子；这里要用实物〈物品〉。"}, {"text": "这个奇迹很简单，只要按照步骤做就行。", "explanation": "这里应该用〈方法〉。奇迹指令人惊奇的事情，不能用来形容做法简单；这里要用〈方法〉。"}, {"text": "这次台风造成了很大的奇迹，许多房子都倒了。", "explanation": "这里应该用〈灾难〉。奇迹指令人惊叹的事情，不能用来指台风带来的破坏；这里应该用〈灾难〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94016, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹（qí jì）：令人惊奇、不可思议的事情或成就，是这里要辨认的词。"}, {"text": "骑士", "is_correct": false, "explanation": "骑士（qí shì）与奇迹只有第二个音节声母不同（sh 与 j），意思是中世纪的武士。"}, {"text": "旗帜", "is_correct": false, "explanation": "旗帜（qí zhì）与奇迹只有第二个音节声母不同（zh 与 j），意思是旗子。"}, {"text": "其次", "is_correct": false, "explanation": "其次（qí cì）与奇迹只有第二个音节声母不同（c 与 j），意思是次一等、然后。"}], "explanations": {"奇迹": "奇迹（qí jì）：令人惊奇、不可思议的事情或成就，是这里要辨认的词。", "骑士": "骑士（qí shì）与奇迹只有第二个音节声母不同（sh 与 j），意思是中世纪的武士。", "旗帜": "旗帜（qí zhì）与奇迹只有第二个音节声母不同（zh 与 j），意思是旗子。", "其次": "其次（qí cì）与奇迹只有第二个音节声母不同（c 与 j），意思是次一等、然后。"}, "sentence_index": null, "correct_answer": "奇迹"}, "level_3": {"options": [{"text": "奇迹", "is_correct": true, "explanation": "奇迹：令人惊叹的事，可以放在“看到了”之后。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看到”不能接“声音”，听觉对象应说“听到”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度要靠身体感觉体会，不能用眼睛“看到”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看到”不能接“味道”，味道应说“尝到”或“闻到”。"}], "explanations": {"奇迹": "奇迹：令人惊叹的事，可以放在“看到了”之后。", "声音": "搭配：“看到”不能接“声音”，听觉对象应说“听到”。", "温度": "语义：温度要靠身体感觉体会，不能用眼睛“看到”。", "味道": "搭配：“看到”不能接“味道”，味道应说“尝到”或“闻到”。"}, "sentence_index": 6, "correct_answer": "奇迹"}, "level_6": {"correct_sentence_index": 8, "wrong_sentences": [{"text": "他大学学的奇迹是医学。", "explanation": "这里应该用〈专业〉。奇迹指令人惊奇的事情，不能用来说学习的方向；这里要用〈专业〉。"}, {"text": "我们在奇迹里开了一个下午的会。", "explanation": "这里应该用〈会议室〉。奇迹是抽象的事情，不是地点，不能用“在……里”表示开会的场所；这里应该用〈会议室〉。"}, {"text": "这种奇迹很常见，每个人都会得。", "explanation": "这里应该用〈疾病〉。奇迹指令人惊奇的事情，不是病，不能说“每个人都会得”；这里应该用〈疾病〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古桥在洪水里屹立不倒，真是一条奇迹。", "corrected_sentence": "这座古桥在洪水里屹立不倒，真是一个奇迹。", "error_description": "量词错误：“条”用于细长的东西，奇迹不是这类事物，应说“一个奇迹”，不能说“一条奇迹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在沙漠里种出了一片森林，真是一张奇迹。", "corrected_sentence": "他们在沙漠里种出了一片森林，真是一个奇迹。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，奇迹不能用“张”，应说“一个奇迹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
