INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父亲的母亲。", "primary_collocate": null, "pronunciation": "nǎi nai", "ipa": "nai̯˨˩˦ nai̯", "syllable_count": 2, "sentences": [{"text": "奶奶是爸爸的妈妈。", "target_word": "奶奶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我奶奶今年七十岁了。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我常去奶奶家。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶住在乡下，爸爸常回去看她。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我做了一件毛衣。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，奶奶小时候很苦。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上都去公园走路。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和奶奶一起包过饺子。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的头发已经白了。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给奶奶买了一个新手机。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老奶奶", "label": "复合"}], "register": "口语", "sense_fingerprint": "爸爸的妈妈，亲属称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc29dc70-dc3b-43f5-8c12-a16457eab3c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奶奶", "is_correct": true, "explanation": "正确。奶奶指父亲的母亲，与句中“爸爸的妈妈”一致。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：爷爷指父亲的父亲，是男性，不能是“爸爸的妈妈”。"}, {"text": "外婆", "is_correct": false, "explanation": "语义：外婆指母亲的母亲，与“爸爸的妈妈”不是同一个人。"}, {"text": "姑姑", "is_correct": false, "explanation": "语义：姑姑是父亲的姐妹，不是父亲的母亲。"}], "explanations": {"奶奶": "正确。奶奶指父亲的母亲，与句中“爸爸的妈妈”一致。", "爷爷": "语义：爷爷指父亲的父亲，是男性，不能是“爸爸的妈妈”。", "外婆": "语义：外婆指母亲的母亲，与“爸爸的妈妈”不是同一个人。", "姑姑": "语义：姑姑是父亲的姐妹，不是父亲的母亲。"}, "sentence_index": 0, "correct_answer": "奶奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶是妈妈的妈妈。", "explanation": "这里应该用〈外婆〉。奶奶指父亲的母亲，妈妈的妈妈是外婆。"}, {"text": "我们班的奶奶都很努力学习。", "explanation": "这里应该用〈同学〉。奶奶指父亲的母亲，不能用来称呼同班的同龄人。"}, {"text": "奶奶是爸爸的姐姐。", "explanation": "这里应该用〈姑姑〉。奶奶指父亲的母亲，爸爸的姐姐是姑姑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奶奶", "is_correct": true, "explanation": "正确。奶奶指父亲的母亲，能每天早上去公园走路。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会走路，不能去公园。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会走路，不能去公园。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会走路，不能去公园。"}], "explanations": {"奶奶": "正确。奶奶指父亲的母亲，能每天早上去公园走路。", "石头": "语义：石头不会走路，不能去公园。", "桌子": "语义：桌子不会走路，不能去公园。", "椅子": "语义：椅子不会走路，不能去公园。"}, "sentence_index": 6, "correct_answer": "奶奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶是爸爸的妻子。", "explanation": "这里应该用〈妈妈〉。奶奶指父亲的母亲，爸爸的妻子是妈妈。"}, {"text": "奶奶是我爸爸的弟弟。", "explanation": "这里应该用〈叔叔〉。奶奶指父亲的母亲，爸爸的弟弟是叔叔。"}, {"text": "奶奶是爸爸的爸爸。", "explanation": "这里应该用〈爷爷〉。奶奶指父亲的母亲，爸爸的爸爸是爷爷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一条奶奶，住在乡下。", "corrected_sentence": "我有一位奶奶，住在乡下。", "error_description": "量词错误：“奶奶”指人，应用量词“位”。“条”用于细长的东西，不能用于人，应把“一条”改为“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我写了一封信奶奶。", "corrected_sentence": "我写了一封信给奶奶。", "error_description": "介词漏用：“奶奶”是收信人，前面要用介词“给”引出，应为“写了一封信给奶奶”。去掉“给”后，“奶奶”紧接在宾语后面，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
