INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94019, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好奇是看到新鲜东西，就想知道是什么。", "primary_collocate": null, "pronunciation": "hào qí", "ipa": "xɑʊ̯˥˩ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "小孩看到新玩具，很好奇。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟对什么都很好奇，总是问为什么。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫看见窗外的鸟，很好奇。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次来中国，对街上的一切都很好奇。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对那个大箱子很好奇，都想打开看看。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很好奇，那个盒子里到底有什么。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不好奇外面发生了什么事吗？", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗闻着新鞋子，好像很好奇。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对手机里的新功能特别好奇。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到陌生的盒子，谁都会觉得好奇。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好奇心", "label": "复合"}, {"form": "好奇地", "label": "复合"}], "register": "中性", "sense_fingerprint": "好奇|形容词|看到新鲜东西想知道是什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：好奇，指看到新鲜东西就想知道是什么。"}, {"text": "豪气", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，qì（第四声）与 qí（第二声）声调也不同，“豪气”意思是勇敢、有气魄。"}, {"text": "好棋", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，“好棋”指走得好的一步棋。"}, {"text": "耗气", "is_correct": false, "explanation": "第二音节 qì（第四声）与 qí（第二声）声调不同，“耗气”指消耗力气。"}], "explanations": {"好奇": "正确：好奇，指看到新鲜东西就想知道是什么。", "豪气": "háo（第二声）与 hào（第四声）声调不同，qì（第四声）与 qí（第二声）声调也不同，“豪气”意思是勇敢、有气魄。", "好棋": "hǎo（第三声）与 hào（第四声）声调不同，“好棋”指走得好的一步棋。", "耗气": "第二音节 qì（第四声）与 qí（第二声）声调不同，“耗气”指消耗力气。"}, "sentence_index": null, "correct_answer": "好奇"}, "level_3": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：“好奇”指看到新鲜事物想知道是什么，与“看到新玩具”的心理相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指对人或事不热情，与小孩看到新玩具后想了解的心理相反。"}, {"text": "大方", "is_correct": false, "explanation": "语义：“大方”形容举止不拘谨或待人慷慨，不能说明看到玩具时的心理。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示发怒，与看到新玩具后的反应不符。"}], "explanations": {"好奇": "正确：“好奇”指看到新鲜事物想知道是什么，与“看到新玩具”的心理相符。", "冷淡": "语义：“冷淡”指对人或事不热情，与小孩看到新玩具后想了解的心理相反。", "大方": "语义：“大方”形容举止不拘谨或待人慷慨，不能说明看到玩具时的心理。", "生气": "语义：“生气”表示发怒，与看到新玩具后的反应不符。"}, "sentence_index": 0, "correct_answer": "好奇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很好奇。", "explanation": "这里应该用〈好看〉。“好奇”描述人想了解的心理，不能用来形容衣服。"}, {"text": "他很好奇，请大家吃饭。", "explanation": "这里应该用〈大方〉。“好奇”是对事物的心理，不能说明待人慷慨。"}, {"text": "这支笔很好奇。", "explanation": "这里应该用〈好用〉。“好奇”描述人想了解的心理，不能用来形容笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：“好奇”与“你不……外面发生了什么事吗”构成否定疑问，表示想了解的心理。"}, {"text": "认真", "is_correct": false, "explanation": "搭配：“认真”修饰做事的态度，不修饰“想不想知道”的心理。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”指不愿劳动，与“外面发生了什么事”的疑问无关。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事不仔细，不能说明对外面事情的心理。"}], "explanations": {"好奇": "正确：“好奇”与“你不……外面发生了什么事吗”构成否定疑问，表示想了解的心理。", "认真": "搭配：“认真”修饰做事的态度，不修饰“想不想知道”的心理。", "懒惰": "语义：“懒惰”指不愿劳动，与“外面发生了什么事”的疑问无关。", "粗心": "语义：“粗心”指做事不仔细，不能说明对外面事情的心理。"}, "sentence_index": 6, "correct_answer": "好奇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子很好奇，量得很准。", "explanation": "这里应该用〈精确〉。“好奇”描述人想了解的心理，不能用来形容尺子。"}, {"text": "这道题很好奇。", "explanation": "这里应该用〈难〉。“好奇”描述人想了解的心理，不能用来形容题目。"}, {"text": "他的声音很好奇。", "explanation": "这里应该用〈洪亮〉。“好奇”描述人想了解的心理，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们跟那只小猫很好奇。", "corrected_sentence": "孩子们对那只小猫很好奇。", "error_description": "错误：“好奇”的对象要用介词“对”引出，不能用“跟”。正确应为“孩子们对那只小猫很好奇。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她好奇一直在门口张望。", "corrected_sentence": "她好奇得一直在门口张望。", "error_description": "错误：“一直在门口张望”是“好奇”的程度补语，中间要用“得”连接，这里漏了“得”。正确应为“她好奇得一直在门口张望。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
