INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94020, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对未知的事物很想了解、很感兴趣。", "primary_collocate": null, "pronunciation": "hào qí", "ipa": "xɑʊ̯˥˩ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我对太空很好奇，想知道星星是什么。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们对老师的故事很好奇。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他好奇得睡不着，想马上知道结果。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很好奇，新同事是个什么样的人。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对中国的茶文化特别好奇。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对这件事好奇吗？", "target_word": "好奇", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很好奇，他为什么今天没来。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友对海里的动物非常好奇。", "target_word": "好奇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不好奇别人的私事，也不爱问。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很好奇他是怎么学会做饭的。", "target_word": "好奇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好奇心", "label": "复合"}, {"form": "好奇地", "label": "复合"}], "register": "中性", "sense_fingerprint": "好奇|形容词|对未知事物想了解、感兴趣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：好奇，指对未知的事物很想了解、很感兴趣。"}, {"text": "豪气", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，qì（第四声）与 qí（第二声）声调也不同，“豪气”意思是勇敢、有气魄。"}, {"text": "好棋", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，“好棋”指走得好的一步棋。"}, {"text": "耗气", "is_correct": false, "explanation": "第二音节 qì（第四声）与 qí（第二声）声调不同，“耗气”指消耗力气。"}], "explanations": {"好奇": "正确：好奇，指对未知的事物很想了解、很感兴趣。", "豪气": "háo（第二声）与 hào（第四声）声调不同，qì（第四声）与 qí（第二声）声调也不同，“豪气”意思是勇敢、有气魄。", "好棋": "hǎo（第三声）与 hào（第四声）声调不同，“好棋”指走得好的一步棋。", "耗气": "第二音节 qì（第四声）与 qí（第二声）声调不同，“耗气”指消耗力气。"}, "sentence_index": null, "correct_answer": "好奇"}, "level_3": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：“好奇”表示对太空很想了解，与后句“想知道星星是什么”相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”表示不感兴趣，与后句“想知道星星是什么”相矛盾。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”表示觉得没意思，与后句“想知道星星是什么”的意愿冲突。"}, {"text": "好笑", "is_correct": false, "explanation": "搭配：“好笑”多修饰言行或事情，不说“对太空很好笑”。"}], "explanations": {"好奇": "正确：“好奇”表示对太空很想了解，与后句“想知道星星是什么”相符。", "冷淡": "语义：“冷淡”表示不感兴趣，与后句“想知道星星是什么”相矛盾。", "无聊": "语义：“无聊”表示觉得没意思，与后句“想知道星星是什么”的意愿冲突。", "好笑": "搭配：“好笑”多修饰言行或事情，不说“对太空很好笑”。"}, "sentence_index": 0, "correct_answer": "好奇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把刀很好奇。", "explanation": "这里应该用〈锋利〉。“好奇”描述人想了解的心理，不能用来形容刀。"}, {"text": "这座桥很好奇，常年经受风雨。", "explanation": "这里应该用〈坚固〉。“好奇”描述人想了解的心理，不能用来形容桥。"}, {"text": "这把椅子很好奇，经得起很多人坐。", "explanation": "这里应该用〈结实〉。“好奇”描述人想了解的心理，不能用来形容椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好奇", "is_correct": true, "explanation": "正确：“好奇”表示想知道原因，与“他为什么今天没来”的疑问相符。"}, {"text": "勤奋", "is_correct": false, "explanation": "语义：“勤奋”描述做事的态度，不能表示想知道“他为什么没来”的心理。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”表示不说话，与“他为什么今天没来”的疑问不相符。"}, {"text": "尴尬", "is_correct": false, "explanation": "搭配：“尴尬”描写窘迫的心情，与“他为什么今天没来”的疑问不搭配。"}], "explanations": {"好奇": "正确：“好奇”表示想知道原因，与“他为什么今天没来”的疑问相符。", "勤奋": "语义：“勤奋”描述做事的态度，不能表示想知道“他为什么没来”的心理。", "沉默": "语义：“沉默”表示不说话，与“他为什么今天没来”的疑问不相符。", "尴尬": "搭配：“尴尬”描写窘迫的心情，与“他为什么今天没来”的疑问不搭配。"}, "sentence_index": 6, "correct_answer": "好奇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很好奇，把钱都捐给了学校。", "explanation": "这里应该用〈慷慨〉。“好奇”表示想了解的心理，不能用来形容捐钱的行为。"}, {"text": "这门课很好奇，从不放松要求。", "explanation": "这里应该用〈严格〉。“好奇”描述人想了解的心理，不能用来形容课程。"}, {"text": "王老师很好奇，上课从来不笑。", "explanation": "这里应该用〈严肃〉。“好奇”表示想了解未知事物的心理，不能说明人不苟言笑的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他好奇一直盯着窗外的鸟。", "corrected_sentence": "他好奇得一直盯着窗外的鸟。", "error_description": "错误：“好奇”后面表示程度或状态时要用“得”连接，这里漏了“得”。正确应为“他好奇得一直盯着窗外的鸟。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给那只陌生的小鸟很好奇。", "corrected_sentence": "我对那只陌生的小鸟很好奇。", "error_description": "错误：“好奇”的对象要用介词“对”引出，不能用“给”。正确应为“我对那只陌生的小鸟很好奇。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
