INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "姓是名字前面的字，是一家人都有的。", "primary_collocate": null, "pronunciation": "xìng", "ipa": "ɕiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我们一家人的姓是一样的。", "target_word": "姓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的姓很少见。", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "王是中国很常见的姓。", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我跟爸爸的姓一样。", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的姓一般跟爸爸一样。", "target_word": "姓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个姓在我们村里很多。", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她结婚以后，还用自己的姓。", "target_word": "姓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥和我的姓都是李。", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的姓和我的一样吗？", "target_word": "姓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们是一家人，所以有同一个姓。", "target_word": "姓", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "姓氏", "label": "复合"}, {"form": "姓名", "label": "复合"}], "register": "中性", "sense_fingerprint": "一家人共有的、放在名字前面的字，如王、李、张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94021, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姓", "is_correct": true, "explanation": "正确。xìng 就是“姓”，表示一家人共有的字。"}, {"text": "星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是星星。"}, {"text": "心", "is_correct": false, "explanation": "xīn 与 xìng 韵母不同（in 与 ing），意思是心脏、心情。"}, {"text": "行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是行走、行为。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng（第三声）与 xìng（第四声）声调不同，意思是醒来。"}, {"text": "信", "is_correct": false, "explanation": "xìn 与 xìng 韵母不同（in 与 ing），声调相同，意思是书信。"}], "explanations": {"姓": "正确。xìng 就是“姓”，表示一家人共有的字。", "星": "xīng（第一声）与 xìng（第四声）声调不同，意思是星星。", "心": "xīn 与 xìng 韵母不同（in 与 ing），意思是心脏、心情。", "行": "xíng（第二声）与 xìng（第四声）声调不同，意思是行走、行为。", "醒": "xǐng（第三声）与 xìng（第四声）声调不同，意思是醒来。", "信": "xìn 与 xìng 韵母不同（in 与 ing），声调相同，意思是书信。"}, "sentence_index": null, "correct_answer": "姓"}, "level_3": {"options": [{"text": "姓", "is_correct": true, "explanation": "正确。“我们一家人的姓是一样的”中，姓指一家人共有的字。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”是名字中的名，一家人的名字不一样，不能共用。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：一家人的年龄不可能都一样，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高因人而异，一家人不会都一样，与句意不符。"}], "explanations": {"姓": "正确。“我们一家人的姓是一样的”中，姓指一家人共有的字。", "名": "语义：“名”是名字中的名，一家人的名字不一样，不能共用。", "年龄": "语义：一家人的年龄不可能都一样，与句意不符。", "身高": "体貌：身高因人而异，一家人不会都一样，与句意不符。"}, "sentence_index": 0, "correct_answer": "姓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的姓是小明。", "explanation": "这里应该用〈名〉。姓是家族的字，如王、李；小明是名字，要用“名”。"}, {"text": "我的姓是大家给我取的外号。", "explanation": "这里把“姓”当成了〈外号〉来用。姓是家族传下来的字，不是大家给取的绰号。"}, {"text": "我把姓放在桌子上。", "explanation": "这里把“姓”当成了〈名片〉一类的实物来用。姓是家族的字，不能直接放在桌上；放的是写着姓的名片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94021, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姓", "is_correct": true, "explanation": "正确。xìng 就是“姓”，表示一家人共有的字。"}, {"text": "新", "is_correct": false, "explanation": "xīn 与 xìng 韵母不同（in 与 ing），意思是新的。"}, {"text": "辛", "is_correct": false, "explanation": "xīn 与 xìng 韵母不同（in 与 ing），意思是辛苦、辛辣。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是形状。"}, {"text": "型", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是类型、模型。"}], "explanations": {"姓": "正确。xìng 就是“姓”，表示一家人共有的字。", "新": "xīn 与 xìng 韵母不同（in 与 ing），意思是新的。", "辛": "xīn 与 xìng 韵母不同（in 与 ing），意思是辛苦、辛辣。", "形": "xíng（第二声）与 xìng（第四声）声调不同，意思是形状。", "型": "xíng（第二声）与 xìng（第四声）声调不同，意思是类型、模型。"}, "sentence_index": null, "correct_answer": "姓"}, "level_3": {"options": [{"text": "姓", "is_correct": true, "explanation": "正确。“还用自己的姓”指婚后仍保留原来的姓。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以“用”的东西，与句意不符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：句子说的是结婚后名字前面的字有没有改，“工作”与此无关。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别不能“用”，句中指的是家族的字。"}], "explanations": {"姓": "正确。“还用自己的姓”指婚后仍保留原来的姓。", "年龄": "语义：年龄不是可以“用”的东西，与句意不符。", "工作": "语义：句子说的是结婚后名字前面的字有没有改，“工作”与此无关。", "性别": "语义：性别不能“用”，句中指的是家族的字。"}, "sentence_index": 6, "correct_answer": "姓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的姓是女。", "explanation": "这里应该用〈性别〉。姓是家族的字，说“是男/女”的是性别。"}, {"text": "我的姓是2023001。", "explanation": "这里应该用〈学号〉。姓是家族的字，不是数字编号。"}, {"text": "我的姓是十八岁。", "explanation": "这里应该用〈年龄〉。姓表示家族，不表示岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只姓在城里很少见。", "corrected_sentence": "这个姓在城里很少见。", "error_description": "量词错误。“只”用于动物，姓不能用“只”计量，应该用“个”：这个姓。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把姓在我们村很少见。", "corrected_sentence": "这个姓在我们村很少见。", "error_description": "量词错误。“把”用于有柄的器具，姓应该用“个”：这个姓。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
