INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山区是有很多山的地方。", "primary_collocate": null, "pronunciation": "shān qū", "ipa": "ʂan˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "他在山区长大。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的路不好走。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个山区冬天很冷。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要去山区看孩子们。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区里的人家很少。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在山区教了十年书。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的空气特别新鲜。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区下雨，路上有石头。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给山区学校送去了书。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个山区没有火车。", "target_word": "山区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片山区", "label": "量词"}, {"form": "山區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "山区：有很多山的地方，常指交通不便的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31cd9ccf-46cc-489b-9a7d-aecd9f59af1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山区", "is_correct": true, "explanation": "山区（shān qū）：有很多山的地方。"}, {"text": "删去", "is_correct": false, "explanation": "删去（shān qù）与山区只有第二个音节声调不同（第四声 qù 与第一声 qū），意思是把某些内容去掉。"}, {"text": "商区", "is_correct": false, "explanation": "商区（shāng qū）与山区只有第一个音节韵母不同（ang 与 an），意思是商业集中的区域。"}, {"text": "三区", "is_correct": false, "explanation": "三区（sān qū）与山区只有第一个音节声母不同（s 与 sh），意思是第三个区域。"}], "explanations": {"山区": "山区（shān qū）：有很多山的地方。", "删去": "删去（shān qù）与山区只有第二个音节声调不同（第四声 qù 与第一声 qū），意思是把某些内容去掉。", "商区": "商区（shāng qū）与山区只有第一个音节韵母不同（ang 与 an），意思是商业集中的区域。", "三区": "三区（sān qū）与山区只有第一个音节声母不同（s 与 sh），意思是第三个区域。"}, "sentence_index": null, "correct_answer": "山区"}, "level_3": {"options": [{"text": "山区", "is_correct": true, "explanation": "山区：有很多山的地方，可以作为“在……长大”的地点。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人可以长大的地方，“他在空气长大”不合理。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是器物，不能作为人长大的地方。"}, {"text": "早上", "is_correct": false, "explanation": "搭配：“在……长大”需要地点作宾语，“早上”是时间，不能这样搭配。"}], "explanations": {"山区": "山区：有很多山的地方，可以作为“在……长大”的地点。", "空气": "语义：空气不是人可以长大的地方，“他在空气长大”不合理。", "家具": "语义：家具是器物，不能作为人长大的地方。", "早上": "搭配：“在……长大”需要地点作宾语，“早上”是时间，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "山区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片山区没有一座山，全是平地，适合种庄稼。", "explanation": "这里应该用〈平原〉。山区指多山的地方，这里说没有山、全是平地，应该用〈平原〉。"}, {"text": "我早饭吃了一碗山区。", "explanation": "这里应该用〈米饭〉。山区是一片地区，不能吃；一碗可以吃的应是〈米饭〉。"}, {"text": "他是个山区，世代住在山里。", "explanation": "这里应该用〈山民〉。“山区”指地区，不能用来指人；指住在山里的人要说“山民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山区", "is_correct": true, "explanation": "山区：有很多山的地方，符合句子描述空气特别新鲜的语境。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，没有可以“新鲜”的空气，“字典的空气”不成立。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：柜子是家具，不能说它的空气特别新鲜。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”指饮食，“……的空气特别新鲜”需要环境或地点作主语。"}], "explanations": {"山区": "山区：有很多山的地方，符合句子描述空气特别新鲜的语境。", "字典": "语义：字典是书，没有可以“新鲜”的空气，“字典的空气”不成立。", "柜子": "语义：柜子是家具，不能说它的空气特别新鲜。", "早饭": "搭配：“早饭”指饮食，“……的空气特别新鲜”需要环境或地点作主语。"}, "sentence_index": 6, "correct_answer": "山区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个山区很长，流过很多城市。", "explanation": "这里应该用〈河流〉。山区是一片地区，不会流动，不能说“流过很多城市”；这里应该用〈河流〉。"}, {"text": "我们的山区每周都要交作业。", "explanation": "这里应该用〈学生〉。山区是地区，不能交作业；交作业的应是〈学生〉。"}, {"text": "这个山区感冒了，需要休息几天。", "explanation": "这里应该用〈病人〉。山区是地区，不会感冒；生病的应是〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些药材都是从里山区采来的。", "corrected_sentence": "这些药材都是从山区采来的。", "error_description": "方位词位置错误：“里”不能放在“山区”前面。直接说“从山区采来的”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生在一条山区生活了十年。", "corrected_sentence": "这位医生在一个山区生活了十年。", "error_description": "量词错误：“山区”应搭配量词“个”，“条”用于细长的东西，不能修饰地区；正确说法是“在一个山区生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fab36115-6b05-4e23-b3f8-87ecffc1219a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
