INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94025, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "身上或物体上附有某种具体东西。", "primary_collocate": null, "pronunciation": "dài yǒu", "ipa": "tai̯˥˩ jou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆自行车带有一个小铃铛。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子带有一个小盖子。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的帽子上带有一朵花。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个罐子上带有一个小把手。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个茶壶带有一个长长的嘴。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服上带有一块补丁。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包带有三个小口袋。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件外套带有一个帽子。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋带有两根鞋带。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子带有一把小锁。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身上或物体上附有某种具体东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc29dc70-dc3b-43f5-8c12-a16457eab3c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带有", "is_correct": true, "explanation": "正确。带有表示自行车上附有小铃铛，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：自行车不会吃东西，不能说“自行车吃一个小铃铛”。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”要求人作主语、衣物作宾语，不能接“小铃铛”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，铃铛不能喝。"}], "explanations": {"带有": "正确。带有表示自行车上附有小铃铛，与句意一致。", "吃": "语义：自行车不会吃东西，不能说“自行车吃一个小铃铛”。", "穿": "配价：“穿”要求人作主语、衣物作宾语，不能接“小铃铛”。", "喝": "语义：“喝”的对象是液体，铃铛不能喝。"}, "sentence_index": 0, "correct_answer": "带有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我出门时忘了带有钱包。", "explanation": "这里应该用〈带〉。带有表示附着某种东西，随身携带物品要用“带”。"}, {"text": "妈妈带有一个婴儿走进门。", "explanation": "这里应该用〈抱〉。抱着婴儿要用“抱”，“带有”不表示怀里抱着人。"}, {"text": "她带有三个孩子去公园。", "explanation": "这里应该用〈带〉。“带有”不表示领着人外出，带孩子去公园要用“带”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带有", "is_correct": true, "explanation": "正确。带有表示包上附有小口袋，与句意一致。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”的对象不能是包上的口袋，句子不通。"}, {"text": "戴", "is_correct": false, "explanation": "配价：“戴”要求帽子、眼镜等作宾语，不能接“小口袋”。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”与“三个小口袋”搭配不当，句子不通。"}], "explanations": {"带有": "正确。带有表示包上附有小口袋，与句意一致。", "卖": "语义：“卖”的对象不能是包上的口袋，句子不通。", "戴": "配价：“戴”要求帽子、眼镜等作宾语，不能接“小口袋”。", "扔": "搭配：“扔”与“三个小口袋”搭配不当，句子不通。"}, "sentence_index": 6, "correct_answer": "带有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我带有一个妹妹。", "explanation": "这里应该用〈有〉。“带有”表示身上或东西上附着某种东西，家人关系要用“有”。"}, {"text": "他带有一群孩子去郊游。", "explanation": "这里应该用〈带领〉。“带有”不表示领着一群人，带领孩子外出要用“带领”。"}, {"text": "他带有一个大箱子搬家。", "explanation": "这里应该用〈搬〉。“带有”表示附着在身上或物体上，搬运大件行李要用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞上很带有几滴雨水。", "corrected_sentence": "这把伞上带有几滴雨水。", "error_description": "副词错误：程度副词“很”不能直接修饰动词“带有”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书包带有过两个小口袋。", "corrected_sentence": "这个书包带有两个小口袋。", "error_description": "用法错误：“带有”表示状态，不能加“过”表示经历，应删去“过”，写成“这个书包带有两个小口袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
