INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "具有；含有。", "primary_collocate": null, "pronunciation": "dài yǒu", "ipa": "tai̯˥˩ jou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌带有浓浓的乡村味道。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话带有很深的感情。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书带有明显的个人色彩。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事带有一点神话色彩。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音带有一种特别的温暖。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划带有一定的风险。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事带有很大的偶然性。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容带有一点害羞。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词带有不好的意思。", "target_word": "带有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画带有很强的地方特色。", "target_word": "带有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "含有某种性质、色彩或感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc29dc70-dc3b-43f5-8c12-a16457eab3c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带有", "is_correct": true, "explanation": "正确。带有表示这首歌含有浓浓的乡村味道，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说歌吃味道。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语应是衣物，不能接“味道”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能用来说歌带有味道，句子不通。"}], "explanations": {"带有": "正确。带有表示这首歌含有浓浓的乡村味道，与句意一致。", "吃": "语义：“吃”指进食，不能说歌吃味道。", "穿": "配价：“穿”的宾语应是衣物，不能接“味道”。", "洗": "语义：“洗”不能用来说歌带有味道，句子不通。"}, "sentence_index": 0, "correct_answer": "带有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这次比赛带有很大的信心。", "explanation": "这里应该用〈抱有〉。对信心、希望等通常说“抱有”，不说“带有”。"}, {"text": "他的成绩带有很大的进步。", "explanation": "这里应该用〈取得〉。成绩的进步通常说“取得进步”，“带有进步”不是通常的说法。"}, {"text": "我带有一把伞出门。", "explanation": "这里应该用〈带着〉。携带物品要用“带着”，不用“带有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带有", "is_correct": true, "explanation": "正确。带有表示这件事含有很大的偶然性，与句意一致。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”要求文字作宾语，不能接“偶然性”。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”的对象不能是“偶然性”，句子不通。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动具体的东西，不能搬运抽象的“偶然性”。"}], "explanations": {"带有": "正确。带有表示这件事含有很大的偶然性，与句意一致。", "写": "配价：“写”要求文字作宾语，不能接“偶然性”。", "卖": "语义：“卖”的对象不能是“偶然性”，句子不通。", "搬": "语义：“搬”指移动具体的东西，不能搬运抽象的“偶然性”。"}, "sentence_index": 6, "correct_answer": "带有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带有一顶红帽子出门。", "explanation": "这里应该用〈戴〉。戴在头上的帽子要用“戴”，“带有”不适用于此。"}, {"text": "他带有一个好消息回家。", "explanation": "这里应该用〈带回〉。“带有”表示具有或含有，把消息带回家要用“带回”。"}, {"text": "她带有一件红裙子。", "explanation": "这里应该用〈穿着〉。衣服要用“穿”，不用“带有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章带有了明显的讽刺意味。", "corrected_sentence": "这篇文章带有明显的讽刺意味。", "error_description": "体标误用：“带有”表示具有某种性质，是状态动词，后面不能加“了”，应改为“带有明显的讽刺意味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首诗被带有淡淡的忧伤。", "corrected_sentence": "这首诗带有淡淡的忧伤。", "error_description": "被动误用：“带有”表示具有某种性质，不能用于“被”字句，应去掉“被”，改为“这首诗带有淡淡的忧伤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff888a25-b015-4f76-a6db-5136e0394f52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
