INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "干扰是别人在旁边打搅，让你没法好好做事。", "primary_collocate": null, "pronunciation": "gān rǎo", "ipa": "kan˥ ʐaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "别在旁边说话，会干扰我学习。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的噪音干扰了他的思考。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要干扰别人看书。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机铃声干扰了大家听课。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的音乐干扰我睡觉。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一直干扰我写作业。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他安静地坐着，不想干扰任何人。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的吵闹干扰了老人休息。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在工作，你别来干扰我。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视的声音干扰着他复习。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干扰了", "label": "完成体"}, {"form": "干扰着", "label": "持续体"}, {"form": "干扰过", "label": "经历体"}, {"form": "干擾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "干扰：旁人的声音或举动打搅正在做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”表示给予有益的支持，与“别在旁边说话”的负面后果不符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏作品或景色，不能用于“学习”这一过程，句意不通。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指旁人打搅，使我无法好好学习，符合句意。"}, {"text": "提高", "is_correct": false, "explanation": "语义：“提高”指使事物变得更好，此句若说旁人说话“会提高”学习，与“别在旁边说话”的负面后果相反。"}], "explanations": {"帮助": "语义：“帮助”表示给予有益的支持，与“别在旁边说话”的负面后果不符。", "欣赏": "语义：“欣赏”指赞赏作品或景色，不能用于“学习”这一过程，句意不通。", "干扰": "“干扰”指旁人打搅，使我无法好好学习，符合句意。", "提高": "语义：“提高”指使事物变得更好，此句若说旁人说话“会提高”学习，与“别在旁边说话”的负面后果相反。"}, "sentence_index": 0, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事干扰了他的心，让他一夜没睡。", "explanation": "这里应该用〈牵动〉。〈牵动〉指引起情绪变化，〈干扰〉只指打搅正在进行的事，不用于说心被触动。"}, {"text": "工厂的废水干扰了河水。", "explanation": "这里应该用〈污染〉。干扰指打搅人或妨碍正在进行的活动，不指使水质变坏。"}, {"text": "这件事干扰了他的性格。", "explanation": "这里应该用〈影响〉。干扰只说打搅正在进行的事，不用于改变人的性格等长期状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感动", "is_correct": false, "explanation": "语义：“感动”指使人心里受触动，与“安静地坐着”的状态不协调，句意不通。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指打搅他人，符合“不想……任何人”的语境。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”接“沉默、纪录”等，不接人。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”接“成果、经验”等，不接人。"}], "explanations": {"感动": "语义：“感动”指使人心里受触动，与“安静地坐着”的状态不协调，句意不通。", "干扰": "“干扰”指打搅他人，符合“不想……任何人”的语境。", "打破": "搭配：“打破”接“沉默、纪录”等，不接人。", "收获": "搭配：“收获”接“成果、经验”等，不接人。"}, "sentence_index": 6, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天把参考书借给我，干扰了我的学习。", "explanation": "这里应该用〈帮助〉。借书是好意，〈干扰〉含打搅、妨碍之意，用于此句与语义相反。"}, {"text": "他一直在旁边鼓励我，干扰了我的学习。", "explanation": "这里应该用〈帮助〉。热心鼓励是好意，〈干扰〉含打搅、妨碍之意，用于此句与语义相反。"}, {"text": "他总是主动替我做家务，干扰了我的学习。", "explanation": "这里应该用〈帮助〉。主动替人做家务是体贴之举，〈干扰〉含打搅之意，与语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟在客厅玩，干扰我了看书。", "corrected_sentence": "弟弟在客厅玩，干扰了我看书。", "error_description": "错误形式：「干扰我了看书」。正确形式：「干扰了我看书」。「了」是完成体标记，应紧跟动词「干扰」，不能放在宾语「我」之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "装修的声音一直干扰得我工作。", "corrected_sentence": "装修的声音一直干扰我工作。", "error_description": "错误形式：「干扰得我工作」。正确形式：「一直干扰我工作」。「得」后面要接说明状态或结果的补语（如「干扰得我没法工作」），这里只有「得」，没有补语，不能成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
