INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打扰；妨碍正常进行。", "primary_collocate": null, "pronunciation": "gān rǎo", "ipa": "kan˥ ʐaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大雾干扰了飞机的正常起飞。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强风干扰了比赛的进行。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界的消息不应干扰我们的计划。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气干扰了我们的出行计划。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题干扰了会议的正常进行。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无关的人员不要干扰医生工作。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不让感情干扰判断。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的施工干扰了交通。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众的喊声干扰了演员表演。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让小事干扰你的正常生活。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干扰了", "label": "完成体"}, {"form": "干扰着", "label": "持续体"}, {"form": "干扰过", "label": "经历体"}, {"form": "干擾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "干扰：外来因素妨碍事情或活动正常进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": false, "explanation": "语义：“保障”指保证，与“大雾”造成的阻碍相反，句意不通。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指外来因素妨碍事情正常进行，符合句意。"}, {"text": "促进", "is_correct": false, "explanation": "语义：“促进”指推动事情发展，与“大雾”造成的阻碍相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”接机器、物品等，不接“起飞”这类过程。"}], "explanations": {"保障": "语义：“保障”指保证，与“大雾”造成的阻碍相反，句意不通。", "干扰": "“干扰”指外来因素妨碍事情正常进行，符合句意。", "促进": "语义：“促进”指推动事情发展，与“大雾”造成的阻碍相反。", "修理": "搭配：“修理”接机器、物品等，不接“起飞”这类过程。"}, "sentence_index": 0, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场台风干扰了农田。", "explanation": "这里应该用〈破坏〉。干扰指妨碍事情或活动的正常进行，不指对农田这类实物造成损坏。"}, {"text": "他干扰了百米纪录。", "explanation": "这里应该用〈打破〉。干扰表示妨碍正在进行的事，不表示突破已有纪录。"}, {"text": "吸烟干扰了健康。", "explanation": "这里应该用〈损害〉。干扰指妨碍事情进行，不指伤害身体或健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治疗", "is_correct": false, "explanation": "搭配：“治疗”接疾病或病人，不接“判断”。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”接距离、温度等可量化的事物，不接“判断”。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指外来因素妨碍判断，符合句意。"}, {"text": "提醒", "is_correct": false, "explanation": "语义：“提醒”需要有人作主语，感情不能提醒判断，句意不通。"}], "explanations": {"治疗": "搭配：“治疗”接疾病或病人，不接“判断”。", "测量": "搭配：“测量”接距离、温度等可量化的事物，不接“判断”。", "干扰": "“干扰”指外来因素妨碍判断，符合句意。", "提醒": "语义：“提醒”需要有人作主语，感情不能提醒判断，句意不通。"}, "sentence_index": 6, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一本好词典，干扰了他的学习。", "explanation": "这里应该用〈帮助〉。买到好词典是好事，〈干扰〉指妨碍正常进行，用于此句与语义相反。"}, {"text": "这件事干扰了他的心，让他一夜没睡。", "explanation": "这里应该用〈牵动〉。〈牵动〉指引起情绪变化，〈干扰〉只指打搅正在进行的事，不用于说心被触动。"}, {"text": "他一直在旁边鼓励我，干扰了我的学习。", "explanation": "这里应该用〈帮助〉。热心鼓励是好意，〈干扰〉含打搅、妨碍之意，用于此句与语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨干扰了过火车的运行。", "corrected_sentence": "暴雨干扰了火车的运行。", "error_description": "错误：「了」与「过」同时用在动词「干扰」之后，一个动词后只能用一个体标。正确形式：「暴雨干扰了火车的运行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "施工把交通干扰。", "corrected_sentence": "施工把交通干扰了。", "error_description": "错误：「把交通干扰」。把字句中动词「干扰」后面不能光杆结尾，须带「了」等其他成分。正确形式：「施工把交通干扰了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
