INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "硬要过问或插手别人不想让你管的私事。", "primary_collocate": null, "pronunciation": "gān shè", "ipa": "kan˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我的事，请你不要干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该干涉孩子交朋友。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是干涉我的生活，我很烦。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我自己的事，你别干涉我。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不干涉我选专业。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板干涉了我们的工作方式。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都不喜欢他干涉别人的事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太爱干涉朋友的决定了。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让别人干涉我的爱情。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总要干涉我穿什么衣服？", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涉了", "label": "体标"}, {"form": "干涉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "硬要管别人不想让你管的私事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手别人的私事，与“我的事”和“请你不要”的语境相符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动、会议等，不能说“参加我的事”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赞赏，与“请你不要”的劝阻语气相悖。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能说“擦我的事”。"}], "explanations": {"干涉": "干涉：过问或插手别人的私事，与“我的事”和“请你不要”的语境相符。", "参加": "搭配：“参加”的对象是活动、会议等，不能说“参加我的事”。", "欣赏": "语义：“欣赏”表示赞赏，与“请你不要”的劝阻语气相悖。", "擦": "搭配：“擦”的对象是物体表面，不能说“擦我的事”。"}, "sentence_index": 0, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直干涉他的勇气。", "explanation": "这里应该用〈欣赏〉。干涉的对象是别人的事务或决定，不能是品质；称赞他人的勇气要用〈欣赏〉。"}, {"text": "我的队友都来干涉我的工作，我们一起完成了任务。", "explanation": "这里应该用〈分担〉。干涉是不受欢迎地插手别人的事务，带有管束之意；队友主动分担工作要用〈分担〉。"}, {"text": "我每天干涉房间。", "explanation": "这里应该用〈打扫〉。干涉的对象是人的事务，不能用于房间这类物体；“打扫房间”才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：插手别人的事，句中“同事们不喜欢他”的语境与之相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“参观别人的事”。"}, {"text": "失败", "is_correct": false, "explanation": "配价：“失败”是不及物动词，不能带“别人的事”作宾语。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活、乐趣等，不能说“享受别人的事”。"}], "explanations": {"干涉": "干涉：插手别人的事，句中“同事们不喜欢他”的语境与之相符。", "参观": "搭配：“参观”的对象是场所或展览，不能说“参观别人的事”。", "失败": "配价：“失败”是不及物动词，不能带“别人的事”作宾语。", "享受": "搭配：“享受”的对象是生活、乐趣等，不能说“享受别人的事”。"}, "sentence_index": 6, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他干涉了那盆花。", "explanation": "这里应该用〈浇〉。干涉的对象是人或人的事务，不能用于植物；应说“浇花”。"}, {"text": "他很快就干涉完了那份作业。", "explanation": "这里应该用〈做〉。干涉是插手别人的事务或决定，不能表示完成作业；做作业要用〈做〉。"}, {"text": "我们干涉了快乐。", "explanation": "这里应该用〈分享〉。干涉的对象是他人的事务或选择，快乐不能被插手；应说“分享快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母不要干涉在我的恋爱。", "corrected_sentence": "父母不要干涉我的恋爱。", "error_description": "错误在于“干涉”后应直接带宾语，不能在宾语前加“在”。正确形式是“父母不要干涉我的恋爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是干涉了我跟谁交往。", "corrected_sentence": "他总是干涉我跟谁交往。", "error_description": "“总是”表示习惯性的动作，不能与表示完成的“了”同用。应去掉“了”，说“他总是干涉我跟谁交往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
