INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过问或插手别人的事情。", "primary_collocate": null, "pronunciation": "gān shè", "ipa": "kan˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "公司领导很少干涉我们的具体工作。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官独立判案，不受别人干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家不能干涉另一个国家的内政。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有干涉学生的社团活动。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想干涉哥哥和朋友的事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，不再干涉家里的大事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不应该过多干涉市场。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长很少干涉老师怎么上课。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不干涉你的选择，你自己决定。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事别人无权干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涉了", "label": "体标"}, {"form": "干涉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "过问或插手他人事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手，句中“很少”与“具体工作”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃具体工作”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“具体工作”作宾语。"}, {"text": "失眠", "is_correct": false, "explanation": "配价：“失眠”是不及物动词，不能带“具体工作”作宾语。"}], "explanations": {"干涉": "干涉：过问或插手，句中“很少”与“具体工作”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能说“吃具体工作”。", "哭": "配价：“哭”是不及物动词，不能带“具体工作”作宾语。", "失眠": "配价：“失眠”是不及物动词，不能带“具体工作”作宾语。"}, "sentence_index": 0, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在干涉电脑。", "explanation": "这里应该用〈修理〉。干涉的对象是人或人的事务，不能用于机器；“修理电脑”才是正确搭配。"}, {"text": "妈妈每天都干涉我的早饭，做得又香又好吃。", "explanation": "这里应该用〈准备〉。干涉是不受欢迎地插手别人的事务，不能表示做饭；“准备早饭”才是正确说法。"}, {"text": "妈妈干涉了窗户。", "explanation": "这里应该用〈擦〉。干涉的对象是人的事务，不能用于窗户等物体；“擦窗户”才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手，句中“过多”与“市场”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗市场”。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带“市场”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}], "explanations": {"干涉": "干涉：过问或插手，句中“过多”与“市场”的语境相符。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗市场”。", "躺": "配价：“躺”是不及物动词，不能带“市场”作宾语。", "睡": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}, "sentence_index": 6, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他干涉了一杯茶。", "explanation": "这里应该用〈喝〉。干涉的对象是他人的事务，不能用于饮品；“喝一杯茶”才是正确搭配。"}, {"text": "他干涉了蜡烛。", "explanation": "这里应该用〈点燃〉。干涉的对象是人或人的事务，不能用于蜡烛；应说“点燃蜡烛”。"}, {"text": "他干涉了一棵树。", "explanation": "这里应该用〈种〉。干涉的对象是人的事务，不能用于植物；应说“种了一棵树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不要干涉了他人的隐私。", "corrected_sentence": "我们不要干涉他人的隐私。", "error_description": "错误在于“不要”表示禁止，不能与表示完成的“了”同用。应去掉“了”，说“我们不要干涉他人的隐私”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长不该随便干涉得学生的选择。", "corrected_sentence": "校长不该随便干涉学生的选择。", "error_description": "“干涉”后的“得”只能接补语，不能直接带宾语。应去掉“得”，说“校长不该随便干涉学生的选择”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
