INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "快钱是很快就能赚到的钱。", "primary_collocate": null, "pronunciation": "kuài qián", "ipa": "kʰwaɪ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他想找一份能赚快钱的工作。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快钱哪有那么容易赚，别想得太美了。", "target_word": "快钱", "complexity_tier": "T3", "furigana": "kuài qián nǎ yǒu nà me róng yì zhuàn，bié xiǎng de tài měi le。", "sentence_source": "generated"}, {"text": "爸爸说，赚快钱要先看清楚风险。", "target_word": "快钱", "complexity_tier": "T3", "furigana": "bà ba shuō，zhuàn kuài qián yào xiān kàn qīng chu fēng xiǎn。", "sentence_source": "generated"}, {"text": "这笔快钱让他很高兴。", "target_word": "快钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了赚快钱，他每天只睡三小时。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友只对快钱有兴趣。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快钱虽然诱人，但是常常有陷阱。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他抢着去赚快钱，却忘了学习。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李赚过几次快钱，后来都亏了。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不要总想着赚快钱。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔快钱", "label": "量词"}, {"form": "快錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很快就能到手的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a85a42-1479-4e4a-b652-72cd3e0bc2f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快钱", "is_correct": true, "explanation": "正确：“赚快钱的工作”指能短时间赚到钱的工作，与“赚”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能靠“赚”得到，“能赚石头的工作”不成立。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是可以赚来的收益，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“赚”搭配钱或利益，不接心情。"}], "explanations": {"快钱": "正确：“赚快钱的工作”指能短时间赚到钱的工作，与“赚”搭配。", "石头": "语义：石头不能靠“赚”得到，“能赚石头的工作”不成立。", "房子": "语义：房子不是可以赚来的收益，句意不通。", "心情": "搭配：“赚”搭配钱或利益，不接心情。"}, "sentence_index": 0, "correct_answer": "快钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我父亲每个月的快钱都很稳定。", "explanation": "这里应该用〈退休金〉。快钱指短时间内容易赚到的钱，不用于每个月固定、稳定的收入。"}, {"text": "这笔快钱是他工作了三十年才慢慢攒下的。", "explanation": "这里应该用〈积蓄〉。快钱指短时间内很快赚到的钱，工作三十年慢慢攒下的钱不是快钱。"}, {"text": "这家公司每年的快钱都很稳定。", "explanation": "这里应该用〈利润〉。快钱是短时间内容易赚到的钱，不能用来形容每年稳定的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快钱", "is_correct": true, "explanation": "正确：“快钱虽然诱人，但常有陷阱”指短时间赚到的钱，语义相合。"}, {"text": "白开水", "is_correct": false, "explanation": "搭配：「诱人」多修饰利益、风景、美食，不说“白开水诱人”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不会让人觉得“诱人”，也谈不上“常有陷阱”。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是让人动心的东西，句子的意思说不通。"}], "explanations": {"快钱": "正确：“快钱虽然诱人，但常有陷阱”指短时间赚到的钱，语义相合。", "白开水": "搭配：「诱人」多修饰利益、风景、美食，不说“白开水诱人”。", "空气": "语义：空气不会让人觉得“诱人”，也谈不上“常有陷阱”。", "墨水": "语义：墨水不是让人动心的东西，句子的意思说不通。"}, "sentence_index": 6, "correct_answer": "快钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子每个月的快钱都很稳定。", "explanation": "这里应该用〈房租〉。快钱指短时间内容易赚到的钱，不能用来形容每月固定的收入。"}, {"text": "他的快钱要等到退休才能领取。", "explanation": "这里应该用〈养老金〉。快钱是短时间内容易赚到的钱，不是等到退休才能领取的钱。"}, {"text": "他在工厂里每天按时领取快钱。", "explanation": "这里应该用〈工资〉。快钱指短时间内不费力赚到的钱，按日领取的薪水不是快钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她说，赚一只快钱的人往往不会长久。", "corrected_sentence": "她说，赚一笔快钱的人往往不会长久。", "error_description": "错误：量词用了“只”；正确：“一笔快钱”。快钱按笔计，量词应为“笔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了一辆快钱，把积蓄都投进了股市。", "corrected_sentence": "他为了一笔快钱，把积蓄都投进了股市。", "error_description": "错误：量词用了“辆”；正确：“一笔快钱”。快钱按笔计，量词应为“笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f19adf-0438-47a7-8026-6e6aba10d77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
