INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应付是想办法把事做完，或者随便做一做。", "primary_collocate": null, "pronunciation": "yìng fu", "ipa": "iŋ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "他只想应付作业，没有认真写。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告太马虎了，明显是应付差事。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做工作要认真，不能随便应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天上班只是应付一下，不想多做。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不多，先应付这个月的生活吧。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没时间做饭，随便应付一顿。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板要的东西，我先应付着做一份。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样应付检查，迟早会出问题。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把作业应付完就去玩了。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习不能只是应付考试。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应付了", "label": "完成体"}, {"form": "应付着", "label": "持续体"}, {"form": "应付过", "label": "经历体"}, {"form": "應付", "label": "繁体"}, {"form": "应付差事", "label": "复合词"}], "register": "中性", "sense_fingerprint": "应付：不认真，只求把事情做完或勉强凑合过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：作业不是值得欣赏的对象，与“没有认真写”的语境不合。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：装饰指美化物体，不能用于作业。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付作业指勉强完成、敷衍了事，符合“没有认真写”的句意。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：粉刷的对象是墙壁、房子，不能说粉刷作业。"}], "explanations": {"欣赏": "语义：作业不是值得欣赏的对象，与“没有认真写”的语境不合。", "装饰": "搭配：装饰指美化物体，不能用于作业。", "应付": "正确：应付作业指勉强完成、敷衍了事，符合“没有认真写”的句意。", "粉刷": "搭配：粉刷的对象是墙壁、房子，不能说粉刷作业。"}, "sentence_index": 0, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友很应付，每次聚会都认真陪伴大家。", "explanation": "这里应该用〈真诚〉。“应付”带有敷衍意味，与“认真陪伴”矛盾。"}, {"text": "这种方法可以应付在教学中。", "explanation": "这里应该用〈应用〉。“应用”指用于某种场合；“应付”指对付情况，不能说“应付在教学中”。"}, {"text": "他应付工作很认真，每件事都仔细检查。", "explanation": "这里应该用〈对待〉。“应付”带有敷衍意味，与“很认真、仔细检查”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推辞", "is_correct": false, "explanation": "语义：推辞指婉言谢绝，“做一份”的东西不是推辞的对象。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付指勉强对付，符合“先应付着做一份”的句意。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：赔偿针对损失或损害，不能用于做东西。"}, {"text": "打听", "is_correct": false, "explanation": "语义：打听指探问消息，与“做一份”无关。"}], "explanations": {"推辞": "语义：推辞指婉言谢绝，“做一份”的东西不是推辞的对象。", "应付": "正确：应付指勉强对付，符合“先应付着做一份”的句意。", "赔偿": "搭配：赔偿针对损失或损害，不能用于做东西。", "打听": "语义：打听指探问消息，与“做一份”无关。"}, "sentence_index": 6, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的梦想终于应付了。", "explanation": "这里应该用〈实现〉。“实现”指梦想成为现实；“应付”表示敷衍或勉强对付，不能指梦想成真。"}, {"text": "这次考试是用来应付学习效果的。", "explanation": "这里应该用〈检验〉。“检验”指查看效果；“应付”表示对付，不能说“应付学习效果”。"}, {"text": "学生应该应付老师的爱，并努力回报。", "explanation": "这里应该用〈接受〉。“接受”指愿意接纳感情，“应付”只表示处理事情或敷衍，不能用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些问题我很快就应付了完。", "corrected_sentence": "这些问题我很快就应付完了。", "error_description": "错误：“应付了完”，结果补语“完”应直接跟在动词后，“了”要放在句末。正确：“应付完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只是随便应付一下地。", "corrected_sentence": "他只是随便应付一下。", "error_description": "错误：“应付一下地”，“地”是状语标记，只能加在形容词或副词后面，动量补语“一下”之后不能加“地”。正确：“应付一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
