INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对待；敷衍。也指想办法处理。", "primary_collocate": null, "pronunciation": "yìng fu", "ipa": "iŋ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "他很会应付各种突发情况。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对记者的问题，他随口应付了几句。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小问题，我一个人就能应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板突然来检查，大家都不知道怎么应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别想着应付我，我要听实话。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的考试很难，我得好好准备才能应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用笑容应付了客人的各种要求。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太多，一个人实在应付不了。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老师的提问只是随便应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师应付各种场面都很自如。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应付了", "label": "完成体"}, {"form": "应付着", "label": "持续体"}, {"form": "应付过", "label": "经历体"}, {"form": "應付", "label": "繁体"}, {"form": "应付自如", "label": "复合词"}], "register": "中性", "sense_fingerprint": "应付：面对情况或要求，想办法处理，或随口敷衍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1db9e8-06c6-4a9b-b527-9c50bd8055f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赞赏美好的事物，突发情况不能用来欣赏，与“很会……各种突发情况”不合。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付指对待、处理突发情况，符合“很会处理突发情况”的句意。"}, {"text": "模仿", "is_correct": false, "explanation": "搭配：模仿的对象是人或动作，不能说模仿突发情况。"}, {"text": "享受", "is_correct": false, "explanation": "语义：享受指愉快地得到或使用，突发情况的棘手性质与之不合。"}], "explanations": {"欣赏": "语义：欣赏指赞赏美好的事物，突发情况不能用来欣赏，与“很会……各种突发情况”不合。", "应付": "正确：应付指对待、处理突发情况，符合“很会处理突发情况”的句意。", "模仿": "搭配：模仿的对象是人或动作，不能说模仿突发情况。", "享受": "语义：享受指愉快地得到或使用，突发情况的棘手性质与之不合。"}, "sentence_index": 0, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对待工作很应付，每件事都一丝不苟地完成。", "explanation": "这里应该用〈认真〉。“应付”也指敷衍了事，与“一丝不苟”矛盾。"}, {"text": "这首歌很好听，我每次都只是随便应付它。", "explanation": "这里应该用〈欣赏〉。“应付”指处理事情或敷衍了事，不能用于欣赏音乐。"}, {"text": "他去那家公司应付财务经理的职位。", "explanation": "这里应该用〈应聘〉。“应聘”指申请某个职位，“应付”不能用于求职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制造", "is_correct": false, "explanation": "搭配：制造说产生问题或麻烦，“要求”不是被制造出来的。"}, {"text": "推销", "is_correct": false, "explanation": "语义：推销指把商品卖给别人，不能用来推销要求。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付指应对、处理客人的要求，符合句意。"}, {"text": "吸引", "is_correct": false, "explanation": "搭配：吸引的对象是注意力或顾客，不能说吸引要求。"}], "explanations": {"制造": "搭配：制造说产生问题或麻烦，“要求”不是被制造出来的。", "推销": "语义：推销指把商品卖给别人，不能用来推销要求。", "应付": "正确：应付指应对、处理客人的要求，符合句意。", "吸引": "搭配：吸引的对象是注意力或顾客，不能说吸引要求。"}, "sentence_index": 6, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他高兴地应付了朋友的邀请，下周去他家做客。", "explanation": "这里应该用〈接受〉。“接受”指愉快地答应邀请；“应付”表示处理或敷衍，与“高兴地”去做客不符。"}, {"text": "他的预言终于应付了。", "explanation": "这里应该用〈应验〉。“应验”指预言成为现实；“应付”表示对待或处理，不能指预言实现。"}, {"text": "每个人都应付平等的权利。", "explanation": "这里应该用〈应有〉，表示理应具有某种权利；“应付”表示处理，不能用于拥有权利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把突发情况应付很好。", "corrected_sentence": "他把突发情况应付得很好。", "error_description": "错误：“应付很好”，动词和程度补语之间漏了“得”。正确：“应付得很好”，动词后接程度补语要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些问题应付了掉。", "corrected_sentence": "他把这些问题应付掉了。", "error_description": "错误：“应付了掉”，结果补语“掉”应紧跟动词，“了”要放在句末。正确：“应付掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d396802-7729-495b-9413-d426656f8a51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
