INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94035, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "应时是正好是这个时候该有的。", "primary_collocate": null, "pronunciation": "yìng shí", "ipa": "iŋ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "天旱了很久，这场雨下得很应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的这笔钱来得很应时，我正需要。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些本子送得很应时，我开学正要用。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天很冷，这杯热茶来得真应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在复习，这本参考书出得很应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大家最需要时说的话，非常应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前教练的提醒很应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，你的电话打得很应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章在考试前发表，真应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以前送来的棉衣，是很应时的礼物。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "應時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "应时：来得正是时候，正合当下的需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：来得正好，正合当下的需要，即正确答案。"}, {"text": "英式", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是英国式样。"}, {"text": "影视", "is_correct": false, "explanation": "yǐng（第三声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是电影和电视。"}, {"text": "应试", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是应付考试。"}], "explanations": {"应时": "应时：来得正好，正合当下的需要，即正确答案。", "英式": "yīng（第一声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是英国式样。", "影视": "yǐng（第三声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是电影和电视。", "应试": "shì（第四声）与 shí（第二声）声调不同，意思是应付考试。"}, "sentence_index": null, "correct_answer": "应时"}, "level_3": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：来得正好，正合当下的需要，与“来得很”搭配，符合句意。"}, {"text": "凌乱", "is_correct": false, "explanation": "搭配：“凌乱”形容杂乱无章，不用来修饰雨的下法。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神透明，不用来修饰雨的下法。"}, {"text": "老套", "is_correct": false, "explanation": "语域：“老套”多指思想、做法陈旧，是口语中的贬义词，不用来描述天气。"}], "explanations": {"应时": "应时：来得正好，正合当下的需要，与“来得很”搭配，符合句意。", "凌乱": "搭配：“凌乱”形容杂乱无章，不用来修饰雨的下法。", "清澈": "搭配：“清澈”形容水或眼神透明，不用来修饰雨的下法。", "老套": "语域：“老套”多指思想、做法陈旧，是口语中的贬义词，不用来描述天气。"}, "sentence_index": 0, "correct_answer": "应时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个很应时的人，从来不迟到。", "explanation": "这里应该用〈守时〉。“应时”说事物来得正合需要，不用来形容人守时间；形容人不迟到要用“守时”。"}, {"text": "他应时考上了大学。", "explanation": "这里应该用〈如愿〉。“应时”说事物来得正合需要，不用来形容人的考试结果；“如愿”才表示愿望得以实现。"}, {"text": "她长得很应时，大家都说她漂亮。", "explanation": "这里应该用〈好看〉。“应时”说事物来得正是时候，不能形容人的长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：来得正好，正合当下的需要，与“提醒”的时机相合，符合句意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时，与“比赛前正好提醒”的语境相反。"}, {"text": "静谧", "is_correct": false, "explanation": "搭配：“静谧”形容环境或氛围安静，不用来修饰提醒。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "语域：“慢吞吞”是口语色彩很重的说法，不用来形容提醒。"}], "explanations": {"应时": "应时：来得正好，正合当下的需要，与“提醒”的时机相合，符合句意。", "陈旧": "语义：“陈旧”指过时，与“比赛前正好提醒”的语境相反。", "静谧": "搭配：“静谧”形容环境或氛围安静，不用来修饰提醒。", "慢吞吞": "语域：“慢吞吞”是口语色彩很重的说法，不用来形容提醒。"}, "sentence_index": 6, "correct_answer": "应时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他应时地提出了建议。", "explanation": "这里应该用〈适时〉。“适时”修饰提出建议这类行为；“应时”形容事物来得恰当，不修饰行为。"}, {"text": "这个房间很应时，又大又亮。", "explanation": "这里应该用〈宽敞〉。“应时”说事物来得合宜，不能形容房间大小。"}, {"text": "我们应时在街上遇见了老师。", "explanation": "这里应该用〈正好〉。“应时”说事物来得合宜，不用于说人在某处遇见某人；“正好”才能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨来很应时。", "corrected_sentence": "这场雨来得很应时。", "error_description": "错误：“来很应时”缺少补语标记“得”，应为“来得很应时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份礼物一点也应时。", "corrected_sentence": "这份礼物一点也不应时。", "error_description": "错误：“一点也”后面漏掉否定词“不”，应为“一点也不应时”，表示一点也不合时宜。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
