INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94036, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "适合时令的；合乎当季的。", "primary_collocate": null, "pronunciation": "yìng shí", "ipa": "iŋ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "夏天的西瓜是应时的水果。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的春笋是很应时的菜。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆只卖应时的蔬菜。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，螃蟹是最应时的食物。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，穿羽绒服才应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天热了，冰淇淋是最应时的零食。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，应时的菜又新鲜又便宜。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节的月饼是应时的礼物。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是五月，樱桃正应时。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买应时的菜，不买大棚里的。", "target_word": "应时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "應時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "应时：合乎季节，多指当季的蔬菜、水果、食物或衣物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2924ff-ae98-4ec2-b567-6d2345447c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：合乎季节，多指当季的蔬菜、水果，即正确答案。"}, {"text": "英式", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是英国式样。"}, {"text": "影视", "is_correct": false, "explanation": "yǐng（第三声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是电影和电视。"}, {"text": "应试", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是应付考试。"}], "explanations": {"应时": "应时：合乎季节，多指当季的蔬菜、水果，即正确答案。", "英式": "yīng（第一声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是英国式样。", "影视": "yǐng（第三声）与 yìng（第四声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是电影和电视。", "应试": "shì（第四声）与 shí（第二声）声调不同，意思是应付考试。"}, "sentence_index": null, "correct_answer": "应时"}, "level_3": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：合乎季节，与“夏天”和当季的西瓜相合，符合句意。"}, {"text": "过季", "is_correct": false, "explanation": "语义：“过季”指已经过了时令，与“夏天的西瓜”正当季的语境相矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神透明，不用来修饰水果。"}, {"text": "老套", "is_correct": false, "explanation": "语域：“老套”多指思想、做法陈旧，是口语中的贬义词，不用来形容水果。"}], "explanations": {"应时": "应时：合乎季节，与“夏天”和当季的西瓜相合，符合句意。", "过季": "语义：“过季”指已经过了时令，与“夏天的西瓜”正当季的语境相矛盾。", "清澈": "搭配：“清澈”形容水或眼神透明，不用来修饰水果。", "老套": "语域：“老套”多指思想、做法陈旧，是口语中的贬义词，不用来形容水果。"}, "sentence_index": 0, "correct_answer": "应时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个很应时的人，从来不迟到。", "explanation": "这里应该用〈守时〉。“应时”指事物合乎季节，不用来形容人守时间。"}, {"text": "他每天应时吃饭。", "explanation": "这里应该用〈按时〉。“应时”形容事物合乎季节，不用来说人的作息；“按时”才用于吃饭。"}, {"text": "这条河的水很应时，可以游泳。", "explanation": "这里应该用〈干净〉。“应时”指合乎季节，不能形容水干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应时", "is_correct": true, "explanation": "应时：合乎季节，与“新鲜”“便宜”的蔬菜相合，符合句意。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”的菜与“又新鲜”相矛盾，句子不通。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”与“又便宜”相矛盾，句子不通。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多用来形容人的身体或物件坚实，不用来修饰菜。"}], "explanations": {"应时": "应时：合乎季节，与“新鲜”“便宜”的蔬菜相合，符合句意。", "冷冻": "语义：“冷冻”的菜与“又新鲜”相矛盾，句子不通。", "昂贵": "语义：“昂贵”与“又便宜”相矛盾，句子不通。", "硬朗": "搭配：“硬朗”多用来形容人的身体或物件坚实，不用来修饰菜。"}, "sentence_index": 6, "correct_answer": "应时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应时在街上遇到了老师。", "explanation": "这里应该用〈恰好〉。“应时”说事物合乎季节，不用于说人在某处遇到人。"}, {"text": "他应时地提出了建议。", "explanation": "这里应该用〈适时〉。“应时”形容事物合乎季节，不修饰提出建议这类行为。"}, {"text": "这个房间很应时，又大又亮。", "explanation": "这里应该用〈宽敞〉。“应时”指合乎季节，不能形容房间大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天的萝卜是很应时蔬菜。", "corrected_sentence": "冬天的萝卜是很应时的蔬菜。", "error_description": "错误：“很应时”修饰名词时，中间要加“的”，应为“很应时的蔬菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批草莓很应时地。", "corrected_sentence": "这批草莓很应时。", "error_description": "错误：“应时”作谓语时句末不加“地”，应为“很应时”；“地”只用于修饰动词，不能放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac5cfabc-0a36-46e3-8f84-8dac7d715b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
