INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94037, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "控股是拥有一家公司最多的股份，能管着这家公司。", "primary_collocate": null, "pronunciation": "kòng gǔ", "ipa": "kʰʊŋ˥˩ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司由一家大银行控股。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多股票，现在控股这家公司。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家控股的企业一般比较稳定。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生控股这家工厂已经十年了。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有百分之六十的股份，所以能控股。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想控股一家公司，得先买够股份。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店是老板的儿子控股的。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁控股这家公司，谁就能做决定。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司想控股一家小报社。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直买股份，现在终于控股了这家店。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控股了", "label": "体标"}, {"form": "控股过", "label": "体标"}], "register": "正式", "sense_fingerprint": "拥有公司最多股份而管着公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd87a46-2f37-4e14-b8d3-920c114019fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控股", "is_correct": true, "explanation": "正确：“控股”指拥有多数股份从而管住公司，用在“由一家大银行”之后正好表示被控制。"}, {"text": "上市", "is_correct": false, "explanation": "配价：“上市”是不及物动词，不能带“一家大银行”作施事，“由……上市”的句子不成立。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：“倒闭”指企业自己停业，不能由银行使这家公司倒闭。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间、场地，不能说打扫一家公司。"}], "explanations": {"控股": "正确：“控股”指拥有多数股份从而管住公司，用在“由一家大银行”之后正好表示被控制。", "上市": "配价：“上市”是不及物动词，不能带“一家大银行”作施事，“由……上市”的句子不成立。", "倒闭": "语义：“倒闭”指企业自己停业，不能由银行使这家公司倒闭。", "打扫": "语义：“打扫”的对象是房间、场地，不能说打扫一家公司。"}, "sentence_index": 0, "correct_answer": "控股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他控股了这家工厂的生产。", "explanation": "这里应该用〈控制〉。控股指拥有公司多数股份从而管理公司，不能用来指控制生产等具体环节。"}, {"text": "他控股了这家工厂的几台机器。", "explanation": "这里应该用〈拥有〉。控股的对象是公司、企业，机器不能被控股，应说拥有几台机器。"}, {"text": "他控股了一辆汽车，每天开它上班。", "explanation": "这里应该用〈拥有〉。控股只用于公司、企业，汽车不能被控股，应说拥有一辆汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控股", "is_correct": true, "explanation": "正确：“是……的”句中，“控股”指老板的儿子拥有这家饭店的多数股份。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，没有受事，不能带“这家饭店”作宾语。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”的对象是文章、言论，不能用于饭店。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用于饭店。"}], "explanations": {"控股": "正确：“是……的”句中，“控股”指老板的儿子拥有这家饭店的多数股份。", "出生": "配价：“出生”是不及物动词，没有受事，不能带“这家饭店”作宾语。", "发表": "语义：“发表”的对象是文章、言论，不能用于饭店。", "唱": "语义：“唱”的对象是歌曲，不能用于饭店。"}, "sentence_index": 6, "correct_answer": "控股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天控股这家店。", "explanation": "这里应该用〈管理〉。控股指拥有公司多数股份这一持续状态，不是每天重复的动作，不能与“每天”搭配。"}, {"text": "他控股了这家店的每一位员工。", "explanation": "这里应该用〈掌控〉。控股的对象是公司、企业，员工不能被控股，应说掌控。"}, {"text": "他控股了这家店的店长。", "explanation": "这里应该用〈任命〉。控股的对象是公司、企业，人不能被控股，应说任命这家店的店长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家银行控股了那家保险公司的经理。", "corrected_sentence": "这家银行控股了那家保险公司。", "error_description": "错误：“控股”的对象只能是公司、企业，不能是人（经理）。正确：“控股了那家保险公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们公司没控股了一家旅行社。", "corrected_sentence": "他们公司没控股过一家旅行社。", "error_description": "错误：否定词“没”后面不能用体标“了”。正确：用“过”，“没控股过一家旅行社”表示从没有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19047cfd-e260-4974-a09a-1b28b4f4a66e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
