INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94039, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "是次是这一次。", "primary_collocate": null, "pronunciation": "shì cì", "ipa": "ʂɻ̩˥˩ tsʰɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "是次比赛，我们班得了第一名。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次旅行，我们去了北京和上海。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次会议很重要，请大家准时到。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次考试不难，大部分同学都通过了。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次活动由学校办，欢迎大家参加。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次演出，小王唱了三首歌。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次比赛的结果，让大家很高兴。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次作业须于周五前提交。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次访问时间不长，只有两天。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次展览在市中心，欢迎大家来看。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "是次：指示代词，指说话时正在谈论的这一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd71f46b-59ce-4fa8-abe9-85caaf31d755') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是次", "is_correct": true, "explanation": "是次：指说话时正在谈论的这一次，正合“这一场比赛我们班得了第一名”的语境。"}, {"text": "下一次", "is_correct": false, "explanation": "语义：“下一次”指将来，与“我们班得了第一名”的已发生结果矛盾。"}, {"text": "很", "is_correct": false, "explanation": "语法：副词“很”不能直接修饰名词“比赛”，此处不成立。"}, {"text": "而且", "is_correct": false, "explanation": "语法：连词“而且”不能充当定语修饰名词“比赛”，此处不成立。"}], "explanations": {"是次": "是次：指说话时正在谈论的这一次，正合“这一场比赛我们班得了第一名”的语境。", "下一次": "语义：“下一次”指将来，与“我们班得了第一名”的已发生结果矛盾。", "很": "语法：副词“很”不能直接修饰名词“比赛”，此处不成立。", "而且": "语法：连词“而且”不能充当定语修饰名词“比赛”，此处不成立。"}, "sentence_index": 0, "correct_answer": "是次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "是次房间很大，我们都很喜欢。", "explanation": "这里应该用〈这间〉。是次只指说话时正在谈论的这一次，不能修饰房间等事物。"}, {"text": "是次的老师非常严格，同学们都怕他。", "explanation": "这里应该用〈这位〉。是次只用于时间，不能修饰人。"}, {"text": "是次汽车很快，我们开了一天。", "explanation": "这里应该用〈这辆〉。是次只指这一次的时间或活动，不能修饰汽车等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是次", "is_correct": true, "explanation": "是次：指说话时正在谈论的这一次，正合“这一场比赛的结果”的语境。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指将来，句中“比赛的结果”已经出现，不符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：副词“非常”不能直接修饰名词“比赛的结果”，此处不成立。"}, {"text": "诸位", "is_correct": false, "explanation": "搭配：“诸位”只指人，不能修饰“比赛的结果”。"}], "explanations": {"是次": "是次：指说话时正在谈论的这一次，正合“这一场比赛的结果”的语境。", "下次": "语义：“下次”指将来，句中“比赛的结果”已经出现，不符。", "非常": "语法：副词“非常”不能直接修饰名词“比赛的结果”，此处不成立。", "诸位": "搭配：“诸位”只指人，不能修饰“比赛的结果”。"}, "sentence_index": 6, "correct_answer": "是次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "是次饭店很干净，我们每周都去吃。", "explanation": "这里应该用〈这家〉。是次只指时间，不能修饰饭店等场所。"}, {"text": "是次同学很友好，大家都喜欢他。", "explanation": "这里应该用〈这位〉。是次只指这一次的时间或活动，不能直接修饰人。"}, {"text": "是次电脑很快，我们用了很久。", "explanation": "这里应该用〈这台〉。是次只指这一次的时间或活动，不能修饰电脑等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班在是次非常比赛中得了第一名。", "corrected_sentence": "我们班在是次比赛中得了第一名。", "error_description": "副词“非常”不能插在指示词“是次”与名词“比赛”之间修饰名词，应去掉“非常”，说“在是次比赛中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都很期待是次非常展览。", "corrected_sentence": "我们都很期待是次展览。", "error_description": "副词“非常”不能插在指示词“是次”与名词“展览”之间修饰名词，应去掉“非常”，说“是次展览”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
