INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "此次；这一次。", "primary_collocate": null, "pronunciation": "shì cì", "ipa": "ʂɻ̩˥˩ tsʰɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "是次考试的题目比上次容易。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次选举，很多年轻人去投票了。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次展览吸引了很多市民参观。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次旅游让我认识了新朋友。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次出差，经理带了三个同事。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次比赛有二十个国家参加。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次服务让我很满意。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次聚会将于周六晚上举行。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次失败，让他明白了努力的重要。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次讲座有一百多人来听。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "是次：此次，用于书面或正式场合指这一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd71f46b-59ce-4fa8-abe9-85caaf31d755') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是次", "is_correct": true, "explanation": "是次：此次，指这一次，正合“这次考试的题目”的语境。"}, {"text": "上次", "is_correct": false, "explanation": "语义：句中已有“比上次”，再说“上次考试”会与之重复，指代冲突。"}, {"text": "很", "is_correct": false, "explanation": "语法：副词“很”不能直接修饰名词“考试”，此处不成立。"}, {"text": "上一场", "is_correct": false, "explanation": "语义：“上一场”指前一场，与“比上次”所指的时间重复、冲突。"}], "explanations": {"是次": "是次：此次，指这一次，正合“这次考试的题目”的语境。", "上次": "语义：句中已有“比上次”，再说“上次考试”会与之重复，指代冲突。", "很": "语法：副词“很”不能直接修饰名词“考试”，此处不成立。", "上一场": "语义：“上一场”指前一场，与“比上次”所指的时间重复、冲突。"}, "sentence_index": 0, "correct_answer": "是次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "是次手机很好用，我每天都带着。", "explanation": "这里应该用〈这部〉。是次只指时间，不能修饰手机等物品。"}, {"text": "是次我三年前就去过那里。", "explanation": "这里不该用〈是次〉。是次指说话时正在谈论的这一次，与“三年前”矛盾。"}, {"text": "是次我们每个月都见面。", "explanation": "这里应该用〈经常〉。是次只指这一次，不能表示反复发生的“每个月都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是次", "is_correct": true, "explanation": "是次：此次，指这一次，正合“这次服务”的语境。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指将来，与“让我很满意”描述的已有感受不符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：副词“非常”不能直接修饰名词“服务”，此处不成立。"}, {"text": "诸位", "is_correct": false, "explanation": "搭配：“诸位”只指人，不能修饰“服务”。"}], "explanations": {"是次": "是次：此次，指这一次，正合“这次服务”的语境。", "下次": "语义：“下次”指将来，与“让我很满意”描述的已有感受不符。", "非常": "语法：副词“非常”不能直接修饰名词“服务”，此处不成立。", "诸位": "搭配：“诸位”只指人，不能修饰“服务”。"}, "sentence_index": 6, "correct_answer": "是次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "是次饭店很干净，我们每周都去吃。", "explanation": "这里应该用〈这家〉。是次只指时间，不能修饰饭店等场所。"}, {"text": "是次邻居很热情，我们经常串门。", "explanation": "这里应该用〈这位〉。是次只指这一次的时间或活动，不能直接修饰人。"}, {"text": "是次手表很漂亮，我戴了一天。", "explanation": "这里应该用〈这块〉。是次只指这一次的时间或活动，不能修饰手表等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多专家都在非常是次大会上发了言。", "corrected_sentence": "很多专家都在是次大会上发了言。", "error_description": "副词“非常”不能修饰指示词“是次”，应去掉“非常”，说“在是次大会上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在非常是次大会上提了很多建议。", "corrected_sentence": "我们在是次大会上提了很多建议。", "error_description": "副词“非常”不能修饰指示词“是次”，应去掉“非常”，说“在是次大会上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aeedaf9-6cb7-4a3e-b37d-560e06633ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
