INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94041, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "未了是还没有结束。", "primary_collocate": null, "pronunciation": "wèi liǎo", "ipa": "weɪ˥˩ liɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他有一个未了的心愿。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段情缘至今未了，他常常想起她。", "target_word": "未了", "complexity_tier": "T3", "furigana": "zhè duàn qíng yuán zhì jīn wèi liǎo, tā cháng cháng xiǎng qǐ tā.", "sentence_source": "generated"}, {"text": "他们之间的恩怨未了，谁也不肯先低头。", "target_word": "未了", "complexity_tier": "T3", "furigana": "tā men zhī jiān de ēn yuàn wèi liǎo, shéi yě bù kěn xiān dī tóu.", "sentence_source": "generated"}, {"text": "父亲的遗愿仍未了，他一直记在心里。", "target_word": "未了", "complexity_tier": "T3", "furigana": "fù qīn de yí yuàn réng wèi liǎo, tā yì zhí jì zài xīn lǐ.", "sentence_source": "generated"}, {"text": "这件事未了，我不能放心。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷走的时候还有未了的事。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这桩心事未了，他一直放不下。", "target_word": "未了", "complexity_tier": "T3", "furigana": "zhè zhuāng xīn shì wèi liǎo, tā yì zhí fàng bù xià.", "sentence_source": "generated"}, {"text": "她的一生还有许多未了的梦想。", "target_word": "未了", "complexity_tier": "T3", "furigana": "tā de yì shēng hái yǒu xǔ duō wèi liǎo de mèng xiǎng.", "sentence_source": "generated"}, {"text": "他的夙愿未了，最终带着遗憾离开。", "target_word": "未了", "complexity_tier": "T3", "furigana": "tā de sù yuàn wèi liǎo, zuì zhōng dài zhe yí hàn lí kāi.", "sentence_source": "generated"}, {"text": "此案未了，法官不便宣判。", "target_word": "未了", "complexity_tier": "T3", "furigana": "cǐ àn wèi liǎo, fǎ guān bù biàn xuān pàn.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事情、活动还没有结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 夙 (Zipf 2.11)']::text[], '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未了", "is_correct": true, "explanation": "未了：尚未了结，修饰“心愿”，符合句意。"}, {"text": "生病", "is_correct": false, "explanation": "语义：心愿不会“生病”，“生病的心愿”句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不与“心愿”搭配，心愿不能被吃。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：心愿不会“迟到”，与句子语境不符。"}], "explanations": {"未了": "未了：尚未了结，修饰“心愿”，符合句意。", "生病": "语义：心愿不会“生病”，“生病的心愿”句意不通。", "吃饭": "搭配：“吃饭”不与“心愿”搭配，心愿不能被吃。", "迟到": "语义：心愿不会“迟到”，与句子语境不符。"}, "sentence_index": 0, "correct_answer": "未了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头发还未了。", "explanation": "这里应该用〈未干〉。未了只用于心愿、事情等尚未了结的事，头发不能“了结”；应说“头发还没干”。"}, {"text": "这件衣服还未了。", "explanation": "这里应该用〈未干〉。未了只用于尚未了结的事情，衣服不能“了结”，要说“还没干”。"}, {"text": "这间屋子还未了。", "explanation": "这里应该用〈未收拾好〉。未了指事情尚未了结，屋子是物体，应说“还没收拾好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未了", "is_correct": true, "explanation": "未了：尚未了结，作谓语说明“心事”的状态，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是动作，不能描述“心事”的状态，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是动作，不能描述“心事”的状态，句意不通。"}, {"text": "晒太阳", "is_correct": false, "explanation": "搭配：“晒太阳”不与“心事”搭配，心事不能被晒。"}], "explanations": {"未了": "未了：尚未了结，作谓语说明“心事”的状态，符合句意。", "睡觉": "语义：“睡觉”是动作，不能描述“心事”的状态，句意不通。", "洗澡": "语义：“洗澡”是动作，不能描述“心事”的状态，句意不通。", "晒太阳": "搭配：“晒太阳”不与“心事”搭配，心事不能被晒。"}, "sentence_index": 6, "correct_answer": "未了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饼干还未了。", "explanation": "这里应该用〈未凉〉。未了用于尚未了结的事情或纠纷，饼干不能“了结”；应说“饼干还没凉”。"}, {"text": "水还未了。", "explanation": "这里应该用〈未开〉。水的状态不能用“未了”描述，应说“水还没开”。"}, {"text": "面包还未了。", "explanation": "这里应该用〈未烤熟〉。未了不用于食物的状态，应说“面包还没烤熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场纠纷已未了，我很担心。", "corrected_sentence": "这场纠纷还未了，我很担心。", "error_description": "“未了”本身已含“尚未”之义，不能与表示已经的“已”同用。应用“还”，说“这场纠纷还未了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔账还未了着，大家都很着急。", "corrected_sentence": "这笔账还未了，大家都很着急。", "error_description": "“未了”表示尚未了结的状态，后面不能加“着”。应去掉“着”，说“这笔账还未了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
