INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本日是今天。", "primary_collocate": null, "pronunciation": "běn rì", "ipa": "pən˨˩˦ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "本日天气很好，适合出门。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日本店休息，敬请谅解。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的会议在下午三点开始。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日图书馆不开门。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的作业请今晚交给老师。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日学校放假，学生都在家。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日是我们公司成立十周年。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的菜单写在门口的黑板上。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日下午有雨，请带好雨伞。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日新闻已全部发布。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "本日：指说话当天，今天（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本日", "is_correct": true, "explanation": "正确：“本日”作时间主语，指说话的当天，与“天气很好，适合出门”相合。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是场所，不能作“天气很好”的主语。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不指时间，不能说“书包天气很好”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”本身就是天气现象，与“天气很好”重复，不能作句首的时间主语。"}], "explanations": {"本日": "正确：“本日”作时间主语，指说话的当天，与“天气很好，适合出门”相合。", "教室": "语义：“教室”是场所，不能作“天气很好”的主语。", "书包": "语义：“书包”是物品，不指时间，不能说“书包天气很好”。", "雨": "搭配：“雨”本身就是天气现象，与“天气很好”重复，不能作句首的时间主语。"}, "sentence_index": 0, "correct_answer": "本日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那场大火发生的本日，城里的人都跑到了街上。", "explanation": "这里应该用〈当日〉。“本日”只指说话的当天，叙述过去某件事发生的那一天要用“当日”。"}, {"text": "他小时候很喜欢本日的动画片。", "explanation": "这里应该用〈那时〉。“本日”指今天，不能用来指小时候的日子。"}, {"text": "我十年前本日去过北京。", "explanation": "这里应该用〈那天〉，删去“本日”。“本日”只指说话的当天，不能用来指十年前的某一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本日", "is_correct": true, "explanation": "正确：“本日”作主语，指今天，与“是……成立十周年”的日期说法相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不能作为公司成立的日期。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“成立”搭配公司、组织，“钢琴”不能与之搭配作主语。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是物品，不能指一个纪念日期。"}], "explanations": {"本日": "正确：“本日”作主语，指今天，与“是……成立十周年”的日期说法相合。", "厨房": "语义：“厨房”是场所，不能作为公司成立的日期。", "钢琴": "搭配：“成立”搭配公司、组织，“钢琴”不能与之搭配作主语。", "地毯": "语义：“地毯”是物品，不能指一个纪念日期。"}, "sentence_index": 6, "correct_answer": "本日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我本日六点起床，雷打不动。", "explanation": "这里应该用〈每天〉。“本日”只指一天，不能用来说明雷打不动的习惯。"}, {"text": "夏天的本日很长，晚上七点天还亮着。", "explanation": "这里应该用〈白天〉。“本日”只指今天，没有“白天”的意思。"}, {"text": "一周里有七个本日。", "explanation": "这里应该用〈天〉。“本日”特指说话的这一天，不能泛指一周中的每一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本日得展览有很多人来参观。", "corrected_sentence": "本日的展览有很多人来参观。", "error_description": "“得”误用：“本日”作定语修饰“展览”，应用“的”；“得”用于动词或形容词后作补语，不能接在名词前，应说“本日的展览”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本日地活动请大家准时参加。", "corrected_sentence": "本日的活动请大家准时参加。", "error_description": "“地”误用：“本日”作定语修饰名词“活动”，应用“的”；“地”用于动词前作状语，不能接在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
