INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今天；这一天。多用于书面语。", "primary_collocate": null, "pronunciation": "běn rì", "ipa": "pən˨˩˦ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "本日营业时间到晚上九点。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日为星期五，全天正常办公。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的活动到此结束，谢谢大家。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日我们要学习一个新词。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日早上下了一场大雨。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的客人很多，厨房特别忙。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日是他的生日，朋友们都来了。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日小店打折，欢迎光临。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日的天气预报说晚上会冷。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本日他很早就到了公司。", "target_word": "本日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "本日：今天、这一天，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c925a36f-77bd-4136-b89b-06b5fdc72f21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本日", "is_correct": true, "explanation": "正确：“本日”作时间主语，指今天，与“营业时间到晚上九点”相合。"}, {"text": "书房", "is_correct": false, "explanation": "搭配：“营业”说的是商店、店铺，不说书房的营业时间。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，没有营业时间，不能作此句主语。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书籍，不指时间，不能与“营业时间”搭配。"}], "explanations": {"本日": "正确：“本日”作时间主语，指今天，与“营业时间到晚上九点”相合。", "书房": "搭配：“营业”说的是商店、店铺，不说书房的营业时间。", "饼干": "语义：“饼干”是食品，没有营业时间，不能作此句主语。", "课本": "语义：“课本”是书籍，不指时间，不能与“营业时间”搭配。"}, "sentence_index": 0, "correct_answer": "本日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她本日坚持晨跑，从不间断。", "explanation": "这里应该用〈每天〉。“本日”只指某一天，不能用来说明长期反复的习惯。"}, {"text": "本日工作了三年，很辛苦。", "explanation": "这里应该用〈这些年〉。“本日”指一天，不能用来指一段较长的时间。"}, {"text": "这一年里我有好几个本日都很忙。", "explanation": "这里应该用〈日子〉。“本日”特指某一天，不能当作泛指的日子来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本日", "is_correct": true, "explanation": "正确：“本日”作主语，指今天，与“是他的生日”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不指日期，不能作“是他的生日”的主语。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：“水杯”是物品，不能指一个日子。"}, {"text": "长椅", "is_correct": false, "explanation": "搭配：“生日”指日期或节日，“长椅”不能与“是……的生日”搭配。"}], "explanations": {"本日": "正确：“本日”作主语，指今天，与“是他的生日”相合。", "冰箱": "语义：“冰箱”是家电，不指日期，不能作“是他的生日”的主语。", "水杯": "语义：“水杯”是物品，不能指一个日子。", "长椅": "搭配：“生日”指日期或节日，“长椅”不能与“是……的生日”搭配。"}, "sentence_index": 6, "correct_answer": "本日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月有三十个本日。", "explanation": "这里应该用〈天〉。“本日”特指说话的这一天，不能当作数量单位来数。"}, {"text": "本日的一年很长，我们都很忙。", "explanation": "这里应该用〈今年〉。“本日”只指一天，不能用来指一整年。"}, {"text": "去年他到北京的本日就找到了工作。", "explanation": "这里应该用〈当天〉。“本日”只指说话的今天，叙述过去某一天要用“当天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本日地比赛在下午开始。", "corrected_sentence": "本日的比赛在下午开始。", "error_description": "“地”误用：“本日”作定语修饰“比赛”，应用“的”；“地”只用于动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本日得晚会很热闹。", "corrected_sentence": "本日的晚会很热闹。", "error_description": "“得”误用：“本日”作定语修饰“晚会”，应用“的”；“得”用于动词或形容词后作补语，不能接在名词前，应说“本日的晚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da22dea1-403b-4169-9fdc-3ec4f56ad9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
