INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家的法律监督机关，负责检查案件并提起公诉。", "primary_collocate": null, "pronunciation": "jiǎn chá yuàn", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "检察院负责检查案件，也负责提起公诉。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子已经交给检察院了。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院认为他犯了法，决定起诉他。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院的工作人员在查看材料。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到检察院去举报那家公司。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院可以监督警察和法院的工作。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把证据送到了检察院。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院提起公诉后，法院开始审判。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥大学毕业后在检察院工作。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院昨天公布了案件的结果。", "target_word": "检察院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "人民检察院", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家法律监督机关，查案并提起公诉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "检察院", "is_correct": true, "explanation": "检察院（jiǎn chá yuàn）是国家的法律监督机关，即题目所读的词。"}, {"text": "检查员", "is_correct": false, "explanation": "检查员（jiǎn chá yuán）：末字「员」为第二声 yuán，与「院」yuàn（第四声）声调不同，意思是检查人员。"}, {"text": "监察院", "is_correct": false, "explanation": "监察院（jiān chá yuàn）：首字「监」为第一声，与「检」jiǎn（第三声）声调不同，意思是监察机关，不是检察机关。"}, {"text": "检察员", "is_correct": false, "explanation": "检察员（jiǎn chá yuán）：末字「员」yuán（第二声）与「院」yuàn（第四声）声调不同，意思是检察工作人员。"}], "explanations": {"检察院": "检察院（jiǎn chá yuàn）是国家的法律监督机关，即题目所读的词。", "检查员": "检查员（jiǎn chá yuán）：末字「员」为第二声 yuán，与「院」yuàn（第四声）声调不同，意思是检查人员。", "监察院": "监察院（jiān chá yuàn）：首字「监」为第一声，与「检」jiǎn（第三声）声调不同，意思是监察机关，不是检察机关。", "检察员": "检察员（jiǎn chá yuán）：末字「员」yuán（第二声）与「院」yuàn（第四声）声调不同，意思是检察工作人员。"}, "sentence_index": null, "correct_answer": "检察院"}, "level_3": {"options": [{"text": "法院", "is_correct": false, "explanation": "语义：法院负责审判，不负责提起公诉，与后半句“提起公诉”不合。"}, {"text": "检察院", "is_correct": true, "explanation": "正确：检察院负责检查案件，也负责提起公诉。"}, {"text": "律师事务所", "is_correct": false, "explanation": "语义：律师事务所为当事人服务，不检查案件，也不提起公诉。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不检查案件，也不提起公诉，与前文语境不合。"}], "explanations": {"法院": "语义：法院负责审判，不负责提起公诉，与后半句“提起公诉”不合。", "检察院": "正确：检察院负责检查案件，也负责提起公诉。", "律师事务所": "语义：律师事务所为当事人服务，不检查案件，也不提起公诉。", "医院": "语义：医院不检查案件，也不提起公诉，与前文语境不合。"}, "sentence_index": 0, "correct_answer": "检察院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "检察院判了他三年徒刑。", "explanation": "这里应该用〈法院〉。判处刑罚由法院负责，检察院负责监督和提起公诉，不作判决。"}, {"text": "检察院负责执行刑罚。", "explanation": "这里应该用〈监狱〉。执行刑罚由监狱负责，检察院负责监督和提起公诉，不执行刑罚。"}, {"text": "检察院在大街上巡逻。", "explanation": "这里应该用〈警察〉。街头巡逻由警察负责，检察院不做这项工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超市", "is_correct": false, "explanation": "语义：超市不接收案件证据，“警察把证据送到了超市”与语境不合。"}, {"text": "检察院", "is_correct": true, "explanation": "正确：警察把证据送到了检察院。"}, {"text": "垃圾站", "is_correct": false, "explanation": "语义：垃圾站不接收证据，与“警察送证据”的语境不合。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不接收案件证据，“警察把证据送到了理发店”与语境不合。"}], "explanations": {"超市": "语义：超市不接收案件证据，“警察把证据送到了超市”与语境不合。", "检察院": "正确：警察把证据送到了检察院。", "垃圾站": "语义：垃圾站不接收证据，与“警察送证据”的语境不合。", "理发店": "语义：理发店不接收案件证据，“警察把证据送到了理发店”与语境不合。"}, "sentence_index": 6, "correct_answer": "检察院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "检察院当庭宣布休庭。", "explanation": "这里应该用〈法官〉。当庭宣布休庭由法官决定，检察院不主持庭审的休庭。"}, {"text": "检察院给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病是医生的工作，检察院是法律监督机关，不看病。"}, {"text": "被告请了检察院为自己辩护。", "explanation": "这里应该用〈律师〉。为被告辩护由律师负责，检察院是公诉机关，不替被告辩护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们市有一位检察院。", "corrected_sentence": "我们市有一个检察院。", "error_description": "错误在量词。“位”用于人，不能用来计量机构“检察院”；应说“一个检察院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过一把检察院。", "corrected_sentence": "我去过一次检察院。", "error_description": "错误在量词。“把”用于有柄的器物，不能用来计量“检察院”；应说“去过一次检察院”，“去过一把检察院”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
